// ==========================================
// ★ K 의 방 — S등급 직업 갈림길 · 연결
// 협상가 · 결속술사 · 견습 기사 · 신호수 · 표사
// 연결: 사냥터에도 셈과 손은 남는다 — 사람을 붙들고, 값을 치르고, 데려가는 쪽
// ==========================================

// ------------------------------------------
// 협상가 · 자원 없음
// ------------------------------------------
kJob('negotiator', 'S', [

{ at:'S', t:'길 가운데 — 거저 놓인 고기',
  x:`길 한가운데에 작은 짐승이 놓여 있다. 갓 죽었다. 상처는 목에 하나뿐이다.<br><br>
    먹다 만 것이 아니다. 먹지 않고 가져다 놓은 것이다. 길목에, 잘 보이게.<br>
    거저 놓인 것은 선물이 아니라 첫 제안이다. 그리고 첫 제안은 언제나 내놓은 쪽에 유리하다.<br><br>
    어둠 어딘가에서 내놓은 쪽이 대답을 기다린다. 숨소리가 참을성 있게 길다.`,
  o:[
    { l:'① 첫 제안은 받지 않는다 — 길을 바꾼다.', k:'bond', dc:23, wake:1,
      ok:`고기를 보지 않은 척 돌아섰다. 팀을 벽 쪽 길로 붙였다.<br><br>등 뒤에서 고기가 끌려가는 소리가 났다. 빠르게, 신경질적으로. 값을 부른 쪽이 제 값을 도로 걷어 갔다.<br><br>첫 제안을 거절하는 손이 더는 떨리지 않는다. 사냥터의 흥정도 흥정이다. 공짜를 받는 순간, 다음 값은 이쪽 몸으로 부른다. 그 셈이 뼈에 새겨졌다.`,
      ng:`돌아선 길이 젖어 있었다. 발자국이 남는 땅이다.<br><br>어둠 속에서 무엇이 그 발자국을 하나씩 밟으며 따라왔다. 거절한 값을 재는 걸음이다.<br>한참을 돌아서야 마른 땅을 밟았다. 아무도 말을 하지 않았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 고기를 집어 길 밖 먼 곳에 던진다 — 흥정 자리를 옮긴다.', k:'evade', dc:24,
      ok:`고기를 집어 비탈 아래로 멀리 던졌다. 떨어지는 소리가 나기 전에 팀을 반대쪽으로 몰았다.<br><br>어둠이 소리 쪽으로 쏠리는 게 느껴졌다. 제안을 옮겨 받은 자리로.<br>그쪽에서 무엇이 실망하는 소리가 났다. 흥정 자리를 바꾸면 판을 깐 쪽이 불리해진다.`,
      ng:`집는 순간 알았다. 고기가 아직 따뜻하다. 냄새가 소매에 뱄다.<br><br>던지고 달렸지만 어둠은 고기 쪽으로 가지 않았다. 소매 쪽으로 왔다.<br>외투를 벗어 버리고서야 떨어져 나갔다. 팔에 긁힌 자국이 세 줄 남았다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S', t:'끌고 간 자국 — 산 채로 가져가는 것',
  x:`바닥에 끌린 자국이 길게 나 있다. 자국 머리에 물통이 떨어져 있다. 뚜껑이 잠긴 채다.<br><br>
    피가 거의 없다. 죽여서 끌고 간 게 아니라 산 채로 가져갔다.<br>
    산 채로 가져가는 짐승은 당장 배가 고프지 않은 짐승이다. 모아 두는 쪽이다.<br><br>
    모아 둔 것은 창고다. 그리고 창고가 있는 상대와는, 이론상, 거래가 된다.`,
  o:[
    { l:'① 자국을 따라가 산 사람을 값으로 되찾는다.', k:'bond', dc:25,
      doom:{ title:'저장고의 셈', what:'어둠 속 저장고로 끌려갑니다', dc:19, sec:45,
        text:`자국 끝에 움푹한 어둠이 있었다. 안쪽에서 숨소리가 여럿 났다. 느리고 끈적한 숨.<br><br>말린 고기를 꺼내 바닥에 폈다. 저쪽 것과 바꾸자는 뜻으로.<br>어둠이 고기를 봤다. 그리고 이쪽을 봤다. 더 신선한 쪽을 고르는 눈이었다.<br><br>발목에 무엇이 감겼다. 창고 주인은 바꾸지 않는다. 들여놓을 뿐이다.`,
        dieText:`팀원들이 들어갔을 때 움푹한 어둠은 비어 있었다. 더 깊은 안쪽으로 자국이 이어졌다.<br><br>펴 놓은 말린 고기는 그대로 있었다. 손도 대지 않았다.<br>며칠 뒤 다른 팀이 그 안쪽에서 물통을 또 하나 주웠다. 뚜껑이 잠긴 채였다.` },
      ok:`자국 끝 움푹한 어둠 앞에 말린 고기를 폈다. 그리고 물러나 기다렸다.<br><br>오래 걸렸다. 어둠이 고기를 끌어들였다. 잠시 뒤, 안쪽에서 사람이 기어 나왔다. 다른 팀 막내다. 묶이지도 물리지도 않았다. 그냥 넣어 두었던 것이다.<br><br>맞바꾼 게 아니다. 창고가 꽉 찼을 뿐이다. 그래도 사람이 나왔다. 셈이야 어떻든.`,
      win:{ exp:24, dream:3 } },
    { l:'② 위치만 외워 두고 팀을 먼저 내보낸다.', k:'steady', dc:23,
      ok:`자국의 방향과 갈래를 머리에 넣었다. 기둥 세 개, 꺾인 배관 하나.<br><br>팀을 먼저 통로 밖으로 내보내고 마지막에 나왔다. 나가는 길에 벽에 손톱으로 금을 그었다.<br>나중에 구조조가 그 금을 따라 들어갔다. 둘을 데리고 나왔다. 하나는 사흘 만이었는데 살아 있었다.`,
      ng:`외우는 사이 등 뒤 팀원들이 먼저 움직였다. 대형이 풀렸다.<br><br>어둠 속에서 무엇이 그 틈을 셌다. 맨 뒤 팀원이 넘어지며 발목을 접질렸다.<br>업고 나왔다. 자국의 갈래는 반밖에 못 외웠다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S', t:'쉬는 자리 — 마지막 끼니의 셈',
  x:`먹을 것이 한 줌 남았다. 다섯이고, 길은 반도 못 왔다.<br><br>
    다들 제 몫을 사양한다. 사양은 셈이 아니다. 사양하는 팀은 셈을 안 한 팀이다.<br>
    굶은 사람은 발이 늦고, 늦은 발은 맨 뒤에 서고, 맨 뒤는 이 바닥에서 값이 제일 싸다.<br><br>
    누가 먹을지가 아니라, 누가 굶으면 전부가 비싸지는지를 세어야 한다.`,
  o:[
    { l:'① 제일 지친 사람에게 두 몫을 준다 — 대열의 값으로.', k:'bond', dc:23,
      ok:`제일 눈이 풀린 팀원 앞에 두 몫을 놓았다. 네가 좋아서가 아니라 네 발이 제일 싸졌기 때문이라고 말했다.<br><br>그 말에 그 팀원이 웃었다. 먹었다. 다 먹었다.<br>한 시간 뒤 대열은 다시 한 덩어리로 걸었다. 맨 뒤가 없는 대열은 물 데가 없다.`,
      ng:`두 몫을 받은 팀원이 울기 시작했다. 소리 없이, 길게.<br><br>우는 숨은 멀리 간다. 서둘러 자리를 접고 떠났다.<br>먹인 것은 맞다. 다만 운 값이 더 들었다.`,
      win:{ exp:16, dream:2, item:'말린 고기' }, lose:{ mind:-15, spirit:-17 } },
    { l:'② 반만 먹고 반은 모두 보이는 곳에 매단다.', k:'fix', dc:23,
      ok:`남은 반을 천에 싸서 배낭 꼭대기, 다섯이 다 보이는 자리에 매달았다.<br><br>남은 게 있다는 사실은 위장이 아니라 머리를 먹인다. 걸음이 덜 끌렸다.<br>그 반은 끝까지 안 먹었다. 나갈 때까지 매달려 있었다. 그거면 됐다.`,
      ng:`매단 천에서 냄새가 샜다. 밤새 무엇이 야영지 가장자리를 돌았다.<br><br>아침에 천은 그대로였는데 매단 끈에 잇자국이 나 있었다. 높이가 어깨쯤이었다.<br>그다음부터는 아무도 그 천을 쳐다보지 않았다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-16, spirit:-18 } },
    { l:'③ 제 몫을 내놓고 나가서 갚으라고 한다.', k:'bond', dc:24, wake:1,
      ok:`제 몫을 가운데 놓았다. 거저가 아니라고 했다. 나가서 밥 한 끼로 갚으라고. 다섯 다.<br><br>빚을 진 사람은 빚을 갚을 때까지 안 죽으려 든다. 다섯이 다 이쪽에 한 끼씩 빚졌다.<br><br>대열이 달라졌다. 서로를 보는 눈에 셈이 하나씩 들어섰다. 갚을 때까지는 다 같이 나간다는 셈. 빚으로 사람을 묶는 법을 배웠다. 이 바닥에서 제일 질긴 끈이다.`,
      ng:`내놓은 몫을 아무도 안 받았다. 빚지기 싫은 것이다.<br><br>몫은 가운데서 식었다. 결국 싸서 도로 넣었다.<br>굶은 배보다 거절당한 셈이 더 오래 쓰렸다.`,
      win:{ exp:23, dream:3, spirit:6 }, lose:{ mind:-17, spirit:-19 } }
  ] },

{ at:'S', t:'몰이 — 등짐 하나의 시간',
  x:`뒤에서 몰고 있다. 소리를 내서, 일부러, 한쪽으로.<br><br>
    몰리는 쪽은 값을 두 번 치른다. 달리는 값과, 몰린 자리에서 치르는 값.<br>
    달아나며 셈을 했다. 이쪽이 가진 것 중 저쪽 발을 멈출 만한 것.<br><br>
    등짐 하나. 고기와 기름과 땀이 밴 천. 시간으로 치면 얼마짜리인가.`,
  o:[
    { l:'① 짐 하나를 풀어 길에 두고 시간을 산다.', k:'bond', dc:24,
      ok:`달리면서 등짐 하나를 끌러 길 가운데 떨궜다. 입을 벌려서, 속이 보이게.<br><br>뒤쫓던 소리가 그 자리에서 멎었다. 뒤지는 소리. 찢는 소리.<br>그 사이 꺾인 통로 둘을 지났다. 짐 값으로 산 시간이다. 비싸게 샀지만 제값이었다.`,
      ng:`떨군 짐을 저쪽이 거들떠도 안 봤다. 원하는 게 짐이 아니라는 뜻이다.<br><br>맨 뒤 팀원의 어깨를 무엇이 스쳤다. 천이 길게 찢겼다. 살도 조금.<br>막다른 데 몰리기 직전에 옆 틈으로 빠졌다. 짐만 거저 버렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 아무것도 주지 않고 좁은 틈으로 꺾는다.', k:'evade', dc:25,
      ok:`몰리는 방향 반대쪽 벽에 틈이 있었다. 어깨를 빼고 하나씩 밀어 넣었다.<br><br>몰이는 넓은 데서 하는 사냥이다. 좁은 틈은 몰이의 셈 밖이다.<br>틈 너머에서 숨을 죽였다. 저쪽이 틈 앞을 두 번 오가다 갔다. 셈이 안 맞는 걸 못 견디는 걸음이었다.`,
      ng:`틈이 생각보다 좁았다. 셋째 팀원이 어깨가 끼었다.<br><br>빼내는 동안 몰던 것이 도착했다. 끼인 팀원의 다리를 긁고 지나갔다.<br>틈 너머로 다 들어가긴 했다. 피 냄새가 틈 안까지 따라 들어왔다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-31, spirit:-17 } }
  ] },

{ at:'S', t:'우는 소리 — 값을 부르는 울음',
  x:`앞쪽 어둠에서 우는 소리가 난다. 사람 울음이다. 어린 울음.<br><br>
    팀원 하나가 걸음을 빨리한다. 붙들었다. 울음을 다시 들어 보라고 했다.<br>
    같은 마디가 같은 길이로 돈다. 숨이 모자라는 데가 없다. 우는 사람은 숨이 모자란다.<br><br>
    이건 울음이 아니라 호가(呼價)다. 사람이라는 값을 부르고, 오는 쪽이 값을 치른다.`,
  o:[
    { l:'① 소리에 돌을 던져 위치부터 산다.', k:'sense', dc:24,
      ok:`돌을 울음 왼쪽으로 던졌다. 울음이 끊기고, 돌 떨어진 자리로 무엇이 미끄러지는 소리가 났다.<br><br>크기를 쟀다. 미끄러지는 길이가 사람 셋은 됐다.<br>울음이 다시 시작되기 전에 오른쪽 벽을 타고 지났다. 울음은 한참 뒤에야 다시 돌았다. 조금 더 서럽게.`,
      ng:`돌이 빗나가 쇠를 때렸다. 맑은 소리가 통로를 다 돌았다.<br><br>울음이 뚝 그쳤다. 그쪽이 이쪽 위치를 샀다. 공짜로.<br>한 시간을 꺾고 또 꺾어서야 따돌렸다. 다리가 다 풀렸다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-17, spirit:-16 } },
    { l:'② 울음의 임자와 직접 맞흥정하러 간다.', k:'bond', dc:25,
      doom:{ title:'호가', what:'우는 소리 쪽으로 끌려갑니다', dc:18, sec:50,
        text:`울음 앞까지 가서 말했다. 사람 값은 안 치른다고. 다른 값을 부르라고.<br><br>울음이 멎었다. 그리고 이쪽 목소리로 다시 시작됐다. 방금 한 말을 그대로, 우는 억양으로.<br><br>목덜미에 차가운 것이 감겼다. 값을 부르러 온 사람이 다음 호가가 됐다.`,
        dieText:`팀원들이 달려갔을 때 울음은 두 겹이 되어 있었다.<br><br>어린 울음 하나, 어른 울음 하나. 어른 쪽은 아는 목소리였다.<br>그 통로를 지나는 팀들은 이제 두 사람 값을 부르는 소리를 듣는다. 가끔 값을 치르러 가는 사람이 있다.` },
      ok:`울음 앞까지 가서 말했다. 사람 값은 안 치른다고. 고기면 고기, 불이면 불.<br><br>울음이 멎었다. 어둠이 한동안 셈을 했다. 그리고 바닥에 무엇을 굴려 보냈다. 물통이다. 다른 팀 것.<br>고기 한 줌을 놓고 물통을 받았다. 울음은 그날 밤부터 고기 익는 냄새를 흉내 내기 시작했다. 호가를 바꾼 것이다. 사람 말고도 팔리는 게 있다는 걸 가르친 셈이다.`,
      win:{ exp:23, dream:3, item:'맑은 물' } }
  ] },

{ at:'S', t:'다친 팀의 제안 — 약값',
  x:`다른 팀이 벽에 붙어 쉬고 있다. 다섯 중 둘이 상했다. 하나는 어깨를 물렸다.<br><br>
    그쪽 반장이 지도를 꺼내 보인다. 아래층 내려가는 길이 그려져 있다. 약과 바꾸자고 한다.<br>
    지도는 진짜 같다. 접힌 자국이 손때로 반들거린다.<br><br>
    다만 물린 어깨의 천이 너무 깨끗하다. 피가 멎은 지 오래된 상처라는 뜻이다. 급한 건 약이 아니다.`,
  o:[
    { l:'① 그쪽이 정말 사려는 게 뭔지 본다.', k:'gaze', dc:24,
      ok:`반장의 눈을 봤다. 약을 보는 눈이 아니다. 이쪽 머릿수를 세는 눈이다.<br><br>원하는 건 약이 아니라 동행이다. 여섯 눈보다 열 눈이 밤을 덜 무서워하니까.<br>지도 값으로 약 반, 동행 반나절을 쳐 줬다. 반장이 처음으로 웃었다. 제값을 쳐 주는 상대를 만난 웃음이다.`,
      ng:`눈을 읽는 걸 반장이 알아챘다. 얼굴이 닫혔다.<br><br>흥정은 깨졌다. 그쪽은 지도를 도로 접고 일어섰다.<br>떠나는 그쪽 맨 뒤에서 물린 팀원이 이쪽을 오래 돌아봤다. 그 눈이 밤새 생각났다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 약값으로 지도 말고 그쪽 대열의 뒷자리를 받는다.', k:'bond', dc:24, wake:1,
      ok:`약을 건네며 말했다. 지도는 됐고, 반나절 같이 가되 이쪽이 뒤에 서겠다고.<br><br>반장이 이상한 값이라는 얼굴을 했다. 그래도 받았다. 약이 급하니까.<br>반나절, 앞선 그쪽이 길을 다 밟아 줬다. 헐거운 바닥도, 우는 소리 나는 갈림길도.<br><br>자리가 값이라는 걸 배웠다. 사냥터에서 대열의 앞뒤는 돈보다 비싸다. 그 셈을 입 밖에 안 내고 치르는 법도 같이 배웠다.`,
      ng:`뒷자리를 달라는 말에 반장의 눈이 가늘어졌다. 셈을 들킨 것이다.<br><br>그쪽은 약만 받고 지도를 안 줬다. 흥정이 반만 된 채 갈라섰다.<br>그 팀이 어느 쪽으로 갔는지는 모른다. 다만 그날 밤 멀리서 호루라기 소리가 났고, 곧 그쳤다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-21 } }
  ] },

{ at:'S', t:'세는 눈 — 다섯을 아는 것',
  x:`따라붙은 지 오래다. 덮치지는 않는다. 기다린다.<br><br>
    쉴 때마다 어둠의 같은 높이에서 숨소리가 난다. 다섯이 모이면 조용하고, 하나가 떨어지면 숨이 빨라진다.<br>
    셀 줄 아는 것이다. 다섯은 비싸고 하나는 싸다는 셈까지 안다.<br><br>
    셈을 아는 상대는 셈으로 속일 수 있다.`,
  o:[
    { l:'① 둘씩 붙여 걸려 다섯을 넷으로 보이게 한다.', k:'bond', dc:24,
      ok:`제일 작은 팀원을 제일 큰 팀원 앞에 바싹 붙였다. 발을 맞추게 했다. 그림자가 하나로 겹치게.<br><br>어둠의 숨이 흐트러졌다. 넷인데 발소리는 다섯. 셈이 안 맞는 것이다.<br>셈이 안 맞는 먹이는 비싸다. 숨소리가 멀어졌다. 더 싼 셈을 찾으러 갔다.`,
      ng:`붙여 걷던 둘의 발이 엉켰다. 하나가 넘어지며 혼자가 됐다.<br><br>어둠이 그 순간을 샀다. 숨이 코앞까지 왔다.<br>넷이 소리를 지르며 달려들어 간신히 물렸다. 넘어진 팀원 등에 긴 긁힘이 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-29, mind:-15 } },
    { l:'② 배낭과 외투로 여섯째를 만들어 세운다.', k:'fix', dc:23,
      ok:`배낭에 외투를 입히고 막대를 꽂아 갈림길에 세웠다. 여섯째다.<br><br>어둠이 오래 셌다. 다섯에 하나가 늘어난 셈. 늘어나는 먹이는 이상한 먹이다.<br>여섯째가 덮치는 소리를 뒤로 들으며 빠져나왔다. 외투 값으로 저쪽의 속도를 봤다. 그 속도는 안 보는 게 나았다.`,
      ng:`여섯째가 너무 얌전했다. 숨을 안 쉬니까.<br><br>어둠은 여섯째를 지나쳐 진짜 쪽으로 왔다. 급하게 짐을 버리고 뛰었다.<br>외투도 배낭도 거저 날렸다. 배운 것도 없이.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-17, spirit:-18 } },
    { l:'③ 하나가 싼 척 미끼로 서고 넷이 노린다.', k:'hide', dc:26,
      ok:`제일 빠른 팀원이 절뚝이는 척 뒤처졌다. 넷은 기둥 뒤 어둠에 녹았다.<br><br>싼 값에 어둠이 달려들었다. 네 방향에서 동시에 때렸다. 무엇인지 볼 틈도 없이 저쪽이 빠졌다.<br>바닥에 검은 피가 몇 방울 떨어져 있었다. 밟지 않고 지났다. 이 바닥 피는 믿는 게 아니다.`,
      ng:`미끼가 너무 쌌다. 어둠이 의심했다.<br><br>덮치는 대신 미끼와 매복 사이를 갈랐다. 넷과 하나가 끊겼다.<br>다시 합치는 데 한참 걸렸다. 미끼 섰던 팀원은 그동안 혼자 어둠과 눈을 맞추고 있었다. 돌아온 뒤로 말수가 줄었다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-33, mind:-19 } }
  ] },

{ at:'S', t:'발소리 흥정 — 거리의 값',
  x:`걸으면 걷고, 멈추면 멈춘다. 어둠 속 발소리가 이쪽 박자를 그대로 받는다.<br><br>
    가까워지지도 멀어지지도 않는다. 열 걸음. 꼭 열 걸음.<br>
    거리를 흥정하는 중이다. 저쪽은 열 걸음이 제 값이라고 부르고 있다.<br><br>
    받아들이면 열 걸음은 아홉이 되고, 여덟이 된다. 호가는 깎으라고 있는 것이다.`,
  o:[
    { l:'① 멈춰 서서 먼저 한 걸음 다가선다 — 값을 되부른다.', k:'bond', dc:25,
      doom:{ title:'열 걸음의 셈', what:'어둠 속으로 끌려갑니다', dc:19, sec:44,
        text:`한 걸음 다가섰다. 어둠이 멈칫했다. 두 걸음째에 알았다. 저쪽 호가는 열 걸음이 아니었다.<br><br>열 걸음은 도약 거리였다. 아홉 걸음부터는 저쪽 손안이다.<br><br>바닥이 사라졌다. 끌리는 몸 밑으로 돌이 빠르게 지나간다. 값을 되부르러 간 사람이 낙찰됐다.`,
        dieText:`발소리는 그날부터 들리지 않았다.<br><br>대신 열 걸음 거리에서 숨소리가 둘이 났다. 하나는 길고 하나는 짧았다.<br>짧은 쪽은 가끔 걸음을 맞추려는 것처럼 박자를 탔다. 버릇이란 질긴 것이다.` },
      ok:`한 걸음 다가서며 바닥을 세게 굴렀다. 다섯이 같이, 한 번에.<br><br>어둠이 두 걸음 물러났다. 열둘. 되부른 값이 먹혔다.<br>그 뒤로 발소리는 열두 걸음 밖에서만 따라왔다. 비싼 먹이는 건드리기 전에 오래 센다. 세는 동안 이쪽은 걷는다.`,
      win:{ exp:23, dream:3, spirit:7 } },
    { l:'② 박자를 받아 주며 벽을 따라 빠져나간다.', k:'evade', dc:24,
      ok:`박자를 흐트리지 않았다. 열 걸음 값을 받아들이는 척하며 벽을 탔다.<br><br>벽이 꺾이는 자리마다 걸음 하나를 삼켰다. 열이 열하나가 되고 열둘이 됐다. 저쪽이 눈치채지 못하게 천천히.<br>갈림길에서 박자를 놓고 달렸다. 뒤에서 발소리가 셈을 다시 하는 사이 층계를 탔다.`,
      ng:`걸음 하나를 삼키다 돌을 찼다. 박자가 깨졌다.<br><br>깨진 박자는 깨진 흥정이다. 발소리가 단숨에 다섯 걸음으로 좁혔다.<br>달렸다. 층계에서 맨 뒤 팀원이 굴렀다. 부축해서 마저 달렸다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-27, mind:-16 } }
  ] },

{ at:'S', t:'죽은 탐사대의 장부',
  x:`벽에 기대 마른 시체가 앉아 있다. 품에 수첩이 있다.<br><br>
    펼치니 날짜와 물건이 적혀 있다. 첫날 — 고기 반. 둘째 날 — 고기 반, 물 한 모금. 셋째 날 — 신발 한 짝.<br>
    주는 값이 날마다 조금씩 올랐다. 마지막 장은 비어 있다. 쓸 사람이 없어서가 아니라, 줄 것이 없어서.<br><br>
    장부가 있다는 건 받으러 오는 쪽이 있다는 뜻이다. 오늘 밤에도.`,
  o:[
    { l:'① 장부를 이어 쓴다 — 오늘 줄 것을 먼저 적는다.', k:'bond', dc:24, wake:1,
      ok:`빈 장에 적었다. 오늘 — 말린 고기 한 줄. 그리고 그 고기를 시체 옆에 놓았다.<br><br>밤에 무엇이 왔다. 고기를 집고, 수첩 위에 오래 머물렀다. 글을 읽는 건지 냄새를 읽는 건지.<br>아침에 고기는 없고 수첩은 덮여 있었다. 받아 간 것이다. 적힌 만큼만.<br><br>값은 받는 쪽이 아니라 적는 쪽이 정한다는 것. 죽은 사람이 마지막 장으로 가르쳐 줬다. 이제 셈은 이쪽 글씨로 간다.`,
      ng:`적어 놓고 잤다. 밤에 수첩 넘기는 소리가 났다.<br><br>아침에 보니 이쪽이 적은 줄 밑에 금이 하나 그어져 있었다. 길게, 빗금으로.<br>글씨가 바뀐 걸 안 것이다. 새 상대에게는 새 값. 그날 밤부터 받으러 오는 숨소리가 둘로 늘었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-19, spirit:-22 } },
    { l:'② 장부를 태워 빚을 끊는다.', k:'steady', dc:25,
      ok:`수첩을 태웠다. 재가 다 식을 때까지 지켰다.<br><br>밤에 받으러 온 것이 시체 주변을 오래 돌았다. 장부 없는 거래처 앞에서 서성이는 걸음이었다.<br>새벽에 갔다. 거래는 장부가 있어야 거래다. 종이 한 권 태운 값으로 빚 하나가 지워졌다.`,
      ng:`태우는 연기가 너무 멀리 갔다. 받으러 올 것이 일찍 왔다.<br><br>장부가 재가 되는 걸 그것도 봤다. 그날 밤 그것은 장부 없이 받아 갔다. 배낭 하나를 통째로.<br>적은 만큼만 받아 가던 것이 이제 제 손으로 집는다. 끊은 건 빚이 아니라 한도였다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, spirit:-24 } }
  ] },

{ at:'S', t:'물가의 휴전',
  x:`고인 물가에 발자국이 겹겹이다. 큰 것, 작은 것, 갈라진 것, 사람 것.<br><br>
    뜯긴 흔적이 없다. 물가에서는 아무도 아무것도 사냥하지 않았다.<br>
    마시는 자리의 휴전. 셈 중에 제일 오래된 셈이다. 목마름 앞에서는 이빨도 값을 깎는다.<br><br>
    다만 휴전에는 늘 글자 없는 조항이 있다. 오래 머무는 쪽이 어기는 쪽이다.`,
  o:[
    { l:'① 휴전의 박자에 맞춰 물을 뜬다 — 마시고, 뜨고, 바로 뜬다.', k:'bond', dc:24,
      ok:`한 사람씩 물가에 댔다. 마시고, 물통 채우고, 물러나고. 머문 숨은 열을 안 넘겼다.<br><br>건너편 어둠에서도 무엇이 마시고 있었다. 서로 안 보는 척했다. 그게 조항이다.<br>다섯째까지 다 떴다. 물러날 때 건너편이 고개를 들었다. 눈이 마주쳤고, 둘 다 아무 일도 안 했다. 휴전은 그렇게 지켜진다.`,
      ng:`넷째까지는 박자가 맞았다. 다섯째가 물통을 놓쳤다. 첨벙 소리.<br><br>건너편 어둠이 일어섰다. 일어서는 데만 숨 세 번이 걸리는 크기였다.<br>물통을 버리고 물러났다. 휴전을 깬 건 아니다. 다만 오늘 치 물은 반밖에 못 떴다.`,
      win:{ exp:16, dream:2, item:'맑은 물' }, lose:{ hp:-26, mind:-14 } },
    { l:'② 휴전을 믿지 않고 상류로 돌아 오른다.', k:'sense', dc:23,
      ok:`물가를 등지고 물소리를 거슬러 올랐다. 바위 틈에 가는 물줄기가 있었다.<br><br>좁아서 한 사람씩밖에 못 받았지만, 발자국이 없는 물이었다.<br>다 채우고 내려오는 길에 물가 쪽에서 물 튀는 소리와 짧은 비명이 들렸다. 어느 팀이 조항을 어긴 모양이다. 휴전은 어기는 쪽 값으로 유지된다.`,
      ng:`상류는 길이 험했다. 바위에서 팀원 하나가 미끄러져 정강이가 깨졌다.<br><br>물은 받았다. 피 몇 방울이 물줄기에 섞여 내려갔다.<br>하류의 휴전 자리까지, 그 몇 방울이 흘러갔을 것이다. 서둘러 그 층을 떴다.`,
      win:{ exp:14, dream:2, item:'맑은 물' }, lose:{ hp:-27, spirit:-16 } }
  ] },

{ at:'S', t:'몰린 것 — 출구 없는 상대',
  x:`갈림길 구석에 작은 것이 몰려 있다. 이쪽 무릎 높이. 이빨은 바늘 같고, 숨이 빠르다.<br><br>
    팀원이 몽둥이를 들었다. 지금 치면 잡는다.<br>
    다만 몰린 것은 값을 안 듣는다. 출구 없는 상대는 흥정이 안 되고, 흥정이 안 되는 상대는 전부를 건다.<br>
    그리고 저 작은 숨이 지르는 비명이 얼마나 멀리 갈지, 이 어둠에서 누가 그 비명을 듣고 있을지.`,
  o:[
    { l:'① 길을 반 내주고 물러날 틈을 연다.', k:'bond', dc:23, wake:1,
      ok:`몽둥이를 내리게 하고 벽 쪽으로 다 붙었다. 구석과 어둠 사이에 길이 열렸다.<br><br>작은 것이 한 숨 재더니 그 길로 쏘아져 나갔다. 소리 없이. 비명도, 피 냄새도 없이.<br><br>출구를 주는 것도 흥정이라는 걸 배웠다. 상대가 전부를 걸기 전에 물러날 값을 깔아 주는 것. 사람한테도 똑같이 먹히는 수다. 그게 이 장사의 바닥 패다.`,
      ng:`틈을 열었는데 작은 것이 길이 아니라 사람 사이로 뛰었다.<br><br>겁에 질린 것은 셈을 못 한다. 팀원 하나가 종아리를 물렸다. 바늘 이빨이라 깊지는 않은데 많았다.<br>작은 것은 사라졌다. 비명은 안 질렀다. 그게 그나마 남는 장사였다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 소리 지르기 전에 먼저 끝낸다.', k:'break', dc:25,
      ok:`몽둥이가 비명보다 빨랐다. 한 번에 끝났다.<br><br>작지만 고기는 고기다. 뒷다리 쪽을 발라 챙겼다.<br>다만 손질하는 내내 어둠이 조용했다. 너무 조용했다. 빨리 싸서 자리를 떴다.`,
      ng:`첫 매가 빗나갔다. 작은 것이 비명을 질렀다. 바늘로 귀를 쑤시는 소리.<br><br>멀리서 대답이 왔다. 낮고, 큰 대답.<br>작은 것을 놓아두고 뛰었다. 비명 값은 생각보다 훨씬 비쌌다.`,
      win:{ exp:15, dream:2, item:'짐승 고기' }, lose:{ mind:-15, spirit:-20 } }
  ] },

{ at:'S1', t:'에어록 — 한 번 남은 순환',
  x:`에어록 앞에 두 팀이 섰다. 아홉 사람. 전광판의 숫자는 순환 한 번 치 전력만 남았다고 한다.<br><br>
    안에 들어가는 건 다섯이 한계다. 문은 한 번 열리고, 한 번 닫히고, 그걸로 끝이다.<br>
    복도 끝 어둠에서는 아까부터 긁는 소리가 다가온다. 느리게, 꾸준히.<br><br>
    아홉이 다 문을 본다. 누군가 셈을 해야 한다. 셈은 늘 이쪽 몫이다.`,
  o:[
    { l:'① 다친 사람부터 섞어 태우고, 남는 쪽에 불을 다 모아 준다.', k:'bond', dc:24,
      ok:`양 팀의 다친 둘과 제일 어린 둘, 그리고 저쪽 반장을 태웠다. 반장이 머뭇대자 말했다. 남는 쪽 값은 불로 받겠다고.<br><br>남는 넷에게 두 팀의 손전등과 기름이 다 모였다. 어둠을 살 수 있는 전부.<br>문이 닫히고, 남은 넷이 불을 등지고 섰다. 긁는 소리는 불 앞에서 오래 머뭇댔다. 다음 순환까지, 불은 버텼다.`,
      ng:`셈을 읽어 주는데 저쪽 막내가 울음을 터뜨렸다. 남는 쪽에 제 이름이 있어서.<br><br>울음소리에 긁는 소리가 빨라졌다. 셈이고 뭐고 다 같이 문으로 몰렸다.<br>문은 다섯에서 안 닫혔다. 일곱에서 억지로 닫혔다. 경보가 울었고, 남은 둘은 비상 사다리로 뛰었다. 나중에 합류했을 때 둘 다 말을 안 했다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-19, spirit:-23 } },
    { l:'② 순서를 제비로 정한다 — 제비는 이쪽이 만든다.', k:'luck', dc:24,
      ok:`전선 피복을 잘라 아홉 가닥을 만들었다. 다섯 긴 것, 넷 짧은 것.<br><br>다만 다친 둘 손에는 긴 것이 가게 쥐는 법을 바꿨다. 제비는 공평해 보이는 게 일이지 공평한 게 일이 아니다.<br>아무도 셈을 의심하지 않았다. 운이 정한 일에는 원망이 안 붙는다. 그게 제비 값이다.`,
      ng:`제비를 섞다 손이 떨렸다. 다친 사람 하나가 짧은 걸 뽑았다.<br><br>바꿔 주겠다는 사람이 셋 나왔다. 셈이 도로 엉켰다.<br>결국 시간에 쫓겨 뒤엉킨 채로 탔다. 남은 쪽 눈빛이 문이 닫히는 내내 이쪽에 박혔다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-17, spirit:-19 } },
    { l:'③ 수동 개폐 손잡이를 맡아 맨 마지막에 남는다.', k:'steady', dc:25,
      ok:`안쪽 손잡이는 누가 돌려도 된다. 바깥 손잡이는 남는 사람이 돌려야 한다.<br><br>여덟을 보내고 손잡이를 돌렸다. 문이 닫히는 틈으로 긁는 소리가 모퉁이를 도는 게 보였다.<br>다음 순환은 반나절 뒤였다. 반나절을 배관 위에서 버텼다. 혼자 남는 값을 제 손으로 치르면, 적어도 셈은 깨끗하다.`,
      ng:`손잡이가 반쯤 돌다 걸렸다. 녹이다.<br><br>문이 덜 닫힌 채 멎었다. 안쪽 여덟이 다시 달라붙어 같이 돌렸다.<br>닫히긴 했다. 다만 긁는 소리가 그 틈에 코앞까지 왔었다. 숨이 돌아오는 데 한참 걸렸다.`,
      win:{ exp:17, dream:3, spirit:6 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'S1', t:'표본 단지의 값',
  x:`유리 벽 너머에 연구원이 하나 살아 있다. 마르고, 눈만 빛난다.<br><br>
    문 열림 번호를 알려 주겠다고 한다. 값은 표본 단지 하나. 깨지지 않은 것으로, 셋째 선반.<br>
    셋째 선반의 단지는 멀쩡하다. 안에 웅크린 것도 멀쩡하다. 가끔 자세를 바꾼다.<br><br>
    산 것을 값으로 부르는 거래는 늘 어딘가가 썩어 있다. 어디가 썩었는지 보고 받아야 한다.`,
  o:[
    { l:'① 단지를 안고 운반한다 — 값이니까.', k:'bond', dc:25,
      doom:{ title:'깨진 값', what:'단지 속 것에게 안긴 채 끌려갑니다', dc:19, sec:40,
        text:`단지를 가슴에 안고 걸었다. 안의 것이 자세를 바꿀 때마다 유리가 미지근해졌다.<br><br>문턱에서 발이 걸렸다. 금 가는 소리는 작았다. 안의 것이 나오는 소리는 더 작았다.<br><br>가슴에 안긴 채였다. 그것이 어깨를 감고, 등을 감고, 끌었다. 값이 배달꾼을 집어삼켰다.`,
        dieText:`유리 벽 너머 연구원은 그 광경을 끝까지 봤다.<br><br>그리고 메모지에 또박또박 적어 유리에 붙였다. 다음 팀에게 — 셋째 선반, 깨지지 않은 것으로.<br>값은 아직 수금되지 않았다. 거래는 열려 있다.` },
      ok:`단지를 천으로 감아 안았다. 안의 것이 움직일 때마다 걸음을 멈추고, 잠들면 걸었다.<br><br>유리 벽 투입구에 단지를 넣었다. 연구원이 단지를 받아 품에 안았다. 아이를 받듯이.<br>번호는 진짜였다. 문이 열렸다. 떠나며 돌아보니 연구원이 단지에 입을 대고 무어라 속삭이고 있었다. 썩은 자리는 거기였다. 안 보는 게 나았다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 단지 말고 저 사람이 정말 원하는 걸 본다.', k:'gaze', dc:24,
      ok:`연구원의 눈을 봤다. 단지를 말할 때만 눈이 산다. 연구가 아니라 그리움의 눈이다.<br><br>셋째 선반 단지의 기록표를 읽었다. 채집자 이름이 연구원과 같은 성이다.<br>단지 대신 기록표만 떼어 투입구에 넣었다. 연구원이 그걸 오래 읽고, 울고, 번호를 불러 줬다. 산 것은 선반에 남았다. 거래는 종이로 끝났다. 그게 서로 싼 값이었다.`,
      ng:`눈을 읽히는 걸 연구원이 알았다. 유리에 바싹 붙어 이쪽을 마주 읽었다.<br><br>오래 굶은 눈이 사람을 읽으면, 읽히는 쪽이 춥다.<br>번호는 못 받았다. 다른 길을 찾는 데 한나절이 들었다. 유리 두드리는 소리가 등 뒤에 오래 붙었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'S1', t:'숙주 — 시한의 흥정',
  x:`다른 팀 사내의 가슴 밑에서 무엇이 옮겨 다닌다. 천 위로도 보인다.<br><br>
    그쪽 팀원들이 총대를 세웠다. 지금 끝내자는 쪽과 아직 사람이라는 쪽.<br>
    사내는 제일 침착하다. 제 가슴을 내려다보며 묻는다. 얼마나 남았느냐고.<br><br>
    이 흥정의 양쪽은 겁과 정이다. 둘 다 값을 모른다. 값은 시간으로 매겨야 한다.`,
  o:[
    { l:'① 시한을 정해 준다 — 숨이 바뀌는 순간까지는 사람으로.', k:'bond', dc:25, wake:1,
      ok:`사내 숨소리를 재게 했다. 지금은 사람 숨이다. 숨이 끓는 소리로 바뀌면 그때가 시한이라고, 모두 앞에서 정했다.<br><br>시한이 생기자 총대가 내려갔다. 사내는 제 발로 걷고, 지도를 들고, 길을 두 번 찾아냈다.<br>에어록 앞에서 사내의 숨이 끓기 시작했다. 사내가 먼저 멈춰 섰다. 약속한 값이라고. 문 밖에 남겠다고.<br><br>겁과 정 사이에 시한을 끼우는 법을 배웠다. 값을 매길 수 없는 것들도 기한은 받아들인다.`,
      ng:`시한을 정하는 말이 반쯤 나왔을 때 사내 가슴의 것이 크게 움직였다.<br><br>그쪽 팀이 흩어지며 총대가 올라갔고, 고함이 복도를 울렸다.<br>고함 값은 바로 왔다. 천장 배관에서 긁는 소리가 응답했다. 다 같이 뛰었다. 사내도 뛰었다. 셈은 미뤄졌을 뿐 끝나지 않았다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-21, spirit:-25 } },
    { l:'② 지금 재운다 — 약으로, 깊게.', k:'heal', dc:24,
      ok:`약 상자의 수면제를 긁어모았다. 사내가 고개를 끄덕이고 제 팔을 내밀었다.<br><br>잠든 사내를 들것에 묶었다. 속의 것은 숙주가 조용하면 같이 조용했다.<br>교대로 들고 에어록까지 갔다. 깨어나는 건 의무실 유리 안에서였다. 그 뒤 일은 의무실의 셈이다. 적어도 복도에서 터지는 셈은 막았다.`,
      ng:`약이 사람은 재웠는데 속의 것은 못 재웠다. 숙주가 조용해지자 오히려 바빠졌다.<br><br>들것 위 사내의 가슴이 들썩이는 속도가 빨라졌다. 들고 뛰었다.<br>의무실까지는 갔다. 들것을 든 팔이 다 후들거렸고, 그 방 유리 안에서 무슨 일이 일어났는지는 아무도 입에 안 올렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-29, mind:-18 } }
  ] },

{ at:'S1', t:'환풍구의 맞두드림',
  x:`벽을 두 번 치자 환풍구 속에서 두 번 돌아왔다. 세 번 치니 세 번.<br><br>
    팀원들이 반가워한다. 갇힌 사람이 있다고.<br>
    네 번째에, 저쪽이 먼저 쳤다. 두 번—쉬고—한 번. 이쪽이 안 가르친 박자다. 제안을 해 온 것이다.<br><br>
    배우는 중인 상대와는 거래하면 안 된다. 가르친 것은 전부 미끼로 돌아온다.`,
  o:[
    { l:'① 박자를 어긋내 흥정을 깬다 — 아무것도 가르치지 않는다.', k:'bond', dc:24,
      ok:`대답을 끊었다. 대신 아무 뜻 없는 박자를 쳤다. 셋—다섯—둘—열하나. 셈이 안 되는 수열로.<br><br>저쪽이 따라 하다 엉켰다. 다시 치고, 또 엉켰다.<br>엉킨 상대는 흥미를 잃는다. 긁는 소리가 환풍구 저쪽으로 멀어졌다. 배우러 온 것에게 가르치지 않는 것, 그것도 흥정이다.`,
      ng:`뜻 없는 박자를 쳤는데 저쪽이 그걸 통째로 외웠다. 셋—다섯—둘—열하나, 토씨 하나 안 틀리고.<br><br>그리고 그 박자가 복도 반대편 환풍구에서 났다. 앞뒤로.<br>환풍구 없는 길을 찾아 한 층을 돌았다. 외운 박자는 그 뒤로도 가끔 들렸다. 이쪽 서명을 저쪽이 쥔 셈이다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 덮개를 다 잠그고 환풍구 길을 버린다.', k:'fix', dc:23,
      ok:`이 구간 덮개를 전부 철사로 조였다. 손잡이 달린 쪽은 거꾸로 꺾어 놨다.<br><br>두드림이 덮개마다 따라오며 났다. 잠긴 걸 확인하는 소리.<br>마지막 덮개에서 소리가 오래 멎었다. 그리고 멀어졌다. 열리는 문이 없는 거리는 장사가 안 되는 거리다.`,
      ng:`셋째 덮개를 조이는데 안쪽에서 덮개를 밀었다. 손가락이 철망에 닿을 뻔했다.<br><br>철사를 쥔 채로 뒤로 뛰었다. 덮개는 반만 잠겼다.<br>남은 구간을 뛰다시피 지났다. 손바닥이 철사에 길게 베였다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S1', t:'여왕의 저울',
  x:`큰 방으로 가는 문턱에 물건들이 줄지어 놓여 있다. 손전등, 공구 벨트, 신발 한 짝, 인식표.<br><br>
    버린 게 아니다. 바쳐진 것이다. 줄이 너무 가지런하다.<br>
    문턱 너머 어둠은 숨을 쉰다. 방 전체가 들숨과 날숨으로 부풀고 꺼진다.<br><br>
    통행에 값을 받는 자리다. 그리고 이 시설 장부에는, 이 집 주인에게서 가져간 것이 적혀 있었다. 알 표본 셋.`,
  o:[
    { l:'① 가져간 것을 돌려놓는다 — 알 단지를 문턱에.', k:'bond', dc:26,
      ok:`표본동에서 안고 온 알 단지를 문턱 줄 끝에 놓았다. 뚜껑을 열어서.<br><br>방의 숨이 멎었다. 길고 가는 것이 어둠에서 나와 단지를 더듬었다. 한 번, 두 번. 그리고 단지째 어둠으로 거둬 갔다.<br>문턱의 물건들 위로 바람이 지나갔다. 비켜선 숨이다. 다섯이 벽에 붙어 방을 가로질렀다. 아무것도 따라오지 않았다.<br><br>빚은 갚은 쪽이 기억 못 해도 받은 쪽은 기억한다. 돌려주는 것이 제일 싼 통행료일 때가 있다.`,
      ng:`단지를 놓다 알았다. 단지가 비어 있다. 운반 중 언젠가부터.<br><br>빈 값은 모욕이다. 방의 숨이 거칠어졌다.<br>저울이고 뭐고 달렸다. 등 뒤에서 문턱의 물건들이 쓸려 흩어지는 소리가 났다. 마지막 팀원 외투 자락이 찢겨 날아갔다.`,
      win:{ exp:25, dream:4, spirit:8 }, lose:{ hp:-34, spirit:-28 } },
    { l:'② 아무것도 놓지 않고 저울을 지나친다.', k:'hide', dc:26,
      doom:{ title:'외상 사절', what:'여왕의 방으로 끌려갑니다', dc:20, sec:38,
        text:`벽에 붙어 숨을 끊고 문턱을 넘었다. 반쯤 건넜을 때 방의 숨이 바뀌었다.<br><br>들숨이 길어졌다. 방이 냄새를 세는 중이다. 하나, 둘, 셋, 넷 — 값을 안 낸 숫자를.<br><br>바닥을 쓸며 온 긴 것이 발목을 감았다. 외상은 사절이라는 뜻이다. 몸이 어둠의 안쪽으로 미끄러진다.`,
        dieText:`남은 팀원들이 문턱까지 쫓아갔지만 어둠의 숨이 벽처럼 밀어냈다.<br><br>다음 날 문턱의 줄에 물건이 하나 늘어 있었다. 낯익은 물통이다.<br>줄은 전보다 더 가지런해졌다. 수금은 밀리는 법이 없다.` },
      ok:`벽에 붙어 숨을 반으로 줄이고, 문턱의 물건 줄 바깥으로만 디뎠다.<br><br>방의 숨에 걸음을 실었다. 들숨에 걷고 날숨에 멎고.<br>건너편 문까지 마흔 걸음이 한나절 같았다. 값을 안 낸 게 아니라 저울에 아예 안 올라간 것이다. 그 차이가 목숨값이다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S1', t:'통신실 — 너무 빨리 응하는 값',
  x:`통신실 스피커가 산다. 채널 셋에서 사람 목소리가 나온다.<br><br>
    생존자 캠프라고 한다. 안전한 길을 알려 줄 테니 의약품을 가져오라고.<br>
    목소리는 멀쩡하다. 너무 멀쩡하다. 사흘을 갇힌 목소리에는 갈라진 데가 있어야 한다.<br><br>
    흥정으로 재 보면 안다. 아쉬운 쪽은 값을 깎고, 미끼는 값을 안 깎는다.`,
  o:[
    { l:'① 값을 터무니없이 불러 본다 — 흥정이 되는지 잰다.', k:'bond', dc:24, wake:1,
      ok:`의약품은 없고 대신 손전등 하나를 주겠다고 했다. 터무니없는 값이다.<br><br>목소리가 숨도 안 쉬고 좋다고 했다. 사람이면 욕부터 나올 값인데.<br>교신을 껐다. 그쪽이 알려 주려던 안전한 길은 지도에서 지웠다.<br><br>흥정은 거짓을 거르는 체라는 걸 배웠다. 아무 값이나 받는 상대는 줄 생각이 없는 상대다. 귀가 하나 더 트였다.`,
      ng:`터무니없는 값을 부르자 목소리가 잠깐 멎었다. 그리고 웃었다. 사람 웃음이 아니었다.<br><br>스피커가 꺼졌다. 통신실 바깥 복도 스피커가 켜졌다. 그다음은 그 너머 스피커.<br>위치를 재는 중이다. 이쪽이 되물은 값으로. 통신실을 버리고 반대쪽 계단으로 내뺐다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 교신을 끊고 전선을 따라 발신지를 짚는다.', k:'sense', dc:25,
      ok:`스피커 선을 눈으로 따라갔다. 배선함, 복도, 아래층 덕트.<br><br>발신지는 생존자 캠프 방향이 아니었다. 표본동 깊은 쪽이다.<br>지도에 그 방향을 통째로 빗금 쳤다. 목소리가 어디서 나는지 알면, 안 가면 된다. 제일 싼 해법이다.`,
      ng:`전선이 중간에 벽 속으로 숨었다. 벽에 귀를 댔다.<br><br>벽 안에서 목소리가 났다. 스피커 없이. 이쪽 이름을 비슷하게 발음하면서.<br>귀를 뗐다. 어떻게 아는지는 생각하지 않기로 했다. 그 벽을 등지고 걷는 내내 뒤통수가 당겼다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-19, spirit:-21 } }
  ] },

{ at:'S1', t:'냉동고 앞 — 추운 쪽의 조건',
  x:`냉동 창고 문 안에 사람들이 있다. 성에 낀 창 너머로 눈들이 움직인다.<br><br>
    문은 안에서 잠겼다. 그쪽 말로는, 그것들이 추위 속 숨은 못 맡는다고 한다. 들어오려면 숨부터 차가워지라고.<br>
    복도에 서리 낀 구간이 있다. 거기 서서 입김이 안 보일 때까지 버티면 열어 주겠다는 조건이다.<br><br>
    다친 팀원은 그 추위를 못 버틴다. 조건을 바꿔야 한다.`,
  o:[
    { l:'① 다친 사람 먼저 — 값은 이쪽 외투 전부로 치른다.', k:'bond', dc:24,
      ok:`외투 다섯 벌을 벗어 창에 대 보였다. 다친 하나를 먼저 들이는 값이라고.<br><br>추위에 갇힌 사람들에게 외투는 금이다. 문이 사람 하나 폭만큼 열렸다.<br>다친 팀원이 들어가고 외투가 넘어갔다. 남은 넷은 서리 구간에서 입김을 죽였다. 춥게 버는 돈도 돈이다.`,
      ng:`외투를 보여 주자 안쪽에서 다툼이 났다. 열자는 쪽과 속임수라는 쪽.<br><br>다투는 소리가 복도를 울렸다. 멀리서 배관 긁는 소리가 대답했다.<br>문은 끝내 안 열렸다. 다친 팀원을 업고 서리 구간을 그냥 지났다. 다들 입술이 파래졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-27, spirit:-18 } },
    { l:'② 다른 값을 찾는다 — 그쪽의 바깥 심부름.', k:'fix', dc:24,
      ok:`창 너머에 물었다. 바깥에서 해다 줄 일이 뭐냐고.<br><br>배전반 두꺼비집. 냉동고 예비 전원이 내려가 있단다. 올려 주면 문을 연다고.<br>복도 끝 배전반을 올렸다. 냉동고 불이 켜지고 문이 열렸다. 노동으로 치른 값은 뒤끝이 없다. 안쪽 사람들이 처음으로 웃었다.`,
      ng:`배전반까지는 갔다. 두꺼비집 옆 벽이 안쪽부터 긁혀 있었다. 새 자국이다.<br><br>올리는 손이 급했다. 스위치 하나를 잘못 올려 복도 등이 일제히 켜졌다 나갔다.<br>신호탄을 쏜 셈이다. 뛰어 돌아오는 길에 어깨를 어디에 세게 부딪혔다. 문은 열렸지만 아무도 웃지 않았다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-28, mind:-15 } },
    { l:'③ 숨을 죽여 조건대로 버틴다.', k:'steady', dc:25,
      ok:`서리 구간에 다섯이 섰다. 숨을 얕게, 길게. 입김이 가늘어지다 사라졌다.<br><br>창 너머 눈들이 하나하나 세었다. 문이 열렸다.<br>안은 좁고 추웠고, 살아 있는 사람 냄새가 났다. 그 냄새가 그렇게 반가운 줄 몰랐다.`,
      ng:`넷은 버텼는데 다친 하나의 입김이 자꾸 피어올랐다.<br><br>안쪽에서 고개를 저었다. 조건은 조건이라고.<br>서리 구간에서 물러났다. 손가락 끝이 한동안 말을 안 들었다. 조건을 못 맞춘 흥정은 흥정이 아니라 구걸이 된다. 구걸은 안 했다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-27, mind:-16 } }
  ] },

{ at:'S2', t:'울타리를 미는 박자',
  x:`울타리 너머에서 그것들이 일한다. 한 구간을 밀고, 물러나고, 다음 구간을 민다.<br><br>
    부수려는 게 아니다. 재는 것이다. 어디가 싸고 어디가 비싼지.<br>
    값을 재는 데도 품이 든다. 재 본 구간은 당분간 안 건드린다. 장부에 적힌 셈이니까.<br><br>
    그렇다면 이쪽이 지나갈 자리는 정해져 있다. 방금 셈이 끝난 자리.`,
  o:[
    { l:'① 시험이 끝난 구간 뒤로만 움직인다.', k:'bond', dc:25, wake:1,
      ok:`미는 소리가 멎은 구간을 셌다. 하나 건너 둘. 그 뒤로만 붙어 걸었다.<br><br>그것들의 장부와 이쪽 걸음이 어긋나지 않게. 셈이 끝난 자리는 그늘처럼 안전했다.<br>울타리 반 바퀴를 그렇게 돌았다. 한 번도 눈이 마주치지 않았다.<br><br>상대의 지출을 읽는 눈이 생겼다. 무엇이든 품을 들인 자리에는 당분간 품을 안 들인다. 짐승도, 사람도, 저 바깥의 회사도.`,
      ng:`셈이 끝났다고 믿은 구간을 하나가 되밟았다. 장부에 없는 걸음이다.<br><br>눈이 마주쳤다. 철망 하나를 사이에 두고.<br>그것이 소리를 내기 전에 뛰었다. 철망 밑단이 등 뒤에서 길게 울렸다. 미는 소리가 아니라 부수는 소리였다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-29, mind:-16 } },
    { l:'② 울타리를 두드려 가짜 시험 소리를 보탠다.', k:'fix', dc:24,
      ok:`돌로 먼 구간 철망을 두드렸다. 그것들이 미는 박자 그대로.<br><br>셈이 엉켰다. 저쪽 장부에 가짜 지출이 적혔다.<br>그것들이 가짜 자리를 재러 몰려간 사이 반대쪽을 지났다. 남의 장부를 더럽히는 건 좋은 버릇은 아니다. 잘 먹히는 버릇일 뿐.`,
      ng:`박자가 반 박 늦었다. 그것들이 일제히 멎었다.<br><br>낯선 회계사를 찾는 침묵이었다. 머리들이 이쪽 방향으로 돌았다.<br>두드리던 돌을 던져 버리고 고사리 밭으로 굴렀다. 밤새 그 구간 근처에도 못 갔다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'S2', t:'물을 흔드는 것 — 통행료',
  x:`물에 잠긴 고사리 밭이 길을 막는다. 수면이 가끔 둥글게 운다. 먼 데서부터, 크게.<br><br>
    물 깊이는 허리. 건너는 데 백 걸음.<br>
    물이 우는 간격을 쟀다. 숨 쉰다기보다 순찰이다. 이 물에는 주인이 있고, 주인 있는 길은 통행료를 받는다.<br><br>
    등짐에 짐승 고기 두 토막이 있다. 상류 쪽 물은 이쪽보다 깊다.`,
  o:[
    { l:'① 고기 한 토막을 상류에 던지고, 값이 끝나기 전에 건넌다.', k:'bond', dc:25,
      doom:{ title:'모자란 통행료', what:'물속으로 끌려 들어갑니다', dc:20, sec:36,
        text:`고기가 상류에 떨어지고, 물이 그쪽으로 쏠렸다. 백 걸음을 쉰까지 셌을 때 물이 돌아왔다.<br><br>한 토막 값이 쉰 걸음이었던 것이다.<br><br>종아리를 무엇이 감았다. 물이 입을 벌리듯 꺼지고, 몸이 수면 아래로 미끄러진다. 모자란 값은 몸으로 받는다.`,
        dieText:`물은 금방 잠잠해졌다. 고사리 이파리 몇 장이 뒤집힌 채 떠돌았다.<br><br>남은 고기 한 토막은 아무도 입에 못 댔다. 건너편에 두고 왔다.<br>그 물은 이제 두 토막 값이 됐다. 값이란 오르기만 한다.` },
      ok:`고기를 상류 멀리 던지고 물이 쏠리는 걸 확인했다. 그리고 다섯이 한 덩어리로 물을 갈랐다.<br><br>세는 건 이쪽 몫이었다. 마흔에 반, 여든에 거의. 아흔에서 물이 돌아서는 기척이 왔다.<br>마지막 열 걸음은 셈을 버리고 뛰었다. 다 건넜을 때 등 뒤 수면이 길게 울었다. 통행료는 한 번 값이다. 두 번은 안 통한다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 물이 조용한 때를 기다린다 — 새벽까지.', k:'steady', dc:23,
      ok:`물가에서 물러나 마른 둔덕에 숨었다. 물 우는 간격이 길어지는 때를 쟀다.<br><br>새벽 어스름에 간격이 세 배로 늘었다. 주인도 자는 시간이 있다.<br>그때 건넜다. 느리게, 물결을 안 만들며. 공짜 길은 없지만 할인 시간은 있다.`,
      ng:`기다리는 밤이 길었다. 둔덕의 풀이 밤새 서걱였다. 물것들이 다리를 물었다.<br><br>새벽에 팀원 하나가 깜빡 졸다 비탈로 굴렀다. 물가까지.<br>물이 울기 전에 끌어올렸다. 건너긴 건넜는데, 다들 한숨도 못 잔 채였다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, spirit:-16 } }
  ] },

{ at:'S2', t:'무리의 장과 값 매기기',
  x:`탁 트인 풀밭 가운데서 그것들의 장이 길을 막았다. 홀로. 나머지는 풀 속에 있다. 보이지 않지만 센다.<br><br>
    장은 서두르지 않는다. 고개를 기울이고 이쪽을 잰다. 다리, 짐, 눈.<br>
    값을 매기는 중이다. 사냥은 장사다. 이빨 값보다 고기 값이 싸면 장사가 아니다.<br><br>
    그러니 할 일은 하나다. 비싸게 굴 것.`,
  o:[
    { l:'① 다섯이 어깨를 붙여 한 덩어리로 커진다.', k:'bond', dc:25,
      ok:`다섯이 어깨를 맞대고 섰다. 짐을 머리 위로 올려 키를 더했다. 한 마리의 큰 짐승처럼.<br><br>장의 고개가 반대로 기울었다. 셈이 바뀌는 각도다.<br>장이 몸을 돌렸다. 풀이 물결치며 보이지 않던 것들이 따라 돌았다. 여섯, 일곱… 세다 말았다. 안 사는 손님은 수가 많아도 그냥 손님이다.`,
      ng:`덩어리로 커지는데 맨 끝 팀원의 무릎이 꺾였다. 덩어리에 금이 간 것이다.<br><br>장의 고개가 바로 섰다. 금 간 물건은 싸다.<br>풀이 세 방향에서 일었다. 등을 맞대고 물러나며 긴 백 걸음을 벌었다. 바위 틈에 끼고서야 풀이 가라앉았다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-30, mind:-17 } },
    { l:'② 짐에서 쇠를 꺼내 보인다 — 이빨 값을 올린다.', k:'break', dc:24,
      ok:`곡괭이와 낫을 꺼내 날을 세워 들었다. 해 없는 하늘 아래서도 쇠는 쇠 빛을 낸다.<br><br>장이 그 빛을 안다는 듯 한 발 물러났다. 전에 쇠에 값을 치러 본 몸이다. 옆구리의 오랜 흉터가 그 영수증이다.<br>장은 풀 속으로 녹았다. 영수증 있는 손님이 제일 다루기 쉽다.`,
      ng:`쇠를 보이자 장이 짧게 울었다. 부르는 소리다.<br><br>쇠를 아는 놈이라 쇠 든 팔부터 노린다. 풀에서 튀어나온 둘이 양팔 쪽을 스쳤다.<br>휘두르고 물러나고를 반복하며 바위까지 밀렸다. 낫 하나를 풀밭에 두고 왔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-31, spirit:-17 } },
    { l:'③ 눈을 깔지 않은 채 옆걸음으로 비낀다.', k:'evade', dc:25,
      ok:`정면을 준 채 옆으로 걸었다. 등도 배도 안 보이는 걸음. 먹잇감의 걸음이 아닌 걸음.<br><br>장이 따라 돌며 쟀다. 재는 동안 거리는 조금씩 벌어졌다.<br>풀밭 가장자리 바위에 닿자 장이 셈을 접었다. 도망치지 않는 것은 쫓는 값이 안 나온다.`,
      ng:`옆걸음 중에 발밑에서 마른 가지가 터졌다. 소리에 이쪽 어깨가 먼저 움츠러들었다.<br><br>움츠린 어깨는 먹잇감의 어깨다. 장이 두 걸음 좁혔다.<br>바위까지 남은 거리를 결국 뛰었다. 뛰는 등 뒤로 풀 전체가 일어서는 소리가 났다. 바위 틈이 반 걸음만 멀었어도 셈이 달랐다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S2', t:'낡은 승강기 — 무게의 셈',
  x:`승강기는 살아 있다. 다만 늙었다. 명판의 정원은 넷. 이쪽은 다섯에, 주운 생존자가 하나.<br><br>
    쇠줄이 숨 쉴 때마다 가늘게 운다. 여섯은 욕심이고 다섯도 흥정이다.<br>
    짐을 다 합치면 사람 하나 무게다. 결국 셈은 하나로 좁혀진다.<br><br>
    무엇이 사람이고 무엇이 짐인가. 그걸 가르는 게 이쪽 장사다.`,
  o:[
    { l:'① 짐을 다 부리고 사람만 태운다.', k:'bond', dc:25, wake:1,
      ok:`배낭을 전부 승강장에 부렸다. 못 버리겠다는 손들에게 말했다. 품에 하나씩만. 목숨 다음으로 아까운 것 하나씩만.<br><br>여섯 사람과 품 여섯 개가 탔다. 쇠줄이 울되 끊어질 울음은 아니었다.<br>오르는 동안 승강장의 짐 무더기 곁으로 풀 그림자들이 모이는 게 내려다보였다.<br><br>값나가는 것과 값을 매길 수 없는 것을 가르는 손. 이 장사의 끝에 남는 기술은 그것 하나다.`,
      ng:`다 부렸다고 믿었다. 오르는 중에 쇠줄이 한 번 크게 울었다.<br><br>생존자의 외투 안에서 돌덩이만 한 보따리가 나왔다. 표본석이라고 했다.<br>보따리는 창밖으로 던져졌다. 승강기는 버텼다. 다만 그 한 번의 울음에 다들 수명이 좀 줄었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-22 } },
    { l:'② 두 번에 나눠 올린다 — 남는 쪽을 이쪽이 맡는다.', k:'steady', dc:26,
      ok:`셋을 먼저 올렸다. 승강기가 돌아오는 동안 남은 셋이 승강장 등을 맞댔다.<br><br>기다림은 길었다. 풀 쪽에서 두 번, 물 쪽에서 한 번 기척이 왔다. 그때마다 숨을 죽였다.<br>두 번째 승강기가 내려왔을 때, 문이 열리는 소리가 종소리 같았다. 나눠 치르는 값은 기다리는 쪽이 비싸게 낸다. 그 값을 이쪽이 냈을 뿐이다.`,
      ng:`첫 차가 오른 뒤 풀이 움직였다. 기다림을 저쪽도 셌던 것이다.<br><br>남은 셋이 승강장 철골을 타고 올라 매달렸다. 밑에서 철골이 두 번 흔들렸다.<br>두 번째 차가 왔을 때 팔에 힘이 하나도 안 남아 있었다. 굴러들어 가듯 탔다.`,
      win:{ exp:17, dream:3, spirit:6 }, lose:{ hp:-33, mind:-18 } }
  ] },

{ at:'S2', t:'알 둥지 사잇길',
  x:`길이 둥지 사이로 난다. 흙무더기마다 알이 반쯤 묻혀 있고, 흙이 따뜻하다.<br><br>
    돌아가는 길은 물이고, 물에는 주인이 있다. 사잇길이 그나마 싸다.<br>
    둥지 그늘에 어미가 있다. 눈을 반만 감고 있지만 자는 게 아니다. 제 알을 세고 있다.<br><br>
    세는 상대 앞에서는 셈을 흐트리지 않는 게 예의고, 예의가 곧 값이다.`,
  o:[
    { l:'① 빈손을 펴 보이며 둥지 금 바깥으로만 걷는다.', k:'bond', dc:24,
      ok:`두 손을 펴서 몸 옆에 늘어뜨리고 걸었다. 짐은 등에, 손에는 아무것도.<br><br>어미의 반 감긴 눈이 손을 봤다. 집는 손이 아니라는 걸 확인하는 눈.<br>다섯이 같은 손으로 지났다. 어미는 한 번도 일어서지 않았다. 말이 안 통해도 손은 통한다. 빈손은 모든 말보다 오래된 흥정이다.`,
      ng:`넷째 팀원이 돌부리에 걸려 둥지 금 안쪽에 손을 짚었다.<br><br>어미가 일어섰다. 일어선 키가 생각의 두 배였다.<br>손 짚은 자리에서 모두 얼어붙었다. 한나절 같은 열 숨 뒤에 어미가 도로 앉았다. 뒷걸음으로 사잇길을 마저 나왔다. 아무도 뒤를 안 돌아봤다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-17, spirit:-19 } },
    { l:'② 흙을 끼얹어 냄새를 죽이고 기어서 지난다.', k:'hide', dc:25,
      ok:`둥지 흙을 몸에 끼얹었다. 알 냄새 나는 따뜻한 흙이다.<br><br>배를 땅에 붙이고 금 바깥을 기었다. 어미 눈에 이쪽은 흙 위를 바람이 지나간 자국쯤이었을 것이다.<br>사잇길 끝에서 일어나 흙을 털었다. 품에서 알 조각 하나가 떨어졌다. 빈 껍데기였다. 그래도 멀리 던져 버렸다. 오해는 제일 비싼 지출이다.`,
      ng:`기는 중에 등짐이 둥지 흙무더기를 스쳤다. 흙이 조금 흘렀다.<br><br>어미의 고개가 소리 없이 돌았다. 세던 셈이 어긋난 얼굴.<br>납작 엎드려 숨을 끊었다. 어미가 흙을 도로 긁어 덮는 동안 손끝 하나 못 움직였다. 사잇길의 나머지는 평생처럼 길었다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'S2', t:'관리인의 심부름',
  x:`울타리 안쪽 오두막에 늙은 관리인이 산다. 승강기 열쇠를 목에 걸고 있다.<br><br>
    열쇠 값은 심부름이다. 해 질 녘 배식. 종을 세 번 치고, 수레를 끌고 물가까지. 늘 하던 대로.<br>
    늘 하던 대로가 아니면 큰 것이 수상해한다고 한다. 수상해하면 울타리가 소용없어진다고.<br><br>
    남의 오랜 거래에 대신 들어가는 일이다. 조건부터 다시 봐야 한다.`,
  o:[
    { l:'① 조건을 줄인다 — 종은 치되 수레는 노인이 끈다.', k:'bond', dc:25,
      ok:`심부름을 쪼갰다. 종과 길 트기는 이쪽, 수레는 늘 끌던 손이 끈다. 큰 것은 수레 끄는 걸음 소리까지 외우고 있을 테니까.<br><br>노인이 한참 보다가 고개를 끄덕였다. 제 거래의 요체를 아는 상대를 만난 눈이었다.<br>종 세 번, 익은 걸음, 물가의 배식. 물이 한 번 크게 울고 잠잠해졌다. 열쇠가 이쪽 손에 넘어왔다. 남의 거래는 통째로 사는 게 아니라 필요한 조각만 사는 것이다.`,
      ng:`수레를 노인에게 미루는 걸 노인이 서운해했다. 늙은 팔이 수레를 끌다 바퀴가 돌에 걸렸다.<br><br>배식이 늦었다. 물가의 물이 두 번 울었다. 재촉이다.<br>같이 수레를 밀어 간신히 시간을 맞췄다. 노인은 그날 밤 열쇠를 안 주고 하루 더 보자고 했다. 거래가 하루 늘어진 값으로 울타리 안에서 밤을 났다.`,
      win:{ exp:23, dream:3, item:'산나물' }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 심부름을 그대로 다 한다 — 늘 하던 대로니까.', k:'steady', dc:24,
      doom:{ title:'저녁 배식', what:'배식 수레째 물속으로 끌려 들어갑니다', dc:19, sec:42,
        text:`종 세 번, 수레, 물가. 조건대로 했다.<br><br>다만 큰 것은 걸음 소리로 안다. 늘 끌던 걸음이 아니라는 걸.<br><br>물이 소리 없이 부풀더니 수레를 물었다. 수레 손잡이를 쥔 손까지 같이. 낯선 배식부는 배식에 포함되는 모양이다.`,
        dieText:`수레는 이튿날 물가에 돌아와 있었다. 비어서, 바퀴만 천천히 돌면서.<br><br>노인은 열쇠를 벗어 수레에 걸어 놓고 오두막에 들어가 문을 닫았다.<br>배식 종은 그 뒤로도 해 질 녘마다 울린다. 치는 사람이 누군지는 모른다.` },
      ok:`노인의 낡은 장화를 빌려 신고 걸음까지 흉내 냈다. 수레 삐걱임 박자도.<br><br>물가에 수레를 부리고 종 걸이에 종을 걸었다. 물이 한 번 울고, 받았다.<br>돌아오는 길에 노인이 오두막 앞에서 울고 있었다. 제 걸음을 남이 걷는 걸 본 사람의 울음이었다. 열쇠는 받았다. 값이 어느 쪽이 더 컸는지는 모르겠다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S2', t:'마지막 셈 — 문이 닫히기 전에',
  x:`승강기 문이 열려 있다. 이제 오르면 끝이다.<br><br>
    풀밭 가장자리에 그것들이 나와 섰다. 덤비지 않는다. 보고 있다. 나가는 짐을 검사하는 눈으로.<br>
    팀 배낭에는 정원 것들이 들어 있다. 주운 알 껍데기, 꺾은 양치 이파리, 물가의 돌.<br><br>
    장부를 닫을 시간이다. 닫히지 않은 장부는 따라온다.`,
  o:[
    { l:'① 정원 것은 정원에 두고 빈손으로 오른다.', k:'bond', dc:25, wake:1,
      ok:`배낭을 털었다. 껍데기도, 이파리도, 돌도 승강장 바깥 흙에 내려놓았다.<br><br>가장자리의 그것들이 고개를 낮췄다. 적의가 아니라 셈이 맞았다는 각도.<br>문이 닫히고 승강기가 올랐다. 창밖으로 정원이 줄어들었다. 아무것도 따라 올라오지 않았다.<br><br>셈을 끝내고 나오는 법을 배웠다. 빚 없는 등은 가볍고, 가벼운 등만 문턱을 넘는다. 이 장사의 마지막 장이다.`,
      ng:`다 턴 줄 알았다. 문이 닫히다 멎었다. 반 뼘을 남기고.<br><br>막내 장화 밑창에 씨앗 몇 알이 박혀 있었다. 장화를 벗어 문틈으로 던지고서야 문이 마저 닫혔다.<br>오르는 내내 아무도 입을 안 열었다. 반 뼘의 셈. 그 반 뼘이 밤마다 꿈에 나왔다.`,
      win:{ exp:25, dream:4 }, lose:{ mind:-15, spirit:-18 } },
    { l:'② 가져갈 것은 올려 보내고, 이쪽이 남아 셈을 마주 본다.', k:'steady', dc:26,
      ok:`배낭들을 먼저 올려 보냈다. 그리고 승강장에 홀로 서서 가장자리의 눈들을 마주 봤다.<br><br>물러서지도, 다가서지도 않고. 짐과 사람이 따로라는 걸 보여 주는 자세로.<br>두 번째 승강기가 내려올 때까지 눈싸움은 끝나지 않았다. 다만 아무도 선을 안 넘었다. 셈을 마주 보는 동안은 수금이 없다.`,
      ng:`홀로 남은 숨이 생각보다 빨리 흔들렸다. 눈 하나가 그 흔들림을 집었다.<br><br>가장자리에서 한 마리가 승강장 철골까지 다가와 쇠 냄새를 맡았다.<br>숨 한 번 거리에서 그것의 콧김이 느껴졌다. 승강기가 내려오는 소리에 그것이 물러났다. 타고 오르는 손이 떨려서 손잡이를 세 번 놓쳤다.`,
      win:{ exp:17, dream:3, spirit:7 }, lose:{ hp:-35, spirit:-25 } }
  ] }

]);

// ------------------------------------------
// 결속술사 · 마력
// ------------------------------------------
kJob('binder', 'S', [

{ at:'S', t:'다섯 가닥 점호',
  x:`잠든 팀에 실을 하나씩 걸어 두었다. 다섯 가닥. 손끝에 모아 쥐면 숨결이 올마다 다르게 뛴다.<br><br>
    밤중에 한 가닥이 느슨해졌다. 끊어진 게 아니다. 끊어지면 손끝이 운다.<br>
    느슨한 채로 조금씩 길어진다. 자리에서 멀어지고 있다는 뜻이다. 비명도 발소리도 없이.<br><br>
    자면서 걷는 사람은 없다. 걷게 하는 무엇이 있을 뿐이다.`,
  o:[
    { l:'① 실에 마력을 흘려 그 손목을 당겨 깨운다.', k:'bond', dc:24, cost:{ mana:30 },
      ok:`실을 타고 마력을 밀었다. 손목을 쥐고 흔드는 세기로.<br><br>어둠 저쪽에서 숨 삼키는 소리가 났다. 깬 것이다. 그리고 깬 사람 발치에서 무엇이 황급히 미끄러져 물러나는 소리도.<br>돌아온 팀원의 장화 목에 침 같은 것이 번들거렸다. 물고 끌던 자국이다. 조용히, 깨지 않게, 아주 공들여서.`,
      ng:`마력이 급했다. 당김이 너무 셌다.<br><br>팀원이 비명을 지르며 깼다. 끌던 것이 놀라 마지막으로 세게 물고 놓았다.<br>발목에 구멍이 두 줄 남았다. 비명은 어둠 멀리까지 갔다. 그날 밤은 거기서 끝났다. 아무도 다시 못 잤다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 소리 없이 실을 따라간다.', k:'hide', dc:24,
      ok:`실을 늦추지 않을 만큼만 따라갔다. 모퉁이 하나, 내리막 하나.<br><br>팀원은 눈을 뜬 채 걷고 있었다. 그 앞에서 가늘고 긴 것이 뒷걸음질로 길을 이끌었다. 피리 부는 손짓처럼 허공을 쓸면서.<br>팀원의 허리를 뒤에서 안아 세웠다. 가늘고 긴 것은 어둠에 녹았다. 서두르지 않는 게 더 소름 돋았다.`,
      ng:`세 걸음째에 돌을 밟았다. 끌던 것이 멈췄다.<br><br>어둠 속에서 이쪽을 돌아보는 기척. 그리고 팀원을 버려 두고 사라졌다.<br>팀원은 그 자리에 선 채 울고 있었다. 어디까지 왔는지도 모르면서. 업고 돌아오는 길이 멀었다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-17, spirit:-19 } }
  ] },

{ at:'S', t:'어깨 위의 표식 실',
  x:`팀원 어깨에 실 한 올이 붙어 있다. 이쪽이 건 실이 아니다.<br><br>
    가늘고, 축축하고, 어둠 쪽으로 길게 이어진다. 걸을 때마다 조금씩 풀려 나온다.<br>
    사냥하는 것들은 찜한 먹이에 표를 단다. 눈 대신 실로 쫓는 것이다.<br><br>
    본인은 모른다. 표식은 단 쪽과 보는 쪽만 안다. 지금 보는 쪽은 이쪽뿐이다.`,
  o:[
    { l:'① 표식을 걷어 제 어깨에 옮겨 단다.', k:'bond', dc:25,
      ok:`실을 두 손가락으로 걷어 제 어깨에 얹었다. 축축한 올이 천을 파고드는 게 느껴졌다.<br><br>표식은 이쪽 업이다. 단 줄 알고 다니는 표식은 표식이 아니라 미끼다.<br>모닥불을 피울 때 어깨를 불 쪽으로 대고 오래 앉았다. 올이 마르다가 타다가, 바스러졌다. 어둠 저쪽에서 끊긴 실을 더듬는 기척이 밤새 서성였다.`,
      ng:`옮겨 다는 손끝에서 올이 두 가닥으로 갈라졌다. 한 가닥은 이쪽에, 한 가닥은 그대로 팀원에게.<br><br>표가 둘이 됐다. 그날 밤 서성이는 기척도 둘이었다.<br>불에 지지고 또 지져 겨우 둘 다 끊었다. 어깨 천에 탄 자국이 나란히 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 실을 걷어 바람 길에 띄워 보낸다.', k:'fix', dc:24,
      ok:`통로의 바람 길을 찾았다. 환기 틈에서 틈으로 흐르는 가는 바람.<br><br>걷은 올을 그 바람에 실었다. 올이 흔들흔들 떠서 다른 통로로 흘러갔다.<br>표식은 이제 빈 바람을 쫓는다. 쫓는 것이 바람을 따라잡는 소리를 멀리서 들었다. 따라잡고 나서 한참 조용했다. 셈이 안 맞아 서 있는 것이다.`,
      ng:`바람이 변덕을 부렸다. 올이 떠오르다 도로 내려앉았다. 이번엔 다른 팀원 배낭에.<br><br>세 번을 걷어 세 번을 띄웠다. 올은 자꾸 사람에게 돌아왔다. 바람보다 사람 냄새가 끌리는 모양이다.<br>결국 돌에 감아 물웅덩이에 가라앉혔다. 돌아서는 등 뒤에서 웅덩이가 한 번 꿀럭했다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'S', t:'한 호흡 묶기',
  x:`이 어둠은 귀로 사냥한다. 다섯 숨소리는 다섯 끼니다.<br><br>
    숨을 죽이라고 하면 사람은 오히려 숨이 커진다. 죽이는 게 아니라 묶어야 한다.<br>
    다섯 들숨을 한 박자에, 다섯 날숨을 한 박자에. 그러면 귀에는 하나로 들린다.<br><br>
    하나로 들리되, 큰 하나로 들린다. 그게 요점이다. 큰 것은 아무도 안 건드린다.`,
  o:[
    { l:'① 다섯 숨을 실로 엮어 한 숨으로 만든다.', k:'bond', dc:24, wake:1, cost:{ mana:32 },
      ok:`가슴마다 실을 걸고 마력으로 박자를 맞췄다. 들숨 하나, 날숨 하나. 다섯 가슴이 한 가슴처럼 부풀고 꺼졌다.<br><br>어둠의 귀에 이쪽은 소 만 한 짐승 한 마리였을 것이다. 따라붙던 기척이 거리를 벌렸다. 큰 것의 영역을 침범한 작은 것처럼 조심스럽게.<br><br>묶는 실이 숨까지 엮을 수 있다는 걸 알았다. 몸과 몸이 아니라 박자와 박자를 묶는 것. 손이 하나 더 트인 기분이다.`,
      ng:`네 숨은 묶였는데 다친 팀원의 숨이 자꾸 어긋났다. 아픈 숨은 박자를 못 탄다.<br><br>하나 어긋난 숨은 묶인 네 숨 위에서 더 도드라졌다. 큰 짐승 속에서 우는 작은 짐승 소리.<br>기척이 오히려 가까워졌다. 묶음을 풀고 흩어져 숨었다. 반나절을 버린 뒤에야 다시 모였다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 둘씩만 묶고 교대로 걷는다.', k:'steady', dc:23,
      ok:`둘씩 숨을 맞추게 하고, 세 묶음이 번갈아 걷고 멎었다.<br><br>귀에는 두셋이 오가는 소리. 수를 셀 수 없는 소리다.<br>세기를 포기한 기척이 다른 사냥감을 찾아 떠났다. 셈을 흐리는 것도 묶는 일의 한 갈래다.`,
      ng:`교대 박자가 밀렸다. 세 묶음이 한 순간 다 같이 걸었다.<br><br>여섯 발, 열 발, 다섯 숨이 한꺼번에 울렸다. 어둠이 수를 셌다.<br>그 층을 나올 때까지 두 번을 쫓겼다. 두 번째엔 막내 배낭이 찢겼다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, mind:-15 } },
    { l:'③ 어둠의 숨에 다섯 숨을 겹친다.', k:'sense', dc:25,
      ok:`쫓는 것의 숨을 먼저 들었다. 길고, 축축하고, 느리다.<br><br>그 들숨 속에 다섯 들숨을 숨겼다. 그 날숨 속에 다섯 날숨을.<br>제 숨소리 안쪽에서 나는 소리는 아무도 못 듣는다. 그것의 숨을 빌려 그 곁을 지나갔다. 가장 가까운 자리가 가장 조용한 자리였다.`,
      ng:`겹치다가 그것의 숨이 갑자기 멎었다. 이쪽 다섯 숨만 허공에 남았다.<br><br>숨을 참는 것은 듣고 있다는 것이다.<br>다섯이 숨을 참는 데도 한계가 있다. 제일 먼저 터진 숨을 신호로 다 같이 뛰었다. 갈림길 두 개를 버리고서야 떨어져 나갔다.`,
      win:{ exp:16, dream:3 }, lose:{ mind:-19, spirit:-21 } }
  ] },

{ at:'S', t:'끊어진 실의 끝',
  x:`통로 가운데 실 한 끝이 떠 있다. 이쪽 눈에만 보이는 종류의 실이다.<br><br>
    끊어진 단면이 아직 젖어 있다. 오래되지 않았다. 그리고 실 끝이 이쪽을 향해 조금씩 기운다.<br>
    닻 잃은 실은 닻을 찾는다. 어느 결속술사가 여기서 팀을 걸어 두고, 돌아오지 못한 것이다.<br><br>
    실 끝은 묻고 있다. 네가 받아 줄 거냐고.`,
  o:[
    { l:'① 떠도는 실을 받아 준다.', k:'bond', dc:25,
      doom:{ title:'닻 잃은 실', what:'죽은 팀의 자리로 끌려갑니다', dc:19, sec:45,
        text:`손목을 내밀자 실이 감겨 왔다. 반가워하며, 허겁지겁.<br><br>감기고 나서야 알았다. 실 저쪽 끝이 아직 어딘가에 걸려 있다. 죽은 자리의 무엇에.<br><br>실이 감긴 손목째 당겨진다. 바닥에 발꿈치가 긁히며 어둠 안쪽으로. 닻이 되어 달라는 게 아니라 닻 있는 데로 데려가려는 것이었다.`,
        dieText:`팀원들 눈에는 아무것도 안 보였다. 손목을 앞세우고 어둠으로 미끄러져 가는 사람만 보였다.<br><br>모퉁이 너머에서 실 끊어지는 소리는 이쪽 눈 가진 사람에게만 들렸을 것이다.<br>그 통로에는 이제 실이 두 가닥 떠 있다. 둘 다 조금씩, 지나는 사람 쪽으로 기운다.` },
      ok:`손목을 내밀어 실을 받았다. 감기는 순간 남의 마지막이 흘러들었다.<br><br>아래층 물소리. 셋이 먼저 가라는 외침. 문이 안 닫히던 감촉. 그리고 끝.<br>실을 쓰다듬어 달랜 뒤 매듭을 풀어 흩었다. 실은 바람도 없이 흩어졌다.<br><br>아래층 물소리 나는 문은 지도에서 지웠다. 죽은 동업자의 마지막 일지를 받은 셈이다. 값은 손목의 서늘한 자국으로 치렀다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 닿기 전에 끊어 흩는다.', k:'break', dc:24,
      ok:`칼날에 마력을 얇게 입혀 실 끝을 쳤다. 눈에만 보이는 것도 날은 탄다.<br><br>실이 소리 없이 바스러졌다. 바스러지며 한순간 사람 윤곽 같은 게 비치다 말았다.<br>명복 같은 건 빌지 않았다. 다만 그 통로를 지나는 동안 모자를 벗었다. 같은 일 하다 간 사람이니까.`,
      ng:`날이 실을 반만 쳤다. 반 끊긴 실이 허공에서 몸부림쳤다.<br><br>그 몸부림이 이쪽 실들을 할퀴었다. 팀 다섯에게 걸어 둔 실이 한꺼번에 울었다.<br>팀원들이 이유 모를 오한에 한참 떨었다. 밤에 다들 같은 꿈을 꿨다고 했다. 물소리 나는 문 꿈.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-19, spirit:-23 } }
  ] },

{ at:'S', t:'겁의 매듭',
  x:`겁은 실을 탄다. 이쪽 눈에는 보인다.<br><br>
    맨 뒤 팀원의 떨림이 실을 타고 앞사람에게 번진다. 어깨에서 어깨로, 식은 불꽃처럼.<br>
    다섯째까지 번지면 대열은 달리기 시작한다. 그리고 이 어둠에서 달리는 것은 전부 먹이다.<br><br>
    번지는 길목은 실이 가장 가는 자리다. 매듭 하나면 막을 수 있다.`,
  o:[
    { l:'① 겁이 넘어가는 길목에 매듭을 묶는다.', k:'bond', dc:24, wake:1,
      ok:`둘째와 셋째 사이 실에 매듭을 지었다. 단단하게, 그러나 피가 통할 만큼.<br><br>겁이 매듭에 닿아 멎었다. 둘째까지는 떨고, 셋째부터는 걸었다. 떨던 둘도 앞이 걷는 걸 보고 차츰 가라앉았다.<br>겁은 둑 터진 물이 아니라 실을 타는 불이다. 중간만 끊으면 번지지 않는다.<br><br>마음도 실을 탄다는 것. 그 실에도 매듭이 먹힌다는 것. 묶는 일의 지경이 한 뼘 넓어졌다.`,
      ng:`매듭이 너무 단단했다. 겁만 막은 게 아니라 온기도 막았다.<br><br>둘째가 혼자가 됐다. 매듭 뒤에서, 제 겁에 잠겨서.<br>걸음이 서다시피 느려졌다. 매듭을 도로 풀고 어깨를 빌려줬다. 늦은 만큼 밤길을 걸었다.`,
      win:{ exp:22, dream:3, mind:6 }, lose:{ mind:-17, spirit:-19 } },
    { l:'② 실을 다 풀고 저마다 제 발로 서게 한다.', k:'steady', dc:25,
      ok:`걸어 둔 실을 다 걷었다. 지금부터 각자의 숨으로 걷는다고 말했다.<br><br>처음엔 대열이 흔들렸다. 그러다 저마다 제 박자를 찾았다.<br>겁은 번지지 않았다. 번질 길이 없으니까. 다만 이쪽 손끝이 종일 허전했다. 묶는 사람이 실을 놓는 것도 수행이다.`,
      ng:`실을 걷자마자 맨 뒤 팀원이 주저앉았다. 실이 지탱이었던 것이다.<br><br>혼자가 된 겁은 번지는 겁보다 깊었다. 달래서 일으키는 데 한참 걸렸다.<br>그 뒤로 그 팀원은 걸을 때 자꾸 제 손목을 만진다. 실 자국이 있던 자리를.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'S', t:'무게 나누기',
  x:`들것에 누운 팀원이 무겁다. 드는 둘의 팔이 두 시간째 떨린다.<br><br>
    교대를 늘려도 둘은 늘 지쳐 있다. 지친 둘은 대열의 구멍이고, 구멍은 냄새가 난다. 쫓는 것들은 그 냄새를 안다.<br>
    들것의 무게는 어차피 다섯이 나눠 진 목숨이다. 그러면 무게도 다섯으로 나누는 게 맞다.<br><br>
    실은 힘도 나른다. 가늘어서 그렇지.`,
  o:[
    { l:'① 들것 무게를 다섯 실에 나눠 건다.', k:'bond', dc:24, wake:1, cost:{ mana:28 },
      ok:`들것 네 귀에서 실을 뽑아 다섯 어깨에 걸었다. 마력이 실을 타고 무게를 날랐다.<br><br>드는 둘의 팔에서 떨림이 가셨다. 대신 다섯 어깨가 다 조금씩 묵직해졌다. 걷는 속도가 돌아왔다.<br>들것 위 팀원이 중얼거렸다. 떠가는 것 같다고.<br><br>구하는 실만 실이 아니다. 나르고, 나누고, 버티는 실. 묶는 일은 위급이 아니라 살림이라는 걸 배웠다.`,
      ng:`무게가 실을 타다 한 올이 끊겼다. 끊긴 몫이 남은 넷에게 왈칵 쏠렸다.<br><br>맨 앞 팀원이 무릎을 찧었다. 들것이 기울고 누운 팀원이 굴렀다.<br>도로 손으로 들었다. 끊긴 올의 몫까지 어깨가 알고 있어서, 그날은 다들 일찍 지쳤다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 실 없이 교대 순번만 다시 짠다.', k:'fix', dc:23,
      ok:`교대를 둘-둘-하나에서 넷-하나로 바꿨다. 네 귀를 넷이 잡고, 하나가 앞길을 틔운다.<br><br>한 사람 몫이 반으로 줄었다. 떨리던 팔이 가라앉았다.<br>마력 한 방울 안 쓰고 해결했다. 실이 없을 때의 묶음도 묶음이다. 그걸 잊으면 실의 종이 된다.`,
      ng:`넷이 드니 보폭이 안 맞았다. 들것이 파도를 탔다.<br><br>누운 팀원이 멀미에 토했다. 토한 냄새는 이 어둠에서 등불이나 마찬가지다.<br>냄새를 지우느라 귀한 물을 썼다. 걸음도 반나절 늦어졌다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-16, spirit:-17 } }
  ] },

{ at:'S', t:'실이 먼저 운다',
  x:`팀에 걸어 둔 다섯 실이 일제히 가늘게 운다. 소리가 아니라 손끝으로 오는 울음이다.<br><br>
    실은 몸보다 먼저 안다. 다섯 몸의 솜털이 다 곤두섰다는 뜻이다. 머리가 알기 전에.<br>
    앞길 어딘가에 숨어 있다. 어느 쪽인지는 실이 말해 주지 않는다.<br><br>
    다만 우는 세기가 올마다 다르다. 맨 앞 실이 제일 크게 운다.`,
  o:[
    { l:'① 우는 실 쪽으로 등불을 먼저 던진다.', k:'sense', dc:24,
      ok:`제일 크게 우는 방향, 앞길 왼쪽 틈에 등불을 던졌다.<br><br>틈 속에서 큰 몸이 빛을 피해 접히는 게 보였다. 접히는 데 두 숨이 걸리는 크기였다.<br>그 틈을 넓게 돌아 지났다. 등불 하나 값으로 매복 하나를 샀다. 싸게 산 것이다.`,
      ng:`던진 등불이 틈 앞 바닥에서 깨졌다. 기름 불이 번졌다.<br><br>숨어 있던 것이 불에 몰려 틈 밖으로 나왔다. 이쪽 길로.<br>불과 그것 사이로 달려 빠졌다. 맨 뒤 팀원의 소매가 그슬렸다. 그것에게서인지 불에서인지는 아무도 못 봤다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-27, mind:-16 } },
    { l:'② 실을 조여 다섯을 한 걸음에 세운다.', k:'bond', dc:25,
      ok:`다섯 실을 한 손에 모아 당겼다. 다섯 걸음이 한 박자에 섰다.<br><br>반 숨 뒤, 방금 디디려던 자리로 어둠이 떨어졌다. 바닥이 울리는 무게였다.<br>헛친 것은 두 번 안 친다. 체면이 상한 걸음으로 물러났다. 다섯이 선 자리는 반걸음 차이로 성했다.`,
      ng:`당기는 실에 맨 앞 팀원이 놀라 되물으며 반걸음 더 나갔다.<br><br>그 반걸음을 어둠이 스쳤다. 어깨 천이 날아가고 살이 길게 긁혔다.<br>끌어내 지혈했다. 실 신호를 미리 가르쳐 두지 않은 이쪽 불찰이다. 그날 밤 신호부터 다시 가르쳤다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-32, mind:-16 } }
  ] },

{ at:'S', t:'여섯째 기척',
  x:`따라붙은 것이 안 떨어진다. 다섯 기척을 세며 온다. 꾸준히, 지치지도 않고.<br><br>
    기척을 지우는 건 늦었다. 이미 센 수는 못 지운다.<br>
    그러면 수를 늘리는 수가 남는다. 없는 여섯째를 하나 짜서, 다른 길로 걷게 하는 것.<br><br>
    실로 짠 기척은 속이 비었다. 멀리서는 모르지만 가까이서는 들킨다. 거리가 생명이다.`,
  o:[
    { l:'① 여섯째 기척을 짜서 옆 통로로 흘린다.', k:'bond', dc:25, cost:{ mana:35 },
      ok:`실을 겹쳐 사람 숨과 발소리 꼴로 짰다. 어설프지만 걷는 꼴이 나왔다.<br><br>여섯째를 옆 통로로 걸려 보냈다. 절뚝이게. 뒤처진 하나처럼. 쫓는 것은 셈을 바꿨다. 다섯보다 절뚝이는 하나가 싸니까.<br>그것이 옆 통로로 꺾이는 기척을 들으며 반대로 걸었다. 여섯째는 통로 끝에서 풀려 흩어졌을 것이다. 수고했다.`,
      ng:`짜 놓은 기척의 숨이 너무 골랐다. 지친 사람 숨이 아니었다.<br><br>쫓는 것이 반 통로만 따라가다 돌아섰다. 가짜를 알아본 것이다.<br>속이려던 상대에게 속임수를 들키면 값이 배로 뛴다. 그날 추격은 전보다 집요해졌다. 밤을 꼬박 새워 따돌렸다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-19, spirit:-21 } },
    { l:'② 실을 끊지 않고 쥔 채 저쪽 반응을 읽는다.', k:'gaze', dc:25,
      doom:{ title:'되감긴 실', what:'실을 따라 어둠 속으로 끌려갑니다', dc:19, sec:42,
        text:`여섯째에 건 실을 끊지 않고 쥐고 있었다. 저쪽이 미끼를 무는 순간을 읽으려고.<br><br>물긴 물었다. 그리고 실을 물었다.<br><br>실이 팽팽해지더니 되감기기 시작했다. 낚싯줄 거꾸로 감듯이. 쥔 손이 펴지지 않는다. 몸이 통로를 쓸려 간다. 미끼 던진 쪽이 걸려들었다.`,
        dieText:`팀원들에게 실은 안 보였다. 빈 허공에 손을 앞세우고 끌려가는 모습만 보였다.<br><br>모퉁이에서 실 끊는 칼이 반 박자 늦었다.<br>그 통로에는 아직 실이 걸려 있다. 가끔 팽팽해졌다 늘어진다. 저쪽 끝에서 무엇이 심심할 때마다 감아 보는 것이다.` },
      ok:`실 끝을 느슨히 쥐고 저쪽 반응을 읽었다. 무는 순간, 무는 힘, 무는 방향.<br><br>급하게 물지 않았다. 세 번 재고 물었다. 영리한 놈이라는 뜻이다.<br>무는 순간 실을 놓았다. 미끼는 저쪽에, 정보는 이쪽에. 영리한 놈은 영리한 만큼 가짜에 오래 붙들린다. 그 시간에 두 층을 벌었다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S', t:'남의 팀의 엉킨 실',
  x:`갈림길에서 만난 팀이 이상하다. 넷이 사는데 서로 눈을 안 본다.<br><br>
    이쪽 눈에는 보인다. 그들 사이 실이 참혹하게 엉켰다. 둘은 서로의 목을 감듯 조였고, 하나는 모두에게서 끊겨 혼자 떠 있다.<br>
    무언가에 쫓기다 하나를 두고 왔다고 했다. 그 뒤로 이렇다고.<br><br>
    엉킨 실은 저절로 안 풀린다. 더 조여들 뿐이다.`,
  o:[
    { l:'① 엉킨 실을 하나씩 푼다.', k:'bond', dc:24,
      ok:`네 사람을 불가에 둘러앉혔다. 그리고 실을 짚으며 물었다. 두고 온 사람 이름이 뭐냐고.<br><br>이름이 나오자 조였던 실이 떨렸다. 한 명씩, 그 사람 얘기를 했다. 잘 웃었다고. 코를 골았다고.<br>얘기가 도는 동안 엉킨 올이 한 가닥씩 느슨해졌다. 다 풀리진 않았다. 그래도 목을 감던 실이 어깨로 내려왔다. 그 정도면 걸을 수 있다.`,
      ng:`실을 짚으며 이름을 묻자 넷 중 하나가 일어나 멱살을 잡았다. 네가 뭘 아느냐고.<br><br>엉킨 실은 건드리면 당긴 쪽으로 조인다. 넷의 실이 한꺼번에 울었다.<br>그 팀은 그 길로 갈라져 둘씩 다른 길로 갔다. 말릴 새도 없었다. 못 푼 매듭은 오래 마음에 남는다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-19, spirit:-22 } },
    { l:'② 제일 팽팽한 실부터 끊는다.', k:'break', dc:25,
      ok:`서로의 목을 감은 두 올 중 더 팽팽한 쪽을 끊었다. 원망이 도는 올이다.<br><br>끊기는 순간 둘이 동시에 숨을 크게 쉬었다. 목 졸리던 사람들처럼.<br>남은 올은 헐거워서 저희끼리 풀렸다. 다 살리는 묶음이 있고, 끊어서 살리는 묶음이 있다.`,
      ng:`팽팽한 올을 끊자 반동이 왔다. 감겨 있던 원망이 갈 곳을 잃고 이쪽을 쳤다.<br><br>영문 모를 어지럼에 주저앉았다. 코피가 흘렀다.<br>그 팀 넷이 이쪽을 내려다보고 있었다. 고마워하는 눈이 아니었다. 제 것을 잃은 눈이었다. 원망도 제 것은 제 것이다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, spirit:-20 } },
    { l:'③ 끊겨 떠 있는 하나를 이쪽 그물에 받아 준다.', k:'bond', dc:24, wake:1,
      ok:`혼자 떠 있는 실의 임자에게 갔다. 두고 온 사람과 제일 가까웠던 사람이다. 그래서 끊긴 것이다.<br><br>이쪽 실 한 올을 건넸다. 남는 자리라고. 임시라고.<br>그 사람이 올을 받아 쥐었다. 쥔 손이 오래 떨렸다. 걷기 시작했을 때 그 사람 발이 제일 앞에 있었다.<br><br>그물은 제 팀만 거는 게 아니다. 떨어져 나온 남도 임시로 받는다. 받는 자리를 비워 두는 것까지가 이 일이라는 걸 알았다.`,
      ng:`올을 건넸는데 그 사람이 고개를 저었다. 또 끊어질 바엔 안 걸겠다고.<br><br>한 번 끊긴 실의 임자는 실을 무서워한다. 억지로 걸 수는 없다.<br>그 사람은 제 팀 뒤를 혼자 따라갔다. 다섯 걸음 떨어져서. 그 다섯 걸음이 종일 눈에 밟혔다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'S', t:'이름을 거두는 밤',
  x:`어젯밤 어둠이 막내 이름을 불렀다. 막내 어머니 목소리로.<br><br>
    이름은 실이다. 부르면 당겨진다. 이 어둠은 그 실을 쥐는 법을 안다.<br>
    사람이 사람을 부르는 걸 막을 수는 없다. 부를 다른 것을 주면 된다.<br><br>
    실 당김 신호. 한 번은 서라, 두 번은 와라, 세 번은 뛰어라. 이름 없이도 부를 수 있게.`,
  o:[
    { l:'① 이름을 거두고 당김 신호를 가르친다.', k:'bond', dc:24, wake:1,
      ok:`저녁 내 연습시켰다. 한 번, 두 번, 세 번. 손목의 실이 말이 될 때까지.<br><br>밤에 어둠이 또 막내 이름을 불렀다. 어머니 목소리로, 다정하게.<br>아무도 대답하지 않았다. 막내도. 이름은 어제 거뒀으니까. 대신 이쪽이 실을 한 번 당겼다. 서라. 다섯이 섰고, 목소리는 혼자 부르다 지쳤다.<br><br>이름을 쥐려는 것에게서 이름을 치우는 법. 부르는 것과 당기는 것의 차이를 배웠다. 당기는 쪽이 늘 이긴다.`,
      ng:`신호를 익히다 말고 막내가 물었다. 그럼 제 이름은 언제 돌려받느냐고.<br><br>그 말에 다들 말문이 막혔다. 이름을 거둔다는 게 뺏는 걸로 들린 것이다.<br>그날 밤 목소리가 불렀을 때 막내 어깨가 움찔했다. 대답은 안 했지만, 움찔한 것까지 어둠은 봤을 것이다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-21 } },
    { l:'② 이름을 바꿔 부르기로 한다 — 가짜 이름으로.', k:'fix', dc:23,
      ok:`저마다 번호를 매겼다. 하나부터 다섯. 이름은 입 밖에 안 내기로.<br><br>어둠은 며칠 묵은 이름만 쥐고 불렀다. 아무도 그 이름에 안 돌아봤다.<br>번호는 정이 안 들어서 좋다. 정 안 든 말은 당겨지지도 않는다.`,
      ng:`사흘은 번호로 버텼다. 나흘째 급한 순간에 둘이 서로 이름을 불렀다.<br><br>급하면 혀가 먼저 나간다. 불린 이름 둘을 어둠이 주웠다.<br>그날 밤부터 목소리가 둘을 번갈아 불렀다. 번호 연습을 처음부터 다시 했다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-17, spirit:-19 } }
  ] },

{ at:'S', t:'끌려간 자리의 실',
  x:`다른 팀 야영지가 반쯤 무너져 있다. 셋이 벽에 붙어 떨고, 하나가 없다.<br><br>
    없는 하나의 실이 보인다. 야영지에서 어둠 안쪽으로, 팽팽하게.<br>
    팽팽하다는 건 저쪽 끝에 아직 무게가 있다는 것이다. 시체는 실을 놓는다. 산 사람만 실을 쥔다.<br><br>
    셋은 못 간다고 했다. 실은 이쪽 눈에만 보인다.`,
  o:[
    { l:'① 실을 감으며 따라 들어간다.', k:'bond', dc:26,
      doom:{ title:'실 끝의 어둠', what:'실 끝의 어둠으로 끌려갑니다', dc:20, sec:40,
        text:`실을 한 발씩 감으며 들어갔다. 실은 아래로, 틈으로, 더 아래로.<br><br>실이 갑자기 느슨해졌다. 저쪽 무게가 사라진 게 아니라, 이쪽으로 오고 있는 것이다.<br><br>감던 실이 손에 엉긴 채 어둠이 덮쳤다. 실 임자를 저장한 그것이, 실을 타고 온 것까지 챙기러 왔다.`,
        dieText:`남은 셋은 입구에서 실도 사람도 못 봤다. 어둠이 한 번 출렁인 것만 봤다.<br><br>한참 뒤 틈 안쪽에서 실 감개 하나가 굴러 나왔다. 반쯤 감긴 채였다.<br>셋은 그걸 주워 들고 울었다. 누구 몫으로 울었는지는 셋도 몰랐을 것이다.` },
      ok:`실을 감으며 틈 아래로 내려갔다. 실이 끝나는 곳에 움푹한 어둠이 있었다.<br><br>없어진 하나가 바위 틈에 끼워져 있었다. 산 채로, 이끼에 반쯤 덮여서. 저장된 것이다.<br>입을 막고 빼냈다. 실을 되감으며 돌아 나오는 길, 등 뒤 어둠이 두 번 뒤척였다. 돌아보지 않았다. 감던 실만 셌다.<br><br>맡긴 것을 찾아오듯 조용히. 그게 이 일의 제일 깊은 자리다.`,
      win:{ exp:25, dream:4 } },
    { l:'② 실에 귀를 대 살았는지만 확인한다.', k:'sense', dc:24,
      ok:`실에 손끝을 얹고 숨을 죽였다. 맥이 온다. 느리지만 고르게.<br><br>살아 있고, 잠들어 있다. 위치는 실의 기울기로 쟀다. 아래층 물가 쪽 틈.<br>셋에게 알려 주고 이쪽 팀과 합쳐 여덟로 내려갔다. 여덟이면 저장고를 털 수 있다. 털었다. 산 사람 하나가 돌아왔다.`,
      ng:`손끝을 얹은 순간 실이 길게 울고, 느슨해졌다.<br><br>맥이 끊긴 게 아니라 실이 뽑힌 것이다. 저쪽에서. 눈치챈 것이다.<br>기울기를 다 재기 전이었다. 아래층 어디, 물가 쪽 어디. 그 어림만 들고 내려가는 걸음이 무거웠다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-19, spirit:-21 } }
  ] },

{ at:'S1', t:'숙주와 기생체 사이',
  x:`앓는 팀원의 가슴에 손을 얹자 보였다. 속에 든 것이 실을 짜고 있다.<br><br>
    숙주의 실에 제 실을 섞어 넣는다. 숨에 한 올, 맥에 한 올. 뽑으면 숙주까지 딸려 나오게.<br>
    영리한 직조다. 소름 끼치게 영리한.<br><br>
    다만 짜는 것은 풀 수도 있다. 시간과 손끝이 있다면.`,
  o:[
    { l:'① 밤새 한 올씩 되감아 뺀다.', k:'bond', dc:26, wake:1, cost:{ mana:36 },
      ok:`팀원을 눕히고 가슴 위에서 밤을 샜다. 속엣것이 짠 올을 한 올씩, 숙주의 실과 가려 가며 되감았다.<br><br>속엣것이 눈치채고 더 빨리 짰다. 이쪽은 더 천천히 풀었다. 빠른 직조는 성기다. 성긴 것은 잘 풀린다.<br>동틀 무렵 속엣것의 실이 숙주에게서 다 떨어졌다. 둥둥 뜬 그것은 제 실에 제가 감겨 조용해졌다. 의원이 손쓸 자리가 생겼다.<br><br>묶는 일의 절반이 푸는 일이라는 걸 알았다. 푸는 손은 묶는 손보다 느려야 한다. 평생 쓸 손이 하나 더 생겼다.`,
      ng:`세 올째에서 속엣것이 직조를 바꿨다. 이쪽 되감는 손을 배운 것이다.<br><br>풀면 두 올을 짜고, 또 풀면 세 올을 짰다. 밤새 쫓다가 손이 먼저 저렸다.<br>동틀 무렵 포기했다. 팀원은 더 창백해졌고, 이쪽은 빈 마력으로 하루를 걸었다. 배우는 상대와는 손 승부를 길게 끌면 안 된다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 숙주의 실을 두껍게 감아 버티게 한다.', k:'heal', dc:24,
      ok:`뺄 수 없으면 버티게 한다. 숙주의 숨과 맥에 실을 덧감아 속엣것이 파고들 자리를 메웠다.<br><br>속엣것의 직조가 느려졌다. 빈 올이 없으니까.<br>그 상태로 의무동까지 데려갔다. 완치는 아니다. 다만 시간을 이틀 벌었고, 이 바닥에서 이틀이면 산 것이다.`,
      ng:`덧감은 실이 숙주의 숨까지 조였다. 얼굴이 파래졌다.<br><br>급히 반을 풀었다. 그 틈에 속엣것이 두 올을 더 짰다.<br>버는 시간과 잃는 숨 사이에서 반나절을 씨름했다. 결국 얇게 감는 선에서 멈췄다. 모자란 건 걸음으로 메웠다. 의무동까지 뛰다시피 갔다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-27, mind:-17 } }
  ] },

{ at:'S1', t:'에어록 — 사이의 어둠',
  x:`안문이 닫히고 바깥문이 열리기까지, 에어록 안은 완전한 어둠이다.<br><br>
    경고판에 적혀 있다. 순환 중 조명 꺼짐 — 삼십 초.<br>
    삼십 초면 사람이 흩어지기 충분하다. 어둠 속에서 손을 놓치면, 문이 열렸을 때 다섯이 다 있으리란 법이 없다. 이 시설에서는.<br><br>
    바닥 배수구에서 벌써 축축한 냄새가 올라온다.`,
  o:[
    { l:'① 다섯 손목을 한 실로 꿰어 순환을 견딘다.', k:'bond', dc:24,
      ok:`들어가기 전에 손목 다섯을 실 하나로 꿰었다. 당기면 다 같이 당겨지게.<br><br>어둠 삼십 초. 배수구 쪽에서 무엇이 실을 건드렸다. 다섯이 동시에 그 떨림을 느끼고 동시에 벽 쪽으로 붙었다.<br>문이 열렸을 때 다섯 손목이 다 제자리에 있었다. 실 가운데가 축축했다. 만져 본 것이다. 다섯 묶음은 입에 안 맞았는지, 그뿐이었다.`,
      ng:`어둠 속에서 막내가 기척에 놀라 손을 홱 당겼다. 실이 손목을 파고들었다.<br><br>아픈 쪽이 또 당기고, 당겨진 쪽이 넘어졌다. 어둠 속 삼십 초가 엉킨 몸싸움이 됐다.<br>문이 열렸을 때 다섯은 다 있었다. 바닥에 뒤엉킨 채로. 손목마다 실 자국이 벌겋게 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 문틀에 실을 걸어 버팀줄을 만든다.', k:'steady', dc:24,
      ok:`안문 틀과 바깥문 틀에 실을 걸어 허리 높이 버팀줄을 쳤다. 다섯이 그 줄을 쥐고 섰다.<br><br>어둠 속에서 줄이 한 번 아래로 출렁였다. 배수구 쪽에서 무게가 실렸다 빠진 것이다.<br>아무도 소리 내지 않았다. 줄을 쥔 손들에 힘이 들어갔을 뿐. 문이 열리고, 줄을 걷고, 아무 일 없던 얼굴로 나왔다. 그런 얼굴이 되는 데 다들 이골이 났다.`,
      ng:`바깥문 틀 거는 고리가 녹슬어 있었다. 어둠 속에서 그쪽 실이 빠졌다.<br><br>줄이 반만 남자 다섯이 한쪽으로 쏠렸다. 누가 누굴 밟았는지 모를 삼십 초.<br>문이 열리고 보니 막내 코에서 피가 나고 있었다. 팔꿈치에 맞았단다. 누구 팔꿈치인지는 아무도 자백 안 했다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S1', t:'환풍구 — 잘리는 생명줄',
  x:`환풍구를 기어서 건너는 수밖에 없다. 앞사람부터 차례로, 허리에 실을 걸고.<br><br>
    둘째가 들어갔을 때 실이 울었다. 끊긴 울음. 둘째 쪽 실이 매끈하게 잘려 있다.<br>
    씹힌 게 아니다. 잘렸다. 날붙이처럼 매끈하게.<br><br>
    관 속 어딘가에 실을 자르는 법을 아는 것이 산다. 생명줄부터 자르는 법을.`,
  o:[
    { l:'① 잘린 자리마다 매듭을 새로 묶으며 간다.', k:'bond', dc:25,
      ok:`잘리면 잇는다. 한 뼘 기고, 매듭 하나. 손끝이 외울 때까지 같은 박자로.<br><br>관 속의 것은 세 번 잘랐다. 세 번 다 반 숨 만에 매듭이 다시 섰다.<br>네 번째는 안 잘랐다. 자르는 족족 이어지는 실은 자를 맛이 없는 것이다. 출구까지 매듭 열일곱 개. 전부 손끝이 기억한다.`,
      ng:`세 번째 매듭을 묶는 손 옆으로 무엇이 스쳤다. 차갑고 매끈한 것.<br><br>손이 움찔한 사이 실이 또 잘렸다. 이번엔 매듭 바로 위를.<br>묶는 속도가 자르는 속도를 못 따라갔다. 결국 실을 포기하고 서로 발목을 잡고 기었다. 출구까지의 어둠이 유난히 길었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-17 } },
    { l:'② 실을 미끼로 관에 두고 다른 관으로 돈다.', k:'evade', dc:24,
      ok:`실 한 타래를 풀어 원래 관에 길게 늘어놓았다. 사람 다섯이 기어가는 꼴로 띄엄띄엄.<br><br>그리고 옆 관으로 돌았다. 좁고 더럽지만 잘린 실이 없는 관.<br>원래 관 쪽에서 실 잘리는 소리가 박자 맞춰 들렸다. 하나, 둘, 셋, 넷, 다섯. 다 자르고 나서야 빈 실인 걸 알았을 것이다. 그때 이쪽은 관을 다 빠져나와 있었다.`,
      ng:`옆 관이 중간에서 좁아졌다. 어깨가 끼었다.<br><br>뒤로 뺄 수도 앞으로 갈 수도 없는 한참. 등 뒤 관 어딘가에서 실 잘리는 소리가 다가왔다.<br>어깨뼈가 쓸리도록 비틀어 빠졌다. 외투가 반쯤 찢겨 관 속에 남았다. 외투 값은 비쌌지만 어깨 값보다는 쌌다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'S1', t:'여왕의 그물',
  x:`아래층으로 내려서다 멈췄다. 복도 전체에 그물이 쳐져 있다.<br><br>
    이쪽 눈에만 보이는 종류다. 벽에서 벽으로, 배관에서 바닥으로. 수백 올.<br>
    올 하나하나가 안쪽 깊은 데로 모인다. 거미줄이 거미에게 모이듯. 이 시설의 가장 깊은 방으로.<br><br>
    올에 닿으면 저쪽이 안다. 떨림은 실을 타니까. 그건 이쪽이 제일 잘 안다.`,
  o:[
    { l:'① 올 사이 성긴 자리를 읽어 길을 낸다.', k:'bond', dc:26,
      ok:`그물에도 결이 있다. 짠 지 오래돼 늘어진 자리, 급히 짜서 성긴 자리.<br><br>성긴 자리만 골라 다섯을 통과시켰다. 몸을 접고, 숨을 접고, 한 사람씩.<br>마지막 올을 지날 때 그물 전체가 아주 천천히 숨 쉬는 게 보였다. 그물이 아니라 코였다. 냄새를 거르는. 안 닿길 잘했다는 말로는 모자랐다.`,
      ng:`성긴 자리를 반쯤 지났을 때 뒤쪽 팀원의 배낭 끈이 올 하나를 스쳤다.<br><br>떨림이 올을 타고 안쪽으로 달려갔다. 등불이 꺼지듯 복도 공기가 바뀌었다.<br>남은 그물을 찢다시피 뚫고 뛰었다. 깊은 데서 무엇이 일어나는 진동이 발바닥으로 왔다. 그 층 문이란 문은 다 잠그고서야 숨을 돌렸다.`,
      win:{ exp:25, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 올 하나를 튕겨 가짜 신호를 보낸다.', k:'luck', dc:25,
      ok:`구석 올 하나를 손톱으로 튕겼다. 동쪽 날개 끝, 여기서 제일 먼 자리의 떨림을 흉내 내서.<br><br>그물이 일제히 동쪽으로 기울었다. 복도의 올들이 그쪽으로 당겨지며 성겨졌다.<br>그 틈에 다섯이 지났다. 거미의 그물로 거미를 부리는 짓이다. 두 번 할 짓은 못 되지만 한 번은 통했다.`,
      ng:`튕긴 떨림이 어설펐다. 그물이 동쪽으로 기울다 말고 멈췄다.<br><br>가짜를 의심하는 정지였다. 그리고 그물 전체가 이쪽 방향으로 조금씩 조여들기 시작했다.<br>성긴 자리고 뭐고 없어졌다. 왔던 계단으로 물러나 반나절을 돌았다. 그물은 다음 날에야 제자리로 풀렸다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-21, spirit:-25 } },
    { l:'③ 그물에 제 실을 섞어 한 올처럼 붙어 간다.', k:'hide', dc:26,
      doom:{ title:'그물의 셈', what:'그물에 감겨 깊은 방으로 끌려갑니다', dc:20, sec:38,
        text:`제 실을 그물 올에 나란히 붙였다. 같은 떨림, 같은 결. 그물의 일부가 되어 올을 타고 건넜다.<br><br>반쯤 건넜을 때 그물이 알았다. 제 올은 제 숨으로 떨고, 이쪽 올은 이쪽 숨으로 떠니까.<br><br>수백 올이 한꺼번에 감겨 왔다. 고치처럼. 그리고 그물이 모이는 방향으로, 깊은 쪽으로, 실려 가기 시작했다.`,
        dieText:`팀원들 눈에는 허공에서 몸이 떠서 복도 안쪽으로 미끄러져 가는 것만 보였다.<br><br>쫓아간 복도 끝은 막힌 벽이었다. 벽 아래 틈으로 바람이 드나들었다. 숨처럼.<br>그 층을 뜨는 날까지, 벽 너머에서 가끔 실 감는 소리가 났다. 아주 정성스러운 소리였다.` },
      ok:`제 실을 그물 올에 붙이고 떨림까지 베꼈다. 저쪽 숨에 맞춰 떨리게.<br><br>그물은 끝까지 몰랐다. 제 올이 하나 는 줄로 알았을 것이다.<br>건너편에서 실을 떼어 내는 순간 손끝이 저렸다. 한동안 이쪽 실이 저쪽 숨으로 떨었다. 돌아오는 데 시간이 걸렸다. 너무 잘 베끼는 것도 병이다.`,
      win:{ exp:25, dream:4 } }
  ] },

{ at:'S1', t:'단지에 걸린 실',
  x:`표본 선반의 단지들이 비어 보이지만 비어 있지 않다. 단지마다 실이 걸려 있다.<br><br>
    가늘게, 천장 배관을 타고, 깊은 방 쪽으로. 젖줄처럼.<br>
    이 단지들은 아직 저쪽 살림의 일부다. 선반을 지나려면 단지 사이로 어깨를 틀어야 하는데, 실 하나라도 당겨지면 저쪽이 안다.<br><br>
    단지 하나는 길목에 있어서 옮기지 않고는 못 지난다.`,
  o:[
    { l:'① 실이 당겨지지 않게 단지를 받쳐 든 채 옮긴다.', k:'bond', dc:25,
      ok:`단지에 걸린 실의 늘어짐을 눈으로 쟀다. 두 뼘. 두 뼘 안에서만 움직이면 된다.<br><br>단지를 수평으로, 실이 늘어진 호를 그대로 따라 옮겼다. 숨을 반으로 줄이고.<br>내려놓은 단지의 실이 처음과 같은 깊이로 늘어졌다. 저쪽 살림은 아무것도 몰랐다. 남의 집 세간은 건드린 줄 모르게 건드리는 것이다.`,
      ng:`옮기는 중에 단지 속에서 무엇이 뒤척였다. 빈 줄 알았던 단지가.<br><br>놀란 손이 반 뼘 처졌다. 실이 팽팽해졌다 풀렸다.<br>배관 너머 깊은 데서 무엇이 한 번 크게 뒤척이는 소리가 왔다. 단지를 내려놓고 뛰었다. 선반 사이가 미로 같았다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-21, spirit:-23 } },
    { l:'② 실이 안 닿는 선반 뒤로 길을 잡는다.', k:'sense', dc:24,
      ok:`실들이 다 천장 쪽으로 걸렸다는 걸 봤다. 그럼 바닥에 바싹 붙으면 된다.<br><br>선반 맨 아랫단, 먼지와 깨진 유리 사이로 기었다. 실의 그늘 밑으로만.<br>다 지나고 일어서자 무릎과 손바닥이 새까맸다. 더러운 길이 안전한 길인 날이 있다. 이 시설에선 매일이 그렇다.`,
      ng:`아랫단을 기다가 깨진 유리를 짚었다. 손바닥이 베였다.<br><br>피 냄새가 선반 사이에 퍼졌다. 단지 몇 개가 안쪽에서 일제히 뒤척였다.<br>남은 길을 구르다시피 빠져나왔다. 손바닥 상처보다 그 뒤척이는 소리가 오래 남았다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'S1', t:'산성 피 — 녹아내린 다리',
  x:`통로 바닥이 녹아 뚫렸다. 가장자리가 아직 연기를 문다. 검은 피가 지나간 자리다.<br><br>
    구멍 건너편에 다른 팀 하나가 매달려 있다. 발밑은 아래층 어둠.<br>
    실을 던지면 닿는다. 다만 구멍 가장자리에 피가 남아 있다. 실이 닿으면 실이 녹는다.<br><br>
    아래층 어둠에서 젖은 숨소리가 올라온다. 떨어지기를 기다리는 숨이다.`,
  o:[
    { l:'① 열 매듭으로 나눠 짧게 짧게 끌어올린다.', k:'bond', dc:25,
      ok:`실을 길게 쓰지 않았다. 팔 길이씩 열 토막, 토막마다 매듭.<br><br>녹는 건 피에 닿은 토막뿐이다. 녹으면 그 토막만 버리고 다음 매듭을 쥐게 했다.<br>세 토막을 버리고 그 사람을 올렸다. 손바닥에 매듭 자국이 열 개. 실은 아끼는 게 아니라 끊어 쓰는 것이다. 여기서는.`,
      ng:`네 번째 토막이 생각보다 빨리 녹았다. 매달린 사람이 한 뼘 떨어졌다.<br><br>비명이 아래층 숨소리를 깨웠다. 젖은 것이 벽을 타고 올라오기 시작했다.<br>남은 토막을 다 이어 억지로 끌어올렸다. 올라온 사람 장화 뒤축이 녹아 있었다. 한 뼘 아래가 어디까지였는지는 아무도 안 쟀다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-29, spirit:-16 } },
    { l:'② 제 몸을 실에 걸고 내려가 받친다.', k:'steady', dc:25,
      doom:{ title:'녹은 바닥 아래', what:'구멍 아래 어둠으로 끌려 내려갑니다', dc:19, sec:44,
        text:`허리에 실을 감고 구멍 안으로 내려섰다. 매달린 사람 발밑을 어깨로 받쳤다.<br><br>그때 아래층의 젖은 숨이 닿을 만큼 가까워졌다. 발목에 축축한 것이 감겼다.<br><br>실이 팽팽해지고, 허리가 꺾이고, 몸이 아래로 미끄러진다. 받치러 간 무게까지 셈에 넣은 것이다. 처음부터.`,
        dieText:`팀원들이 실을 당겼을 때 올라온 것은 녹다 만 실 끝뿐이었다.<br><br>매달렸던 사람은 그 사이 제 힘으로 기어 올라왔다. 그 사람은 두고두고 말한다. 발밑을 받쳐 준 어깨가 있었다고.<br>구멍은 다음 날 더 넓어져 있었다. 아래층 숨소리는 더 느긋해졌다.` },
      ok:`허리에 실을 감고 내려가 어깨로 받쳤다. 그 사람이 이쪽 어깨를 밟고 가장자리를 넘었다.<br><br>발밑 어둠에서 젖은 숨이 코앞까지 왔다. 올려다보는 눈 같은 건 안 보였다. 그게 더 나빴다.<br>실이 당겨지고 몸이 떠올랐다. 가장자리를 넘는 순간 발꿈치 아래에서 공기가 턱 닫히는 소리가 났다. 반 숨 차이였다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S1', t:'마지막 실 한 타래',
  x:`마력이 바닥을 보인다. 실 한 타래 분량. 그게 전부다.<br><br>
    남은 길은 두 층. 어디에 쓸지 정해야 한다.<br>
    다섯에게 가늘게 나누면 다 끊어질 듯 약하고, 하나에게 몰면 넷이 맨몸이다.<br><br>
    묶는 자의 살림은 늘 이 셈으로 돌아온다. 모자란 실을 어디에 걸 것인가.`,
  o:[
    { l:'① 다섯 모두에게 — 끊어질 만큼 가늘게 한 올씩.', k:'bond', dc:25, wake:1,
      ok:`타래를 다섯으로 갈라 가늘게 걸었다. 입김에도 끊어질 올이다.<br><br>그런데 끊어지지 않았다. 다섯이 올이 가는 걸 아니까, 저마다 올이 안 끊어지게 걸었다. 당기지 않고, 벌리지 않고.<br>두 층을 그 올로 내려왔다. 마지막 계단에서 보니 올들이 처음보다 굵어 보였다.<br><br>실이 사람을 묶는 게 아니라 사람이 실을 지킨다는 것. 가늘게 걸수록 단단해지는 역설. 이 일의 바닥 이치를 만졌다.`,
      ng:`가늘게 건 올 하나가 첫 계단에서 끊겼다. 막내 올이었다.<br><br>끊긴 걸 안 막내가 말을 안 했다. 걱정 끼치기 싫어서.<br>두 층 내내 막내만 맨몸이었던 걸 바닥에 닿아서야 알았다. 아무 일 없었으니 다행이 아니라, 아무 일 없었던 게 요행이다. 그 차이에 등골이 식었다.`,
      win:{ exp:24, dream:3, spirit:7 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 제일 약한 하나에게 전부.', k:'heal', dc:24,
      ok:`다리를 저는 팀원에게 타래를 다 걸었다. 무릎에, 발목에, 허리에.<br><br>실이 다리 노릇을 했다. 저는 걸음이 걷는 걸음이 됐다.<br>대열에서 제일 느린 사람이 보통이 되면 대열 전체가 보통이 된다. 넷의 맨몸은 서로 눈으로 가렸다. 눈도 실의 일종이다.`,
      ng:`실을 다 건 다리가 오히려 뻣뻣해졌다. 실에 기대자 제 힘을 놓은 것이다.<br><br>계단 중턱에서 실 감긴 다리가 접혔다. 둘이 부축해서 내려왔다.<br>실이 떠받치는 것과 대신 걷는 것은 다르다. 그 선을 넘게 감은 이쪽 손이 서툴렀다.`,
      win:{ exp:16, dream:2, hp:5 }, lose:{ hp:-26, mind:-16 } },
    { l:'③ 타래를 아껴 두고 맨눈과 맨손으로 버틴다.', k:'steady', dc:25,
      ok:`타래를 품에 넣고 묶지 않았다. 대신 손을 잡게 했다. 옛날 방식으로.<br><br>실 없이 두 층을 내려오는 동안 뒤가 세 번 서늘했다. 그때마다 손들이 먼저 조여졌다.<br>바닥에 닿았을 때 타래는 그대로 품에 있었다. 안 쓴 실이 제일 질긴 실일 때도 있다. 다음 순간을 위해 남겨 둔 실.`,
      ng:`맨손의 두 층은 길었다. 어둠이 손 잡은 틈을 두 번 치고 빠졌다.<br><br>두 번째에 둘의 손이 떨어졌다. 떨어진 반 숨에 하나가 계단을 헛디뎠다.<br>굴러떨어진 팀원을 안고 남은 반 층을 내려왔다. 품속 타래가 종일 돌덩이 같았다. 아낀 게 아니라 아까워한 것 아닌가, 그 생각이 제일 무거웠다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, spirit:-18 } }
  ] },

{ at:'S2', t:'무리의 실',
  x:`울타리 너머 그것들을 오래 봤다. 이쪽 눈에는 그것들 사이의 실이 보인다.<br><br>
    촘촘하다. 부끄러울 만큼. 사람 다섯을 이렇게 묶어 본 적이 없다.<br>
    장에게서 뻗은 실이 여섯을 부리고, 여섯의 실이 서로를 받친다. 한 몸처럼 도는 그물.<br><br>
    다만 그물에도 성긴 데가 있다. 물가 쪽. 그쪽 올만 유난히 가늘고 떨린다.`,
  o:[
    { l:'① 올이 성긴 물가 쪽으로 팀을 돌린다.', k:'bond', dc:25, wake:1,
      ok:`그물이 가는 쪽은 마음이 가는 쪽이 아니라 겁이 가는 쪽이다. 그것들은 물가를 겁낸다.<br><br>겁내는 자리는 뒤지지 않는다. 물가 바위를 타고 그것들의 그물 바깥으로 돌았다.<br>한 번도 쫓기지 않았다. 그것들의 겁이 이쪽 길이 되어 줬다.<br><br>남의 결속을 읽으면 남의 두려움까지 읽힌다는 것. 묶는 눈은 푸는 눈이고, 푸는 눈은 빠져나가는 눈이다.`,
      ng:`물가 쪽으로 도는데 그물의 성긴 올이 갑자기 팽팽해졌다. 장이 그쪽을 본 것이다.<br><br>겁내는 자리라고 안 보는 자리는 아니다.<br>바위 뒤에 반나절을 붙어 있었다. 장의 실이 느슨해질 때까지. 물가의 축축한 바람에 뼈까지 식었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 무리의 실 한 올을 당겨 본다.', k:'luck', dc:26,
      ok:`제일 바깥 어린 놈의 올을 살짝 당겼다. 장의 부름을 흉내 내서.<br><br>어린 놈이 무리에서 떨어져 두리번거렸다. 그물에 구멍이 하나 열렸다.<br>그 구멍으로 다섯이 지났다. 어린 놈은 한참 헤매다 돌아갔을 것이다. 좀 미안했다. 좀만.`,
      ng:`당긴 올이 장의 올이었다. 바깥 올인 줄 알았는데.<br><br>장이 그 자리에서 돌아봤다. 당긴 손을 찾는 눈으로. 그물 전체가 이쪽으로 기울었다.<br>풀숲을 버리고 바위 비탈로 뛰었다. 발톱 소리가 비탈 아래까지 따라왔다. 남의 그물은 함부로 당기는 게 아니다.`,
      win:{ exp:16, dream:3 }, lose:{ hp:-31, mind:-17 } }
  ] },

{ at:'S2', t:'철망의 떨림',
  x:`울타리 철망도 실이다. 굵고 녹슨 실.<br><br>
    손끝을 대면 떨림이 읽힌다. 먼 구간에서 그것들이 미는 떨림, 바람의 떨림, 그리고 발톱이 긁는 떨림.<br>
    다음에 어디를 밀지, 떨림은 밀기 전에 먼저 온다. 힘이 실리는 쪽 올이 미리 우니까.<br><br>
    건널 자리를 고르는 데 이보다 좋은 귀는 없다.`,
  o:[
    { l:'① 철망에 실을 매어 떨림을 읽고, 빈 구간으로 건넌다.', k:'bond', dc:24,
      ok:`철망 세 군데에 실을 걸고 손끝에 모았다. 떨림의 지도가 손안에 들어왔다.<br><br>북쪽 올이 울기 시작했다. 다음 시험은 북쪽. 그럼 남쪽이 빈다.<br>남쪽 구간을 넘었다. 넘는 동안 북쪽에서 철망 우는 소리가 크게 났다. 저쪽 일과가 이쪽 시계가 됐다.`,
      ng:`떨림을 읽는 중에 큰 떨림이 왔다. 읽던 모든 올이 한꺼번에 울었다.<br><br>시험이 아니라 돌진이었다. 북쪽 철망이 안으로 휘었다.<br>읽기고 뭐고 남쪽으로 뛰어 넘었다. 뒤에서 철망 윗단 가시가 울타리째 울었다. 지도는 다 못 그렸지만 목숨은 건사했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 떨림이 다 잠드는 시간을 기다린다.', k:'steady', dc:23,
      ok:`철망에 손끝을 얹은 채 밤을 쟀다. 자정 넘어 떨림이 하나씩 잦아들었다.<br><br>그것들도 자는 시간이 있다. 다 같이는 아니고, 보초 하나만 남기고.<br>보초의 떨림이 먼 구간에 가 있을 때 넘었다. 떨림 없는 철망은 그냥 쇠였다. 쇠는 무섭지 않다.`,
      ng:`기다리는 중에 이쪽이 먼저 졸았다. 철망에 이마가 닿았다.<br><br>쿵, 하는 떨림이 철망을 타고 울타리 반 바퀴를 돌았다.<br>먼 데서 그것들의 대답이 왔다. 이쪽 보초 노릇을 이쪽이 망친 셈이다. 그 밤은 넘기를 포기하고 물러났다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'S2', t:'물 건너기 — 고목의 실',
  x:`물에 잠긴 고사리 밭. 허리 깊이. 백 걸음.<br><br>
    물 밑은 실이 안 보인다. 물은 실의 떨림을 삼킨다. 이쪽 눈이 반쯤 머는 자리다.<br>
    물가에 고목이 하나 서 있다. 밑동이 굵고, 뿌리가 바위를 문 채 죽은 나무.<br><br>
    먼 수면이 한 번 둥글게 운다. 주인이 순찰 중이다.`,
  o:[
    { l:'① 고목에 실을 걸어 다섯을 꿰고 건넌다.', k:'bond', dc:25, cost:{ mana:34 },
      ok:`고목 밑동에 실을 감고 다섯 허리를 꿰었다. 마력을 실어 물에 안 삭게.<br><br>물속에서 발이 미끄러져도 실이 받았다. 셋째가 구덩이를 밟았을 때도 가슴까지만 잠기고 섰다.<br>건너편에서 실을 걷는데 실 가운데가 미지근했다. 물밑에서 무엇이 실을 따라 헤엄쳐 본 것이다. 끊지는 않았다. 간을 본 것이다. 다음 팀은 모르겠다.`,
      ng:`반쯤 건넜을 때 고목이 울었다. 죽은 뿌리가 물밑에서 삭아 있던 것이다.<br><br>밑동이 기울며 실이 통째로 늘어졌다. 다섯이 한꺼번에 물에 쏠렸다.<br>실을 끊고 서로를 잡아 세웠다. 남은 반을 맨몸으로 건넜다. 수면이 등 뒤에서 두 번 울었다. 세 번째 울기 전에 뭍을 밟았다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 맨 뒤에 서서 실 끝을 제 허리에 감는다.', k:'steady', dc:25,
      doom:{ title:'물밑의 무게', what:'물속으로 끌려 들어갑니다', dc:20, sec:36,
        text:`넷을 앞세우고 실 끝을 제 허리에 감았다. 누가 넘어지면 이쪽이 닻이 되는 자리.<br><br>여든 걸음째, 닻이 먼저 잡혔다. 물밑에서 허리의 실째 무엇이 물었다.<br><br>수면이 입을 벌리듯 꺼진다. 앞의 넷에게는 실이 당겨지는 느낌만 갔을 것이다. 닻은 소리를 못 지른다. 물속이라.`,
        dieText:`넷이 실을 당겼다. 실은 돌아왔다. 끝이 젖은 채, 허리 매듭만 남은 채.<br><br>수면은 금방 고요해졌다. 고사리 이파리가 몇 장 돌았다.<br>건너편에 선 넷은 한참 동안 실 끝을 놓지 못했다. 닻 없이 건넌 물이 아니라, 닻을 두고 건넌 물이었다.` },
      ok:`맨 뒤에서 허리에 실을 감고 건넜다. 발밑을 읽으며, 수면을 세며.<br><br>아흔 걸음째 뒤쪽 수면이 울었다. 가까이. 실을 두 번 당겨 신호하고 마지막 열 걸음을 물살처럼 갔다.<br>뭍에 오르는 발꿈치 뒤에서 물이 턱 닫혔다. 닻은 무사히 회수됐다. 자리가 자리인 만큼, 간이 반으로 줄었지만.`,
      win:{ exp:24, dream:3 } },
    { l:'③ 수면의 울음 간격을 재서 맨몸으로 건넌다.', k:'sense', dc:24,
      ok:`수면이 우는 간격을 쟀다. 둥근 울음과 울음 사이, 이백 숨.<br><br>이백 숨이면 백 걸음은 간다. 울음이 멀어진 직후 다섯이 물을 갈랐다.<br>백아홉 걸음 만에 다 건넜다. 아낀 마력은 품에 남았다. 눈과 숨으로 되는 일에 실을 쓰면 실이 아깝다.`,
      ng:`간격이 갑자기 바뀌었다. 재 둔 이백 숨이 백 숨으로 줄었다.<br><br>주인이 순찰 길을 바꾼 것이다. 물 한가운데서 울음이 다가왔다.<br>셈을 버리고 달렸다. 물보라가 일어 다 젖었다. 뭍에 구르듯 올라 고사리 덤불에 박혔다. 수면이 바로 뒤에서 울었다. 오래, 아쉬운 듯이.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-27, mind:-16 } }
  ] },

{ at:'S2', t:'새끼와 어미 사이',
  x:`길 한가운데 어린 것이 혼자 서 있다. 무리에서 떨어진 새끼다.<br><br>
    이쪽 눈에는 보인다. 새끼에게서 뻗은 실 하나가 숲 안쪽으로 팽팽하게 이어져 있다. 어미 쪽으로.<br>
    실이 팽팽하다는 건 어미가 실을 쥐고 있다는 것이다. 곧 온다는 것이다.<br><br>
    이 실은 끊어도 재앙이고 당겨도 재앙이다. 건드리지 않고 지나는 수뿐이다.`,
  o:[
    { l:'① 실을 건드리지 않게 다섯 걸음을 실의 결에 맞춘다.', k:'bond', dc:25, wake:1,
      ok:`실이 바람에 흔들리는 결을 읽었다. 흔들려 내려올 때 지나고, 올라갈 때 멎고.<br><br>다섯이 그 박자로 실 밑을 지났다. 새끼는 이쪽을 보면서도 울지 않았다. 실이 흔들리지 않으니 겁날 일이 없는 것이다.<br>다 지나고 스무 걸음 뒤에 숲이 갈라지며 어미가 왔다. 실을 따라 곧장, 이쪽은 보지도 않고.<br><br>끊지 않고 비켜 가는 법. 세상에는 묶는 자가 손대면 안 되는 매듭이 있다는 것. 그걸 아는 데 이 눈을 쓰는 날이 올 줄 몰랐다.`,
      ng:`넷째까지 지났는데 막내 배낭 끝이 실을 스쳤다.<br><br>실이 한 번 크게 출렁였다. 새끼가 자지러지게 울었다.<br>숲이 통째로 갈라지는 소리가 왔다. 다 같이 바위 틈으로 뛰었다. 어미는 새끼를 찾고도 한참 동안 주변 바위를 하나하나 들여다봤다. 그 그림자가 틈 앞을 네 번 지났다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-19, spirit:-22 } },
    { l:'② 새끼를 어미 쪽으로 몰아 실부터 걷게 한다.', k:'evade', dc:25,
      ok:`크게 돌아 새끼 뒤쪽에 서고, 발소리를 숲 반대편으로 냈다.<br><br>새끼가 실 방향으로 내뺐다. 팽팽하던 실이 걷히며 길이 비었다.<br>어미와 새끼가 만나는 소리를 등 뒤로 들으며 지났다. 상봉 장면은 안 봤다. 볼 이유도 없고, 봤다간 큰일 날 크기였다.`,
      ng:`몰던 발소리가 너무 가까웠다. 새끼가 어미 쪽이 아니라 옆으로 튀었다.<br><br>실이 길게 끌리며 방향이 엉켰다. 어미가 실을 따라오면 이쪽 길과 겹치게 됐다.<br>길을 버리고 비탈로 올랐다. 비탈에서 막내가 미끄러져 팔꿈치가 깨졌다. 새끼 울음은 밤까지 들렸다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S2', t:'삭은 쇠줄',
  x:`낡은 승강기의 쇠줄을 올려다봤다. 이쪽 눈에는 쇠줄도 실이다.<br><br>
    굵은 실 안에 가는 올이 수백. 그중 삭아 끊긴 올이 반이 넘는다.<br>
    남은 올들이 서로를 겨우 붙들고 있다. 지친 팀처럼. 당기면 버티겠지만, 울컥하면 놓친다.<br><br>
    여섯 사람 무게가 이 올들 위에 실린다.`,
  o:[
    { l:'① 삭은 올에 실을 감아 덧땋는다.', k:'bond', dc:26, cost:{ mana:38 },
      ok:`끊긴 올 자리마다 실을 덧땋았다. 쇠의 결을 따라, 한 올 한 올.<br><br>마력 실은 쇠보다 약하다. 다만 쇠와 쇠 사이를 잇는 데는 충분하다. 끊긴 올이 이어지자 남은 올들의 떨림이 가라앉았다.<br>오르는 내내 쇠줄은 한 번도 안 울었다. 꼭대기에서 실을 걷자 손끝이 텅 비었다. 좋은 피로였다.`,
      ng:`덧땋는 중에 위쪽에서 올 하나가 또 끊겼다. 삭는 속도가 땋는 속도보다 빨랐다.<br><br>다 땋지 못한 채 탔다. 중간에 쇠줄이 한 번 울컥했다. 반 뼘 떨어졌다 섰다.<br>그 반 뼘에 다들 십 년씩 늙었다. 꼭대기에 내려서 보니 땋아 둔 실 매듭이 반은 풀려 있었다. 쇠는 실의 말을 반만 듣는다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-17 } },
    { l:'② 오르는 동안 승강기 바닥 틈에 버팀실을 걸고 선다.', k:'steady', dc:26,
      doom:{ title:'울컥하는 쇠줄', what:'멈춘 승강기와 함께 어둠 아래로 실려 내려갑니다', dc:19, sec:40,
        text:`바닥 틈과 벽 고리에 실을 걸어 다섯을 묶고 올랐다. 쇠줄이 놓쳐도 반 숨은 벌 수 있게.<br><br>반쯤 올랐을 때 쇠줄이 울컥했다. 한 번, 두 번. 세 번째에 놓쳤다.<br><br>승강기가 통째로 미끄러진다. 버팀실이 벽 고리째 뜯겨 나간다. 바닥이 웃자란 고사리 쪽으로, 어두운 정원 바닥으로, 떨어지는 게 아니라 실려 내려간다. 느리게, 쇠줄이 마지막 올로 버티면서.`,
        dieText:`승강기는 바닥 층에 처박혀 멎었다. 위에서 보면 상자 하나가 수풀에 반쯤 묻힌 꼴이었다.<br><br>팀원들이 수동 권양기로 상자를 도로 끌어올리는 데 한나절이 걸렸다.<br>상자는 비어 있었다. 바닥 틈에 버팀실만 성하게 남아 있었다. 정원은 상자 안까지 제 것으로 센다.` },
      ok:`바닥 틈과 벽 고리에 버팀실을 치고 다섯이 그 안에 섰다.<br><br>쇠줄이 중간에 한 번 울컥했다. 승강기가 반 뼘 떨어지다 버팀실에 받혀 섰다.<br>그 반 뼘 사이 아무도 넘어지지 않았다. 넘어지는 무게가 쇠줄을 마저 끊는다. 버팀실은 사람이 아니라 그 반 뼘을 받으려고 친 것이다. 받았다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S2', t:'다섯이 한 짐승처럼',
  x:`숲과 승강장 사이, 가릴 것 없는 풀밭 이백 걸음.<br><br>
    다섯 사람의 발소리는 다섯 끼니의 소리다. 그건 배웠다.<br>
    그렇다면 뒤집으면 된다. 다섯 발을 하나로 묶어 큰 하나의 소리를 내는 것. 네 발 달린 큰 것의 박자로.<br><br>
    이 정원에서 큰 소리는 큰 몸이다. 큰 몸은 아무도 안 센다.`,
  o:[
    { l:'① 다섯 걸음을 실로 묶어 큰 짐승의 발소리를 짠다.', k:'bond', dc:25, cost:{ mana:30 },
      ok:`다섯 발목에 실을 걸고 박자를 짰다. 쿵, 쿵. 앞 둘이 앞발, 뒤 셋이 뒷발.<br><br>풀숲의 그것들이 소리를 쟀다. 재고, 물러났다. 저보다 무거운 것의 길을 비키는 짐승의 예의로.<br>이백 걸음을 큰 짐승 하나가 지나갔다. 승강장에 닿아 실을 걷자 다섯이 서로를 보고 조금 웃었다. 처음으로 이 정원에서 겁먹지 않은 이백 걸음이었다.`,
      ng:`백 걸음까지는 큰 짐승이었다. 백한 걸음째 막내가 발을 접질렸다.<br><br>박자가 깨지며 큰 하나가 작은 다섯으로 쪼개졌다. 풀숲이 그 소리를 들었다.<br>남은 백 걸음은 그냥 달렸다. 묶었던 실이 발목에서 풀리며 채찍처럼 날렸다. 승강장 철골을 잡고서야 뒤를 봤다. 풀이 바로 뒤까지 누워 있었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 묶지 않고 풀 그늘만 이어 달린다.', k:'evade', dc:24,
      ok:`풀밭에도 그늘길이 있다. 키 큰 양치 덤불이 띄엄띄엄 늘어선 줄.<br><br>그늘에서 그늘로, 한 번에 하나씩 보냈다. 마지막에 이쪽이 건넜다.<br>이백 걸음을 다섯 토막으로 끊어 먹었다. 묶는 것만 재주가 아니다. 끊어 가는 것도 재주다.`,
      ng:`세 번째 그늘이 그늘이 아니었다. 덤불 뒤에 그것 하나가 엎드려 있었다.<br><br>먼저 간 둘과 덤불의 그것이 서로 놀랐다. 그것이 벌떡 일며 울었다.<br>다 같이 승강장까지 전력으로 달렸다. 둘은 덤불 반대편으로 크게 돌아서 왔다. 발소리 같은 건 따질 계제가 아니었다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-29, mind:-15 } }
  ] },

{ at:'S2', t:'문이 닫힐 때 — 실 끊는 손',
  x:`승강기에 다 탔다. 문이 닫히기를 기다리는데 손끝이 가렵다.<br><br>
    내려다보니 보인다. 정원의 가는 올들이 다섯 몸에 붙어 있다. 바짓단에, 배낭끈에, 머리카락에.<br>
    정원에 있는 동안 조금씩 짜 붙인 것이다. 눈치도 못 채게. 이대로 오르면 올은 늘어나며 따라온다. 어디까지든.<br><br>
    이쪽 실은 다치지 않게, 저쪽 올만 골라 끊어야 한다. 문이 닫히기 전에.`,
  o:[
    { l:'① 제 실과 남의 올을 가려 하나씩 끊는다.', k:'bond', dc:26, wake:1,
      ok:`눈을 감았다. 눈으로는 못 가린다. 손끝으로 가렸다.<br><br>이쪽 실은 따뜻하고 저쪽 올은 미지근하다. 체온의 반 발짝 차이. 그 차이로 열일곱 올을 끊었다. 문이 닫히는 소리와 마지막 올 끊기는 소리가 겹쳤다.<br>오르는 승강기 창밖으로, 끊긴 올들이 민들레 씨처럼 정원으로 돌아가는 게 보였다.<br><br>어둠 속에서 제 매듭을 아는 손. 묶는 일의 끝은 결국 그것이다. 제 것과 남의 것을 가리는 손끝 하나.`,
      ng:`급한 손이 이쪽 실 하나를 같이 끊었다. 막내에게 걸어 둔 올이었다.<br><br>막내가 흠칫 떨었다. 어디가 허전한지 모르는 얼굴로.<br>남의 올은 다 끊었다. 오르는 동안 막내 옆에 붙어 서 있었다. 실 없이, 어깨로. 올라가서 제일 먼저 그 올부터 다시 걸었다.`,
      win:{ exp:25, dream:4 }, lose:{ mind:-17, spirit:-19 } },
    { l:'② 다 끊고 문 안에서 전부 새로 맺는다.', k:'break', dc:25,
      ok:`가릴 시간이 없었다. 다섯 몸의 실이란 실은 다 끊었다. 제 것까지.<br><br>문이 닫혔다. 승강기 안, 실 하나 없이 선 다섯. 낯선 고요였다.<br>오르는 동안 한 올씩 새로 걸었다. 새 실은 가늘었지만 깨끗했다. 정원 것이 한 올도 안 섞인 그물. 가끔은 다 허물고 새로 짓는 게 빠르다.`,
      ng:`다 끊은 순간 승강기가 덜컹했다. 실 없는 다섯이 제각기 흔들렸다.<br><br>흔들린 막내가 벽을 짚으려다 비상 손잡이를 쳤다. 승강기가 반 층을 서서 떨었다.<br>다시 오르기까지의 몇 숨이, 실 없는 몇 숨이, 유난히 헐벗었다. 그물 없이 공중에 뜬 다섯은 그냥 상자 속 다섯이었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-22 } }
  ] }

]);

// ------------------------------------------
// 견습 기사 · 무력
// ------------------------------------------
kJob('knight', 'S', [

{ at:'S', t:'맨 뒤의 걸음',
  x:`이 어둠은 대열의 꼬리부터 먹는다. 사흘 동안 두 팀이 그렇게 꼬리를 잃었다고 했다.<br><br>
    꼬리가 무른 대열은 전부가 무르다. 맨 뒤에 설 사람은 정해져 있다.<br>
    방패 든 사람. 그러라고 방패를 드는 것이다.<br><br>
    문제는 맨 뒤에서 앞을 보고 걷느냐, 뒤를 보고 걷느냐다.`,
  o:[
    { l:'① 뒷걸음으로 맨 뒤를 선다 — 방패와 눈은 어둠 쪽으로.', k:'bond', dc:24, cost:{ might:28 },
      ok:`방패를 가슴에 붙이고 뒷걸음으로 걸었다. 앞은 팀원 하나가 어깨를 잡아 이끌었다.<br><br>어둠이 두 번 간을 봤다. 두 번 다 방패 테에 발톱이 긁히고 물러났다. 세 번째는 없었다.<br>꼬리에 이빨이 있는 대열은 꼬리부터 먹히지 않는다. 다리가 후들거리는 건 그다음 문제다.`,
      ng:`뒷걸음 반나절에 종아리가 먼저 무너졌다. 돌부리에 뒤꿈치가 걸려 넘어졌다.<br><br>넘어진 순간을 어둠이 쳤다. 방패가 반쯤 벗겨지고 팔뚝이 길게 긁혔다.<br>팀원들이 소리 지르며 달려들어 몰아냈다. 맨 뒤는 지켰다. 팔뚝 값을 치르고.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-29, mind:-14 } },
    { l:'② 대열을 줄여 꼬리 자체를 없앤다.', k:'fix', dc:23,
      ok:`다섯을 두 걸음 간격으로 바싹 붙였다. 앞뒤 없이 한 덩어리로.<br><br>꼬리가 없는 짐승은 꼬리부터 먹을 수 없다.<br>어둠이 대열 주위를 반 바퀴 돌고 떠났다. 물 자리를 못 찾은 것이다. 방패는 덩어리 바깥쪽 어깨에만 걸쳐 두면 됐다.`,
      ng:`바싹 붙인 대열은 느리다. 좁은 길에서 병목이 됐다.<br><br>늘어진 틈을 어둠이 쑤셨다. 가운데 팀원 배낭이 찢겨 바닥에 쏟아졌다.<br>먹을 것 반을 잃었다. 몸은 성했다. 어느 쪽이 싼 값인지는 저녁때쯤 배가 가르쳐 줬다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-16, spirit:-17 } }
  ] },

{ at:'S', t:'두고 가라는 말',
  x:`발목이 꺾인 팀원이 벽에 기대 말한다. 두고 가라고. 짐이 되기 싫다고.<br><br>
    어둠 속에서 제일 자주 듣는 말이고, 제일 들어서는 안 되는 말이다.<br>
    두고 간 사람은 돌아오지 못하고, 두고 온 사람들은 그 말을 평생 듣는다. 밤마다.<br><br>
    방패를 내려다봤다. 방패는 드는 물건만은 아니다.`,
  o:[
    { l:'① 방패를 내려 들것을 만든다.', k:'bond', dc:24, wake:1,
      ok:`방패를 눕히고 끈 두 개를 걸었다. 들것이 됐다. 팀원을 그 위에 실었다.<br><br>둘이 끌고 둘이 밀었다. 방패 바닥이 돌에 긁히며 요란했지만, 요란한 건 산 사람 소리다.<br>두고 가라던 입이 다물렸다. 다문 입이 우는 걸 못 본 척했다.<br><br>막는 것만 지키는 게 아니다. 싣고, 덮고, 끄는 것도 지키는 일이다. 방패의 쓰임이 하나 늘 때마다 기사도 한 뼘 는다.`,
      ng:`방패 들것이 돌밭에서 자꾸 걸렸다. 긁히는 소리가 어둠을 불렀다.<br><br>뒤에서 기척이 따라붙었다. 소리를 죽이려 속도를 늦추니 밤이 길어졌다.<br>교대로 밤을 새우며 갔다. 다 왔을 때 방패 바닥이 반질반질했다. 갈려 나간 만큼이 그 사람 목숨값이면 싼 거다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-19 } },
    { l:'② 업는다 — 방패는 그 사람 등 뒤에 묶는다.', k:'steady', dc:25,
      ok:`팀원을 업고 방패를 그 등 뒤에 묶었다. 업힌 사람이 등딱지를 얻었다.<br><br>뒤에서 오는 것은 이제 사람 등이 아니라 쇠를 본다.<br>한 번 긁는 소리가 났고, 쇠 맛을 본 어둠이 물러났다. 업힌 팀원이 등 뒤 충격을 대신 받아 줘서 고맙다고 농담했다. 농담이 나오면 산다.`,
      ng:`업은 무게에 방패 무게가 얹히니 걸음이 반으로 줄었다.<br><br>일행과 간격이 벌어졌다. 벌어진 간격은 어둠의 자리다.<br>두 번을 쫓기듯 따라붙었다. 어깨끈이 살을 파고들어 밤에 보니 피멍이 끈 모양 그대로였다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-27, mind:-15 } }
  ] },

{ at:'S', t:'문지방 — 닫히려는 틈',
  x:`무너진 벽 틈이 유일한 길이다. 사람 하나 겨우 지나는 폭.<br><br>
    틈 위쪽 돌무더기가 산 것처럼 조금씩 내려앉는다. 다섯이 다 지나기 전에 닫힐 속도다.<br>
    그리고 틈 너머 어둠에서 젖은 숨소리가 난다. 틈이 닫히기를 기다리는 숨 같기도 하다.<br><br>
    누가 틈을 받치고, 누가 마지막에 지나는가. 답은 묻기 전에 나와 있다.`,
  o:[
    { l:'① 어깨와 방패로 틈을 받치고 모두 보낸다.', k:'steady', dc:25,
      doom:{ title:'닫히는 틈', what:'틈 너머 어둠으로 끌려갑니다', dc:19, sec:45,
        text:`방패를 틈에 세로로 괴고 어깨로 받쳤다. 하나, 둘, 셋, 넷이 지나갔다.<br><br>다섯째로 이쪽이 몸을 빼는 순간, 너머의 젖은 숨이 닿을 만큼 가까워졌다.<br><br>손목에 축축한 것이 감겼다. 돌무더기가 내려앉으며 틈이 닫히고, 몸은 닫히는 틈 너머로 당겨진다. 기다린 것은 틈이 아니라 받치는 사람이었다.`,
        dieText:`틈은 닫혔다. 돌무더기 사이로 방패 테두리만 조금 보였다.<br><br>넷이 밤새 돌을 걷었다. 아침에 틈이 다시 열렸을 때 너머에는 방패만 남아 있었다. 안쪽 면에 긁힌 자국 하나 없이.<br>싸울 틈도 없이 데려갔다는 뜻이다. 넷은 그 방패를 번갈아 들고 나갔다.` },
      ok:`방패를 틈에 괴고 어깨로 받쳤다. 돌무더기의 무게가 등뼈로 내려왔다.<br><br>넷이 지나는 동안 너머의 젖은 숨을 마주 보고 있었다. 숨이 다가올 때마다 방패 테로 바닥을 쳤다. 쇳소리에 숨이 주춤했다.<br>마지막에 몸을 빼자 틈이 반 숨 만에 닫혔다. 등 뒤에서 돌 닫히는 소리와 젖은 숨이 돌에 막히는 소리가 같이 났다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 받치지 않고 간격만 끊어 빠르게 통과시킨다.', k:'bond', dc:24,
      ok:`틈이 내려앉는 박자를 쟀다. 내려앉고, 버티고, 또 내려앉고.<br><br>버티는 박자마다 하나씩 밀어 넣었다. 등을 쳐서 신호하고, 당겨서 세우고.<br>다섯이 다 지나고 세 숨 뒤에 틈이 닫혔다. 받치는 것만 힘이 아니다. 박자를 읽어 주는 것도 힘이다.`,
      ng:`셋째까지는 박자가 맞았다. 넷째에서 돌이 예고 없이 내려앉았다.<br><br>넷째 팀원이 틈에 어깨가 끼었다. 앞뒤에서 당기고 밀어 빼냈다.<br>어깨뼈는 성했다. 외투와 살갗이 한 겹씩 틈에 남았다. 다섯째인 이쪽은 구르다시피 지났다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'S', t:'등을 맡긴다는 것',
  x:`합류한 다른 팀에 어린 창잡이가 있다. 눈이 너무 자주 돈다. 앞, 옆, 뒤, 앞, 옆, 뒤.<br><br>
    저러다 쓰러진다. 사방을 혼자 보는 사람은 한 방향도 제대로 못 본다.<br>
    등을 맡기는 법을 배운 적이 없는 것이다. 어디서도 안 가르쳐 주니까.<br><br>
    기사 수련의 첫날에 배우는 것을, 여기서 가르치게 생겼다.`,
  o:[
    { l:'① 등을 맞대고 호흡부터 가르친다.', k:'bond', dc:23,
      ok:`녀석과 등을 맞대고 섰다. 네 눈은 앞 반원만, 뒤 반원은 내 것이라고 일렀다.<br><br>처음엔 등이 뻣뻣했다. 반 시진 뒤에 등이 기대 왔다. 호흡이 맞기 시작한 것이다.<br>그날 밤 습격 때 녀석은 제 반원만 봤다. 그래서 제 반원으로 들어온 것을 잡았다. 등 뒤는 돌아보지도 않았다. 잘 컸다.`,
      ng:`등을 맞대자던 말에 녀석이 더 굳었다. 낯선 등은 벽보다 무섭다.<br><br>어중간하게 반 발짝 떨어진 채로 밤을 맞았다. 그 반 발짝 사이로 어둠이 지나갔다.<br>스친 자리에 긴 긁힘이 남았다. 녀석 것이 아니라 이쪽 옆구리에. 어중간한 간격은 둘 다를 못 지킨다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 녀석의 자리를 벽 쪽으로 바꿔 준다.', k:'fix', dc:24,
      ok:`대열에서 녀석 자리를 벽 쪽 둘째로 옮겼다. 등 뒤가 돌벽이면 볼 방향이 반으로 준다.<br><br>눈 돌아가는 속도가 반으로 줄었다. 반으로 주니 제대로 보기 시작했다.<br>녀석이 그날 갈림길 바닥의 긁힌 자국을 제일 먼저 찾아냈다. 보는 눈은 원래 있었다. 방향이 너무 많았을 뿐.`,
      ng:`벽 쪽 자리를 두고 그쪽 팀 고참이 불퉁했다. 제 자리였다고.<br><br>남의 대열을 손대는 건 남의 살림을 손대는 일이다. 말이 길어졌고, 말 긴 자리는 어둠이 좋아한다.<br>그날 밤 그쪽 팀은 대열을 원래대로 돌렸다. 녀석 눈은 다시 사방을 돈다. 가르침에도 월권이 있다는 걸 배웠다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'S', t:'방패에 박힌 이빨',
  x:`간밤 습격을 막아 낸 방패를 아침에 살폈다. 테두리에 이빨 둘이 박혀 있다.<br><br>
    길고, 안으로 굽었고, 뿌리까지 희다. 부러뜨리고도 물러서지 않던 아귀힘.<br>
    방패는 맞은 걸 기억한다. 움푹 팬 각도, 긁힌 줄의 방향. 읽을 줄만 알면 적의 장부다.<br><br>
    버릇을 읽힌 적은 반쯤 진 적이다.`,
  o:[
    { l:'① 이빨을 뽑아 패인 각을 하나하나 잰다.', k:'gaze', dc:24, wake:1,
      ok:`이빨을 뽑고 팬 자리에 손가락을 넣어 쟀다. 전부 왼쪽 위에서 오른쪽 아래. 비스듬히 찍어 당기는 버릇.<br><br>그러면 다음 수는 정해져 있다. 방패를 오른쪽으로 반 뼘 기울여 드는 것. 찍는 순간 날이 미끄러지게.<br>이틀 뒤 다시 왔을 때 그대로 됐다. 미끄러진 놈이 제 박자를 잃고 물러났다.<br><br>방패가 장부라는 걸 배웠다. 맞은 자리를 읽으면 다음 매가 보인다. 견습 딱지가 한 겹 벗겨지는 소리가 났다.`,
      ng:`각을 재는 데 정신이 팔려 이빨 뿌리의 진을 맨손으로 만졌다.<br><br>손끝이 저리더니 반나절 감각이 없었다. 방패 잡는 손이 하필 그 손이다.<br>저린 손으로 하루를 걸었다. 장부는 읽었는데 수업료가 셌다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 이빨을 뽑아 창끝에 덧댄다.', k:'fix', dc:23,
      ok:`이빨 둘을 창대 끝에 단단히 묶었다. 저쪽 이빨로 저쪽을 겨누는 셈.<br><br>다음 습격 때 그 창끝이 살을 파고들자 놈이 평소의 배로 놀라 물러났다. 제 이빨 맛을 아는 것이다.<br>버린 패도 주우면 패가 된다.`,
      ng:`묶은 이빨이 첫 찌름에 창대에서 빠졌다. 묶음이 허술했다.<br><br>빠진 이빨이 바닥에 구르자 어둠 속 놈이 그걸 도로 집어 갔다. 입으로.<br>제 이빨을 되찾아 가는 꼴을 보고 나니 등골이 서늘했다. 기억력 좋은 적이 제일 나쁜 적이다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-17, spirit:-18 } }
  ] },

{ at:'S', t:'쓰러진 사람을 지는 법',
  x:`업어야 할 사람이 생겼다. 열에 들떠 제 발로는 못 걷는다.<br><br>
    업으면 등이 찬다. 등이 차면 방패를 못 진다. 방패를 못 지면 뒤가 빈다.<br>
    뒤가 비는 걸 아는 어둠이 아까부터 따라온다.<br><br>
    지는 법을 바꿔야 한다. 사람과 방패를 다.`,
  o:[
    { l:'① 사람을 앞으로 안고 방패로 둘을 덮는다.', k:'bond', dc:24, cost:{ might:27 },
      ok:`팀원을 가슴 쪽으로 돌려 안고 방패를 등에 걸었다. 둘이 한 몸, 등딱지 하나.<br><br>팔이 두 배로 무거웠지만 뒤는 쇠였다. 따라오던 어둠이 두 번 간 보고 두 번 쇠에 긁혔다.<br>세 번째가 없는 밤이 처음으로 고마웠다. 안긴 팀원의 열이 가슴으로 느껴졌다. 산 사람 열이다. 무거울 자격이 있는 무게다.`,
      ng:`앞으로 안은 무게에 발밑이 안 보였다. 내리막에서 헛디뎠다.<br><br>안은 사람을 놓치지 않으려고 무릎으로 받았다. 무릎이 돌에 갈렸다.<br>팀원들이 달려와 나눠 안았다. 혼자 다 지려던 게 잘못이라고, 다친 무릎이 말해 줬다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 둘이 번갈아 지게 하고 이쪽은 앞을 연다.', k:'fix', dc:23,
      ok:`지는 일은 둘에게 교대로 맡기고 방패 든 이쪽은 맨 앞에 섰다.<br><br>앞을 여는 방패는 뒤를 막는 방패만큼 일이 많았다. 늘어진 덩굴, 헐거운 바닥, 낮은 턱.<br>업는 쪽이 아니라 길을 고르는 쪽이 대열 속도를 정한다는 걸 알았다. 그 밤은 빠르고 조용했다.`,
      ng:`교대 순서가 꼬였다. 지친 둘이 연달아 업게 됐다.<br><br>뒤처진 둘과 앞선 셋 사이가 벌어졌다. 벌어진 자리를 어둠이 스쳐 갔다.<br>업힌 사람 발끝의 신발 한 짝이 사라졌다. 벗겨 간 것이다. 경고인지 수집인지 모를 일이다. 간격부터 다시 붙였다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'S', t:'비명 쪽으로',
  x:`멀지 않은 어둠에서 비명이 났다. 사람 비명.<br><br>
    몸이 먼저 그쪽으로 반 발 나갔다. 비명 쪽으로 달리는 건 방패 든 사람의 본능이다.<br>
    다만 이 어둠에서는 비명도 미끼로 쓰인다. 그걸 알 만큼은 배웠다.<br><br>
    본능과 배움이 가슴 속에서 싸운다. 비명은 이어지고 있다.`,
  o:[
    { l:'① 달려간다 — 그러라고 방패를 든 것이다.', k:'bond', dc:25,
      doom:{ title:'비명의 임자', what:'비명의 임자에게 끌려갑니다', dc:19, sec:42,
        text:`비명 속으로 달려 들어갔다. 쓰러진 사람 꼴이 보였다. 그 위에 엎드린 어둠도.<br><br>방패를 박아 넣는 순간 쓰러진 사람 꼴이 풀어졌다. 사람이 아니었다. 비명을 내던 구멍들이 일제히 이쪽을 향해 열렸다.<br><br>방패째 감겼다. 끌려가는 바닥에 방패 테가 길게 금을 그었다. 본능은 좋은 것이다. 혼자 올 때만 빼면.`,
        dieText:`팀원들이 금을 따라갔다. 금은 벽 아래 틈에서 끊겼다.<br><br>틈 앞에 방패만 남아 있었다. 안쪽 면이 바깥을 향한 채. 마지막까지 돌려 막은 것이다.<br>그 뒤로도 그 어둠에서는 비명이 난다. 요즘은 가끔, 쇠 두드리는 소리도 섞여 난다.` },
      ok:`달려 들어가되 혼자 가지 않았다. 방패가 앞, 등 뒤에 둘, 불 든 하나.<br><br>비명의 임자는 진짜 사람이었다. 다른 팀 낙오자. 다리를 문 것이 질질 끌고 가는 중이었다.<br>방패 모서리로 그것의 관절을 내리찍었다. 놓고 달아났다. 끌려가던 사람이 방패를 붙잡고 울었다. 본능이 이긴 밤도 있어야 한다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 팀을 세워 두고 소리의 결부터 가른다.', k:'sense', dc:24,
      ok:`비명을 끝까지 들었다. 사람 비명은 갈수록 숨이 짧아진다. 이건 같은 길이로 돈다.<br><br>녹음기처럼 정확한 비명. 미끼다.<br>팀을 물려 다른 길로 돌았다. 비명은 밤새 같은 자리에서 같은 길이로 돌았다. 돌다가, 새벽엔 이쪽 팀원 목소리를 연습하기 시작했다. 떠나길 잘했다.`,
      ng:`결을 가르는 사이 비명이 뚝 그쳤다.<br><br>진짜였나. 미끼였나. 영영 모르게 됐다.<br>그 자리를 떠난 뒤로도 그친 비명이 귓속에서 오래 돌았다. 모르는 채 남는 것이 제일 무겁다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-19, spirit:-22 } },
    { l:'③ 가지 않는다 — 제 팀 곁을 지킨다.', k:'steady', dc:23,
      ok:`방패를 고쳐 쥐고 제자리에 섰다. 지킬 사람은 등 뒤에 있다.<br><br>비명이 그치고 한참 뒤, 어둠이 이쪽 야영지 가장자리를 돌았다. 미끼에 안 온 먹이를 보러 온 것이다.<br>방패 테를 돌에 한 번 갈았다. 쇳소리에 어둠이 떠났다. 안 가는 것도 결정이고, 결정한 자리는 지켰다.`,
      ng:`제자리는 지켰다. 다만 밤새 비명이 머리에서 안 나갔다.<br><br>새벽에 그쪽 방향에서 다른 팀이 왔다. 하나가 모자란 채로.<br>아무도 이쪽을 탓하지 않았다. 그게 더 괴로웠다. 방패가 그날따라 무거웠다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-18, spirit:-23 } }
  ] },

{ at:'S', t:'무릎 꿇는 법',
  x:`수련 때 제일 많이 혼난 게 무릎 꿇는 법이다. 그때는 몰랐다. 꿇는 데 법이 왜 필요한지.<br><br>
    바닥이 울린다. 온다. 정면으로, 크고 곧게. 피할 틈은 양쪽 다 없다.<br>
    돌진은 선 사람을 친다. 꿇은 사람 위로는 넘어간다. 방패 각이 맞으면.<br><br>
    이제 안다. 꿇는 데도 법이 필요하다.`,
  o:[
    { l:'① 무릎 꿇고 방패 아래턱을 바닥에 박는다.', k:'steady', dc:25, cost:{ might:32 },
      ok:`한 무릎을 꿇고 방패 아래턱을 바닥 틈에 박았다. 윗머리는 비스듬히 뒤로.<br><br>돌진이 방패 면을 타고 머리 위로 흘렀다. 쇠가 울고 어깨가 꺼질 듯했지만 각은 살았다.<br>넘어간 것이 균형을 잃고 뒹굴었다. 일어나 다시 오지는 않았다. 바닥을 치고 구른 사냥꾼은 체면이 상해서 못 온다.`,
      ng:`방패 아래턱을 박을 틈이 그 자리에 없었다. 맨바닥에 긁히며 각이 밀렸다.<br><br>충격 반이 어깨로 왔다. 방패째 뒤로 넉 자를 밀려났다.<br>넘어가긴 넘어갔다. 어깨는 사흘을 욱신댔다. 각은 바닥이 반을 만든다. 바닥부터 보는 버릇이 생겼다.`,
      win:{ exp:17, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 꿇지 않고 반 발 비껴 흘린다.', k:'evade', dc:25,
      ok:`정면을 주다가 마지막 반 숨에 반 발 비꼈다. 방패 면을 비스듬히 대 주면서.<br><br>돌진이 방패를 스치고 제 속도에 쏠려 지나갔다. 이쪽은 제자리에서 반 바퀴만 돌았다.<br>지나간 것이 멈추는 데 열 걸음이 걸렸다. 그 열 걸음 사이에 팀은 바위 뒤로 다 들어갔다.`,
      ng:`반 발이 반의 반 발 모자랐다. 어깨가 스쳤다.<br><br>스친 것뿐인데 몸이 공중에 떴다. 바위에 등으로 떨어졌다.<br>숨이 한참 안 돌아왔다. 돌진의 무게란 스치는 것만으로 이렇다. 다음부터는 꿇기로 했다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-33, spirit:-15 } }
  ] },

{ at:'S', t:'셋까지 세는 방패',
  x:`이 방패로 저것의 매를 몇 번 받을 수 있나. 어젯밤 재 봤다. 셋.<br><br>
    넷째에는 팔이 내려간다. 그건 방패의 한계가 아니라 이쪽 팔의 한계다.<br>
    그렇다면 셋이 이쪽 밑천이다. 밑천은 숨기는 게 아니라 쓰는 것이다.<br><br>
    매 한 번에 팀이 한 구간씩 움직이면, 셋이면 꺾인 길 하나를 다 돈다.`,
  o:[
    { l:'① 매 수마다 팀이 한 구간씩 — 방패를 시계로 쓴다.', k:'bond', dc:24, wake:1,
      ok:`팀에게 일렀다. 첫 매에 기둥까지, 둘째에 턱 아래, 셋째에 모퉁이 너머.<br><br>첫 매가 왔다. 쇠가 울리는 동안 넷이 기둥까지 달렸다. 둘째, 턱 아래. 셋째, 모퉁이.<br>이쪽은 셋을 다 받고 모퉁이로 굴러 들어갔다. 팔이 덜덜 떨렸지만 밑천은 셋에서 끝났다.<br><br>방패가 남의 시간이 될 수 있다는 것. 버티는 횟수가 아니라 버는 구간으로 세는 법. 그 셈을 몸이 외웠다.`,
      ng:`둘째 매가 예상보다 빨랐다. 구간 신호가 반 박자 밀렸다.<br><br>턱 아래로 달리던 팀원이 어중간한 자리에서 멈췄다 다시 뛰었다.<br>셋째 매를 받으며 그 팀원이 모퉁이를 넘는 걸 봤다. 넘었다. 다만 이쪽 팔꿈치가 매 사이에 한 번 쓸렸다. 박자가 생명이고, 박자는 연습이 만든다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 넷째 매까지 받아 본다 — 밑천을 늘린다.', k:'steady', dc:26,
      ok:`넷째 매에 팔이 내려가는 건 팔꿈치가 펴져서다. 그럼 처음부터 펴지 않으면 된다.<br><br>팔꿈치를 몸통에 묶듯 붙이고 넷째를 받았다. 어깨로, 등으로, 허리로 흘리며.<br>받았다. 다섯째는 사양이지만 밑천이 하나 늘었다. 늘어난 밑천만큼 팀의 길이 길어진다.`,
      ng:`넷째 매에 팔꿈치가 기어이 펴졌다. 방패 윗머리가 이마를 쳤다.<br><br>제 방패에 맞아 보는 건 처음이다. 눈앞에 불이 튀었다.<br>팀원들이 끌어내 줬다. 밑천은 셋. 그건 겸손이 아니라 측량이었다. 측량을 이기려 들면 이마가 깨진다.`,
      win:{ exp:16, dream:2, hp:5 }, lose:{ hp:-36, mind:-16 } }
  ] },

{ at:'S', t:'검을 놓는 손',
  x:`좁은 바위턱을 건너는데 앞서가던 팀원이 미끄러졌다.<br><br>
    한 손은 턱을 잡았다. 다른 손이 허공을 젓는다. 이쪽 오른손에는 검이 들려 있다. 아래 어둠에서는 아까부터 무엇이 기다린다.<br>
    검을 쥔 채로는 못 잡는다. 놓자니 빈손으로 어둠 위에 서게 된다.<br><br>
    생각할 시간은 없다. 생각은 원래 손보다 느리다.`,
  o:[
    { l:'① 검을 놓고 손을 뻗는다.', k:'bond', dc:24, wake:1,
      ok:`검이 어둠으로 떨어지는 소리보다 손목을 잡는 게 빨랐다. 끌어올렸다.<br><br>아래에서 쇠 떨어지는 소리, 그리고 그걸 무엇이 밟는 소리가 났다. 검은 버린 셈 쳤다.<br>이튿날 내려가는 길에 검이 바위에 꽂혀 있었다. 날이 반쯤 상한 채로. 가져가지 않고 꽂아 둔 이유는 생각하지 않기로 했다.<br><br>검 쥔 손의 진짜 쓰임을 배웠다. 검은 다시 줍는다. 사람은 못 줍는다. 그 순서가 손에 새겨졌다.`,
      ng:`검을 놓는 반 숨이 아까웠다. 그 반 숨에 팀원 손이 턱에서 미끄러졌다.<br><br>한 단 아래 턱에 걸렸다. 떨어진 게 아니라 걸린 것이다. 운이다.<br>끌어올리고 보니 그 팀원 손바닥이 다 까져 있었다. 이쪽 검은 멀쩡했다. 멀쩡한 검이 그렇게 부끄러운 건 처음이었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, spirit:-20 } },
    { l:'② 검집째 뽑아 내밀어 잡게 한다.', k:'fix', dc:24,
      ok:`허리의 검집째 뽑아 내밀었다. 손보다 두 뼘 길다.<br><br>팀원이 검집을 잡았고, 지렛대 삼아 끌어올렸다.<br>검도 사람도 성했다. 손이 안 닿으면 손을 늘리면 된다. 허리에 차고 다니는 게 검만은 아니었던 것이다.`,
      ng:`내민 검집 끝이 땀 쥔 손에서 미끄러졌다. 검집이 어둠으로 떨어졌다.<br><br>팀원은 다른 팀원이 배를 깔고 엎드려 간신히 잡았다.<br>검집 없는 검을 사흘 들고 다녔다. 맨날이 베일 뻔한 사흘이었다. 도구는 늘 두 번째 수다. 첫 수는 역시 손이다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S', t:'야경 — 남의 잠을 지키는 일',
  x:`넷이 잠들고 이쪽이 선다. 야경의 밤이다.<br><br>
    지키는 일의 절반은 밤에 있다. 낮의 방패는 몸을 막고, 밤의 방패는 잠을 막는다. 잠이 깨지면 다음 날 대열이 깨진다.<br>
    모닥불은 작게. 눈은 불을 등지고. 수련 때 배운 대로.<br><br>
    어둠 속에서 무엇이 야영지의 둘레를 재고 있다. 소리 없이, 그러나 분명히.`,
  o:[
    { l:'① 불을 등지고 어둠 쪽에 앉는다 — 몸으로 불빛을 가리고.', k:'bond', dc:23,
      ok:`불과 어둠 사이에 앉았다. 이쪽 그림자가 불빛을 반 넘게 가렸다.<br><br>둘레를 재던 것이 빛의 끊긴 자리마다 멈췄다. 그림자 너머를 못 읽는 것이다.<br>밤새 세 번 멈추고 세 번 돌아갔다. 잠든 넷은 아무것도 몰랐다. 모르게 하는 게 이 일이다.`,
      ng:`새벽녘에 눈이 반 숨 감겼다. 뜨니 모닥불 건너편에 긁힌 자국이 나 있었다.<br><br>잠든 막내 발치 한 뼘 앞까지.<br>아무도 안 다쳤다. 다만 그 한 뼘을 밤새 생각했다. 야경의 적은 어둠이 아니라 눈꺼풀이다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-17, spirit:-19 } },
    { l:'② 보초 선을 넓게 잡고 밤새 돈다.', k:'steady', dc:24,
      ok:`야영지 열 걸음 밖으로 둥글게 돌았다. 같은 빠르기로, 밤새.<br><br>둘레를 재던 것과 두 번 간격이 겹쳤다. 두 번 다 이쪽 발소리에 저쪽이 먼저 비켰다.<br>도는 보초는 서 있는 보초보다 큰 짐승으로 들린다. 아침에 발은 부었지만 잠든 얼굴 넷이 성했다.`,
      ng:`세 바퀴째에 어둠 속 웅덩이를 밟았다. 물소리가 크게 났다.<br><br>잠든 넷이 다 깼다. 둘레를 재던 것은 그 소리에 오히려 다가왔다.<br>모두 선 채로 새벽을 맞았다. 다음 날 대열은 하품으로 출발했다. 야경이 밤을 잡아먹은 꼴이다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, mind:-15 } },
    { l:'③ 앉은 채 눈을 감고 귀로만 선다.', k:'sense', dc:25,
      ok:`눈을 감으면 귀가 두 배로 열린다. 둘레 재는 걸음, 멈추는 숨, 돌아서는 무게.<br><br>그것이 야영지 바람막이 틈에 코를 들이민 순간, 감은 눈인 채로 방패 테를 쳤다.<br>쇳소리 한 번에 물러났다. 보인다고 다 보는 게 아니고 감았다고 못 보는 게 아니다.`,
      ng:`귀로만 서는 밤은 길다. 바람 소리와 발소리가 섞이기 시작했다.<br><br>헛것 소리에 두 번 방패를 쳤다. 두 번 다 바람이었다.<br>세 번째 진짜 소리에는 반 박자 늦었다. 말린 고기 꾸러미 하나가 사라졌다. 귀도 피로를 탄다는 걸 배웠다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-18, spirit:-17 } }
  ] },

{ at:'S1', t:'에어록 — 닫히는 문',
  x:`전력이 깜빡이자 에어록 문이 제멋대로 닫히기 시작했다. 아직 둘이 못 넘었다.<br><br>
    문은 쇠고, 쇠는 사정을 안 듣는다.<br>
    문틈 너머 안쪽 어둠에서는 아까부터 배관 긁는 소리가 나고 있었다. 전력이 나간 걸 저쪽도 아는 것이다.<br><br>
    방패가 문보다 단단한지, 지금 알게 된다.`,
  o:[
    { l:'① 문틈에 방패를 세로로 박는다.', k:'steady', dc:26, cost:{ might:38 },
      ok:`닫히는 틈에 방패를 세로로 박고 두 팔로 받쳤다. 쇠와 쇠가 맞물려 비명을 질렀다.<br><br>방패 테가 휘는 게 손바닥으로 느껴졌다. 둘이 그 틈으로 굴러 들어왔다.<br>방패를 빼자 문이 쾅 닫혔다. 테가 활처럼 휜 방패를 들고 한참 서 있었다. 휜 쇠는 편다. 못 넘은 사람은 못 편다.`,
      ng:`방패가 틈에 박히다 각이 틀어졌다. 문이 방패를 씹으며 계속 밀었다.<br><br>손잡이를 놓치면 방패째 씹힌다. 이를 악물고 버텼다. 둘이 넘어 들어오는 데까지는.<br>빼낸 방패는 가운데가 접혀 있었다. 팔꿈치도 반쯤 접힌 것 같았다. 둘 다 펴는 데 시간이 걸릴 것이다.`,
      win:{ exp:17, dream:3 }, lose:{ hp:-31, mind:-15 } },
    { l:'② 문짝을 몸으로 민다.', k:'bond', dc:25,
      doom:{ title:'문 안쪽의 셈', what:'닫히는 문 안쪽 어둠으로 끌려갑니다', dc:20, sec:40,
        text:`문짝에 등을 대고 두 발로 바닥을 밀었다. 문이 멈췄다. 둘이 넘어 들어왔다.<br><br>몸을 빼려는 순간, 문 안쪽 어둠에서 배관 긁던 것이 팔을 감았다.<br><br>전력이 나간 건 우연이 아니었던 모양이다. 문이 마저 닫히는 쪽으로, 어둠 안쪽으로, 등이 미끄러진다. 문을 민 힘까지 저쪽 셈에 들어 있었다.`,
        dieText:`문은 완전히 닫혔다. 안쪽에서 잠겼다. 쇠문에 잠금장치가 돌아가는 소리가 분명히 났다.<br><br>잠글 줄 아는 것이다. 그 사실이 제일 오래 남았다.<br>팀은 다른 길로 돌았다. 그 문 앞을 지날 일이 생기면, 다들 걸음이 빨라진다.` },
      ok:`문짝에 등을 대고 밀었다. 쇠가 등뼈를 타고 울었다.<br><br>둘이 넘어 들어오는 동안 안쪽 어둠의 긁는 소리가 빨라졌다. 급해진 것이다. 급해진 쪽이 지는 것이다.<br>마지막에 몸을 굴려 빼자 문이 닫혔다. 닫힌 문 너머에서 쇠를 한 번 세게 치는 소리가 났다. 분풀이다. 쇠문은 분풀이를 잘 받아 준다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S1', t:'녹는 방패',
  x:`검은 피를 방패로 받았다. 받은 자리가 하얗게 끓는다.<br><br>
    쇠가 연기를 물고 녹는다. 수련 때부터 들던 방패다. 손에 익어 팔 같던 물건.<br>
    버려야 한다. 안다. 아는데 손가락이 안 펴진다.<br><br>
    연기가 손잡이 쪽으로 번져 온다.`,
  o:[
    { l:'① 버린다 — 늦기 전에.', k:'bond', dc:24, wake:1,
      ok:`손가락을 폈다. 방패가 바닥에서 제 몸을 마저 태웠다.<br><br>타는 걸 끝까지 봤다. 가운데가 뚫리고, 테가 녹아 주저앉고.<br>다음 방에서 철제 사물함 문짝을 뜯어 손잡이를 묶었다. 못생겼지만 넓었다.<br><br>기사는 방패가 아니라는 걸, 방패를 버리면서 배웠다. 사이에 서는 사람이 기사다. 손에 든 게 문짝이어도.`,
      ng:`반 숨 늦게 폈다. 녹은 쇳물 한 방울이 장갑 등을 뚫었다.<br><br>손등이 지져졌다. 왼손이다. 방패 잡는 손.<br>사물함 문짝을 오른손에 익히는 데 이틀이 걸렸다. 손에 익은 것과 헤어지는 값은 늘 생살로 치른다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 녹는 자리만 도려내고 마저 쓴다.', k:'fix', dc:25,
      ok:`끓는 자리를 단검으로 도려 파냈다. 방패 가운데 구멍이 뚫렸다.<br><br>구멍 난 방패는 가볍고, 구멍으로 앞이 보였다. 들창 달린 방패가 된 셈이다.<br>남은 테두리는 아직 단단했다. 성한 데까지 버리는 건 버리는 게 아니라 낭비다.`,
      ng:`도려내는 사이 번짐이 더 빨랐다. 손잡이 받침이 녹아 떨어졌다.<br><br>손잡이 없는 방패는 쇳덩이다. 결국 다 버렸다.<br>도려내느라 벌린 시간에 대열은 반 구간 뒤처졌다. 미련의 값이다. 끓는 것 앞에서는 셈을 빨리 끝내야 한다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-27, spirit:-16 } }
  ] },

{ at:'S1', t:'환풍구 — 방패가 못 가는 길',
  x:`길이 환풍구뿐이다. 어깨 폭 관. 방패는 어떻게 돌려도 안 들어간다.<br><br>
    방패 없이 관을 기는 건 벗고 눈밭에 서는 기분이다.<br>
    그리고 관 속에서는 맨 뒤가 맨 약하다. 뒤를 돌아볼 수도, 무기를 휘두를 수도 없다.<br><br>
    맨 뒤는 이쪽 자리다. 그건 변하지 않는다. 방법만 정하면 된다.`,
  o:[
    { l:'① 방패를 끈으로 묶어 발 뒤에 끌고 간다 — 움직이는 뒷문으로.', k:'fix', dc:24,
      ok:`방패에 끈을 걸어 발목에 묶고 맨 뒤에서 기었다. 방패가 반 뼘 뒤에서 관을 막으며 따라왔다.<br><br>관 중간에서 뒤쪽의 무엇이 방패를 긁었다. 밀고, 두드리고, 또 긁었다.<br>문은 안 열렸다. 끌고 가는 문이라 열 수가 없다. 출구까지 긁는 소리가 따라왔지만 소리는 살을 못 뚫는다.`,
      ng:`관이 꺾이는 데서 방패가 모서리에 걸렸다. 발목 끈이 팽팽해졌다.<br><br>그 순간 뒤의 것이 방패를 당겼다. 발목째 반 뼘 끌려갔다.<br>끈을 끊고 방패를 내줬다. 관 저쪽에서 쇠 구기는 소리가 오래 났다. 방패 값으로 발목을 산 셈이다. 싸게 산 거라고, 다들 그랬다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 방패를 두고 간다 — 발부터 들어가 뒤를 보며 긴다.', k:'steady', dc:25,
      ok:`방패를 입구에 세워 두고 발부터 들어갔다. 얼굴이 뒤쪽을 향한 채, 팔꿈치로 밀며.<br><br>거꾸로 기는 건 배로 느리고 배로 힘들다. 그래도 뒤에서 오는 건 다 보였다.<br>관 끝까지 아무것도 안 왔다. 세워 둔 방패가 입구를 지켰는지도 모른다. 쇠 냄새도 문 노릇을 한다.`,
      ng:`거꾸로 기던 팔꿈치가 관 바닥 틈에 끼었다. 빼는 사이 대열과 간격이 벌어졌다.<br><br>그 간격의 어둠에서 숨소리가 났다. 이쪽 발 냄새를 맡는 소리.<br>팔꿈치 살을 틈에 바치고 빠져나왔다. 출구에서 세어 보니 대열은 다 있었다. 이쪽 팔꿈치만 반 뼘 모자랐다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-29, mind:-15 } }
  ] },

{ at:'S1', t:'벨 수 없는 적',
  x:`같이 가던 생존자의 가슴 속에서 무엇이 움직인다. 의원 말로는 아직 꺼낼 수 있는 때라고 한다.<br><br>
    다만 수술 동안 그것이 날뛰면 숙주째 찢고 나온다고 했다.<br>
    검을 뽑아 들고 깨달았다. 겨눌 데가 없다. 적이 아군 속에 있다.<br><br>
    수련 어디에도 없던 상황이다. 여기서부터는 혼자 배워야 한다.`,
  o:[
    { l:'① 검을 거두고 그 사람 곁에 선다 — 나올 때까지.', k:'bond', dc:25, wake:1,
      ok:`검을 거두고 그 사람 손을 잡았다. 수술 내내 눈을 맞추고 숨을 세어 줬다.<br><br>숙주가 고요하면 속엣것도 고요하다. 의원의 손이 끝까지 갔다.<br>꺼내진 것이 접시 위에서 한 번 꿈틀하고 멎었다. 그제야 검을 뽑아 끝을 냈다. 벨 자리는 그때 처음 생겼다.<br><br>적이 사람 속에 있을 때 기사가 설 자리는 검 끝이 아니라 손끝이라는 것. 지키는 일의 지도가 한 장 넓어졌다.`,
      ng:`곁에 서긴 했는데 쥔 손에 힘이 너무 들어갔다. 이쪽 긴장이 그 사람에게 옮았다.<br><br>숙주의 숨이 가빠지자 속엣것이 날뛰었다. 의원이 손을 뺐다.<br>수술은 다음 날로 밀렸다. 그 사람은 하룻밤을 더 그것과 살았다. 곁에 서는 것도 기술이다. 힘 조절까지가.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-19, spirit:-23 } },
    { l:'② 수술 방 문 앞을 지킨다 — 바깥의 적이라도 맡는다.', k:'steady', dc:24,
      ok:`수술 동안 문 앞에 섰다. 피 냄새는 이 시설의 저녁 종이다. 반드시 무엇이 온다.<br><br>왔다. 복도 끝에서 둘. 방패를 두드려 이쪽으로 꾀었다. 수술 방 반대쪽으로.<br>한 시진을 복도에서 숨바꼭질했다. 문이 열리고 의원이 엄지를 들어 보였다. 벨 수 없는 적은 못 베도, 베러 오는 것들은 벨 수 있다.`,
      ng:`문 앞은 지켰는데 피 냄새가 생각보다 빨리 퍼졌다. 셋이 왔다.<br><br>둘은 꾀어냈는데 하나가 문틈을 긁었다. 수술 방 안의 숨이 다 멎었다.<br>방패째 몸으로 밀어냈다. 수술은 끝났지만 의원 손이 한 번 떨렸다고 했다. 그 한 번이 꿰맨 자리에 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-16 } },
    { l:'③ 그 사람 눈을 똑바로 보고 아직 그 사람인지 확인한다.', k:'gaze', dc:25,
      ok:`눈을 봤다. 겁에 질린 눈이다. 겁은 사람 것이다. 그것들은 겁이 없다.<br><br>아직 사람이라고 의원에게 일렀다. 의원의 칼이 망설임을 버렸다.<br>눈이 흐려지는 순간이 오면 그때는 이쪽 차례라는 것도, 눈으로 그 사람과 약속했다. 그 약속이 수술보다 그 사람을 진정시켰다.`,
      ng:`눈을 보는데 그 사람이 눈을 피했다. 제 눈에 뭐가 보일까 봐 겁낸 것이다.<br><br>피한 눈은 읽을 수 없다. 확인은 실패했다.<br>의원은 더 큰 안전 수칙으로 수술했다. 묶고, 재갈 물리고. 사람을 사람 아닌 듯 다루는 걸 지켜보는 일이 수술보다 길었다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'S1', t:'여왕 앞의 기사',
  x:`가장 깊은 방을 가로질러야 한다. 어둠 안쪽에 그것이 있다. 크고, 느리고, 깨어 있다.<br><br>
    이쪽을 본다. 정확히는, 방패를 본다.<br>
    긴 머리가 기울어진다. 무기를 아는 몸짓이다. 병정을 알아보는 병정의 눈.<br><br>
    여기서 방패는 말이다. 무슨 말을 할지 정해야 한다.`,
  o:[
    { l:'① 방패를 낮추지 않은 채 뒷걸음으로 팀을 물린다.', k:'bond', dc:26,
      ok:`방패를 든 채 맨 뒤에서 뒷걸음으로 물렸다. 팀이 벽을 타고 건너편 문으로.<br><br>그것은 방패와 눈을 맞춘 채 움직이지 않았다. 경계는 하되 덤비지 않는 상대를 저쪽도 아는 것이다.<br>문을 넘는 마지막 순간까지 방패를 안 낮췄다. 그것이 고개를 한 번 까딱였다. 병정끼리의 인사 같기도 했고, 다음에 보자는 말 같기도 했다. 둘 다 아니길 빈다.`,
      win:{ exp:25, dream:4 }, lose:{ mind:-18, spirit:-20 },
      ng:`뒷걸음 중에 발밑의 뼈 무더기를 밟았다. 소리가 방을 울렸다.<br><br>그것의 머리가 소리 쪽으로 쏠리며 반 발 다가왔다. 방 전체의 공기가 조여들었다.<br>방패를 든 채 셋을 세고, 넷을 세고, 그것이 도로 물러날 때까지 숨을 안 쉬었다. 문을 넘고 나서 다들 바닥에 주저앉았다.` },
    { l:'② 방패를 내려놓는다 — 싸울 뜻이 없다는 말로.', k:'steady', dc:26,
      doom:{ title:'내려놓은 말', what:'여왕의 어둠 속으로 끌려갑니다', dc:20, sec:38,
        text:`방패를 천천히 바닥에 내려놓았다. 싸울 뜻이 없다는 말로.<br><br>그것에게는 다른 말로 들렸다. 지킬 것을 버린 병정. 임자 없는 몸.<br><br>긴 것이 바닥을 쓸며 와 발목을 감았다. 방패 없는 몸이 어둠 안쪽으로 미끄러진다. 말은 통했는데 사전이 달랐다.`,
        dieText:`방패는 방 가운데 그대로 놓여 있었다. 팀은 그걸 두고 나올 수밖에 없었다.<br><br>나중에 그 방을 지난 팀이 말했다. 방패가 어둠 안쪽 깊은 데로 옮겨져 있더라고. 뼈 무더기 가장 높은 자리에, 반듯하게.<br>전리품인지 비석인지는 아무도 모른다.` },
      ok:`방패를 반쯤 내렸다. 끝까지는 아니고, 겨눔을 푸는 높이까지만.<br><br>그것이 오래 쟀다. 그리고 몸을 틀어 길을 반 내줬다.<br>반 내준 길을 다섯이 지났다. 방패를 완전히 놓지 않길 잘했다. 예의와 항복은 한 끗 차이고, 그 한 끗이 목이다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S1', t:'금 가는 유리벽',
  x:`제어실 문을 따는 데 시간이 걸린다. 그 사이 등 뒤 관찰창 유리에 금이 번지고 있다.<br><br>
    유리 너머는 캄캄하다. 캄캄한데, 금은 안쪽에서부터 번진다.<br>
    문이 열리기까지 몇 분. 유리가 버티는 시간이 그보다 짧아 보인다.<br><br>
    버티는 시간은 늘릴 수 있다. 몸으로 늘리는 법을 안다.`,
  o:[
    { l:'① 등으로 유리를 받친다.', k:'steady', dc:25,
      ok:`유리에 등을 대고 발로 바닥을 밀었다. 금이 번지다 등판에서 멎었다.<br><br>유리 너머에서 무엇이 등을 밀었다. 한 번, 두 번. 그때마다 마주 밀었다.<br>문이 열렸다. 등을 떼자 금이 와르르 번졌지만 다섯은 이미 문 안이었다. 유리의 수명에 이쪽 등 힘을 보태 준 것뿐이다. 그거면 됐다.`,
      ng:`세 번째 밀림이 셌다. 유리가 등 뒤에서 거미줄처럼 갈라졌다.<br><br>파편이 외투를 뚫고 몇 개 박혔다.<br>문이 열리는 순간 다 같이 굴러 들어갔다. 닫힌 문 너머에서 유리 마저 깨지는 소리와, 바닥을 쓰는 소리가 났다. 등에 박힌 파편은 의원이 밤에 뽑았다.`,
      win:{ exp:16, dream:3 }, lose:{ hp:-30, mind:-15 } },
    { l:'② 선반을 끌어와 버팀대를 세운다.', k:'fix', dc:24,
      ok:`철제 선반 둘을 쓰러뜨려 유리에 비스듬히 괴었다. 버팀 각은 수련 때 배운 그대로.<br><br>유리가 밀릴 때마다 선반이 바닥에 긁히며 버텼다. 쇠가 대신 서 준 것이다.<br>문이 열리고 다 들어간 뒤에도 선반은 버티고 있었다. 잘 세운 각은 사람보다 오래 선다.`,
      ng:`선반을 끄는 소리가 너무 컸다. 유리 너머의 것이 소리 자리로 몰렸다.<br><br>버팀대를 세우기 전에 금이 주먹만큼 뚫렸다. 구멍으로 긴 것이 쑥 들어왔다.<br>선반째 밀어 구멍을 틀어막고 문이 열릴 때까지 다 같이 선반을 눌렀다. 문이 열리는 소리가 그렇게 반가울 수 없었다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-27, mind:-16 } }
  ] },

{ at:'S1', t:'죽은 경비의 자리',
  x:`복도 끝 초소에 경비 하나가 앉은 채 말라 있다. 가슴에 사원증. 손에는 진압 방패.<br><br>
    방패 면이 온통 긁히고 패었다. 수십 번을 받아 낸 자국이다.<br>
    초소 뒤 문에는 긁힌 자국이 하나도 없다. 이 사람 선에서 다 끝난 것이다.<br><br>
    등 뒤의 문을 지키다 간 사람. 이름은 모르지만 직업은 같다.`,
  o:[
    { l:'① 그 방패를 이어받는다.', k:'bond', dc:24, wake:1,
      ok:`굳은 손가락을 하나씩 펴고 방패를 받았다. 이쪽 것보다 무겁고, 팬 자국마다 각이 남아 있다.<br><br>패인 각들이 말해 줬다. 여기 것들은 낮게, 비스듬히, 세 번 연달아 온다고.<br>사원증은 주머니에 넣었다. 나가면 어딘가에 전해 줄 것이다.<br><br>자리는 사람보다 오래 남는다는 것. 방패를 받는 건 쇠가 아니라 그 자리를 받는 일이라는 것. 어깨가 무거워진 만큼 등이 곧아졌다.`,
      ng:`방패를 받아 드는데 초소 선반의 깡통들이 무너졌다. 요란하게.<br><br>복도 저쪽에서 대답처럼 긁는 소리가 왔다. 죽은 경비가 몇 날을 막던 그 소리.<br>방패를 든 채 첫 손님을 바로 받았다. 인수인계치고는 험했다. 세 번 연달아 오는 버릇만은 자국이 미리 가르쳐 준 대로였다. 그게 살렸다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 그 사람의 마지막 자세를 읽어 적는다.', k:'gaze', dc:24,
      ok:`앉은 자세를 오래 봤다. 무릎 각, 방패 기울기, 등과 문의 거리.<br><br>교본에 없는 자세다. 교본은 서서 막으라고 한다. 이 사람은 앉아서 막았다. 낮게 오는 것들에게는 낮은 벽이 맞으니까.<br>수첩에 그 각을 그렸다. 죽은 사람이 몸으로 남긴 교본 한 장. 그날부터 낮은 것들 앞에서는 앉는다.`,
      ng:`자세를 읽느라 너무 오래 머물렀다. 초소의 어둠에 눈이 익어 버렸다.<br><br>익은 눈에 보이기 시작했다. 바닥의 핏자국이 초소 안쪽으로도 한 줄 이어진 것이.<br>문 안쪽 것은 문을 못 넘었지만, 다른 무엇은 넘었던 것이다. 서둘러 자리를 떴다. 배움에도 머물 수 있는 시간이 있다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'S2', t:'울타리 구멍 — 몸으로 막는 문',
  x:`밤에 울타리 한 구간이 뜯겼다. 어른 몸통만 한 구멍.<br><br>
    고칠 자재는 아침에야 구한다. 그때까지 구멍은 열려 있고, 풀숲의 그것들은 열린 것을 귀신같이 안다.<br>
    벌써 구멍 밖 어둠에서 발소리가 간을 본다. 하나, 둘.<br><br>
    문이 없으면 문이 되는 수밖에. 그러라고 배운 몸이다.`,
  o:[
    { l:'① 구멍에 방패를 대고 밤새 문이 된다.', k:'bond', dc:25,
      ok:`구멍에 방패를 대고 그 뒤에 앉았다. 어깨로 받치고, 무릎으로 괴고.<br><br>밤새 세 번 부딪혀 왔다. 세 번 다 쇠를 받고 물러났다. 네 번째부터는 발소리만 오갔다. 문이 단단한지 재는 소리.<br>아침에 자재가 왔을 때 방패 면에 침 자국이 말라붙어 있었다. 문에 침 바르고 간 손님들. 들인 적은 없다.`,
      ng:`새벽녘 부딪힘이 유난히 셌다. 방패째 반 자 밀렸다.<br><br>구멍 틈으로 발톱 하나가 들어와 어깨를 긁고 나갔다.<br>소리에 깬 팀원들이 몰려와 교대해 줬다. 혼자 서는 밤문은 반 밤이 한계라는 걸 어깨가 배웠다.`,
      win:{ exp:17, dream:3 }, lose:{ hp:-29, mind:-14 } },
    { l:'② 구멍 밖으로 나가 간 보는 것들을 쫓고 온다.', k:'break', dc:26,
      doom:{ title:'울타리 밖', what:'울타리 밖 풀숲으로 끌려갑니다', dc:20, sec:36,
        text:`구멍을 넘어 어둠으로 나갔다. 간 보던 둘이 물러났다. 쫓았다.<br><br>물러나는 것들은 미끼였다. 풀숲의 결이 양옆에서 조여 왔다.<br><br>무리는 쫓기는 법을 안다. 쫓게 만드는 법도. 발목에 셋째 놈의 이빨이 걸리고, 풀숲 안쪽으로 몸이 끌린다. 울타리 구멍이 등 뒤에서 점처럼 멀어진다.`,
        dieText:`팀원들이 횃불을 들고 풀숲 어귀까지 쫓아갔다. 풀이 누운 길이 세 갈래로 갈라져 있었다.<br><br>세 갈래 다 가 볼 수는 없었다. 그게 무리의 셈법이다.<br>아침에 울타리 구멍은 수리됐다. 못질 소리가 조종(弔鐘) 같았다고, 아무도 입 밖에 내지 않았다.` },
      ok:`구멍을 넘어서되 울타리에서 세 걸음 이상 안 떨어졌다. 등 뒤에 쇠그물을 둔 채로만 휘둘렀다.<br><br>간 보던 둘이 방패 모서리에 한 번씩 받히고 물러났다. 쫓지는 않았다. 쫓는 순간 저쪽 판이다.<br>구멍 앞 세 걸음은 이쪽 판이었다. 그 세 걸음만 지켰다. 아침까지 손님은 다시 안 왔다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S2', t:'시험받는 자',
  x:`무리가 대열을 따라오며 간을 본다. 한 번에 하나씩, 스치듯 뛰어들었다 빠진다.<br><br>
    노리는 건 늘 같다. 제일 작은 사람, 제일 지친 사람, 제일 끝 사람.<br>
    시험은 막을 수 없다. 저들의 셈법이니까. 다만 시험지를 바꿀 수는 있다.<br><br>
    전부 이쪽을 보게 만들면 된다.`,
  o:[
    { l:'① 제일 크게 선다 — 시험은 전부 이쪽으로.', k:'bond', dc:25, wake:1,
      ok:`방패를 머리 위로 들고 대열 바깥쪽을 걸었다. 제일 크고, 제일 시끄럽고, 제일 성가신 표적.<br><br>시험이 전부 이쪽으로 왔다. 스치고, 받히고, 물러나고. 네 번을 받았다.<br>다섯 번째부터 무리가 흥미를 잃었다. 시험 점수가 안 나오는 문제지였던 것이다.<br><br>눈에 띄는 것이 가리는 것이라는 역설. 모두의 눈을 끄는 자리가 모두를 가리는 자리다. 그 자리에 서는 법을 몸이 외웠다.`,
      ng:`시험을 넷까지 받았다. 다섯째가 수를 바꿨다. 이쪽을 받는 척하며 둘이 동시에 왔다.<br><br>하나는 방패에 받혔는데 하나가 대열 끝을 스쳤다. 막내 배낭이 찢겼다.<br>시험지를 바꿔도 출제자는 저쪽이라는 걸 배웠다. 대열을 바위 쪽으로 붙이고서야 시험이 끝났다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 제일 약한 사람을 대열 한가운데 숨긴다.', k:'fix', dc:24,
      ok:`제일 지친 팀원을 가운데 넣고 네 사람으로 둘러쌌다. 바깥에서는 안 보이는 자리.<br><br>무리의 시험이 두 바퀴를 돌고 멈췄다. 노릴 표적이 안 보이니 셈이 안 서는 것이다.<br>표적 없는 사냥은 품만 든다. 무리는 품 계산이 빠르다. 셋째 바퀴는 없었다.`,
      ng:`가운데 자리가 오히려 그 팀원을 조였다. 사방이 등이라 아무것도 안 보이니까.<br><br>겁이 커진 그 팀원이 대열 밖으로 고개를 뺐다. 그 머리 하나를 무리가 봤다.<br>바로 시험이 들어왔다. 네 사람이 한꺼번에 조여 막았다. 숨기는 것과 가두는 것은 다르다는 걸 배웠다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-18, spirit:-19 } },
    { l:'③ 첫 시험만 세게 받아친다 — 본보기로.', k:'break', dc:25,
      ok:`첫 놈이 스치러 들어오는 각을 미리 읽고, 빠지는 길목에 방패 모서리를 박았다.<br><br>스치려던 놈이 정통으로 받혔다. 깨갱하는 소리가 풀밭을 갈랐다.<br>본보기는 한 번이면 된다. 무리는 깨갱 소리의 뜻을 안다. 시험은 거기서 끝났다.`,
      ng:`길목을 반 뼘 잘못 읽었다. 모서리가 허공을 치고 이쪽 옆구리가 열렸다.<br><br>열린 옆구리를 놈이 스치고 지나갔다. 갈비 쪽이 뜨끔했다.<br>본보기를 보이려다 본보기가 될 뻔했다. 두 번째부터는 받아치기를 접고 버티기로 바꿨다. 셈은 밑천 안에서 해야 한다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-32, mind:-14 } }
  ] },

{ at:'S2', t:'물 건너기 — 하류에 서는 사람',
  x:`물에 잠긴 고사리 밭을 건넌다. 물살은 약하지만 발밑이 진창이다.<br><br>
    그리고 하류 쪽 물안개 속에 그것들이 있다. 물 건너는 짐승의 다리를 노리는 것들.<br>
    넘어지는 사람이 나오면 하류로 쓸리고, 쓸리는 쪽에 이빨이 기다린다.<br><br>
    그러면 하류 쪽에 벽이 있으면 된다. 벽 할 사람도 정해져 있다.`,
  o:[
    { l:'① 하류 쪽에 서서 물살과 이빨을 한 몸으로 받는다.', k:'bond', dc:25, cost:{ might:34 },
      ok:`대열 하류 쪽 반걸음 뒤에 서서 같이 건넜다. 방패를 물에 반쯤 담근 채.<br><br>셋째가 진창에 미끄러졌다. 쓸리는 몸이 이쪽 방패에 걸려 섰다. 물안개 쪽에서 이빨 둘이 왔다가 방패 테에 코를 박고 돌아갔다.<br>다 건너고 보니 하류 쪽 다리가 이빨 자국 대신 멍투성이였다. 멍은 벽의 월급이다.`,
      ng:`넷째가 미끄러질 때 방패가 반 박자 늦었다. 몸이 방패 아래로 쓸렸다.<br><br>물속에서 그 팀원 허리를 잡아 세우는 사이 물안개의 것이 이쪽 장딴지를 스쳤다.<br>다 건넜다. 장딴지에서 피가 물을 타고 하류로 길게 흘렀다. 물안개 쪽이 그 냄새로 소란해지는 소리를 들으며 뭍을 밟았다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 제일 깊은 가운데 물목을 이쪽이 맡는다.', k:'steady', dc:25,
      doom:{ title:'가운데 물목', what:'물속으로 끌려 들어갑니다', dc:20, sec:36,
        text:`가슴까지 오는 가운데 물목에 서서 넷을 차례로 건네줬다. 손에서 손으로.<br><br>넷째를 건네고 제 차례에, 발밑 진창이 꺼졌다.<br><br>진창이 아니었다. 기다린 것이다. 물목 한가운데, 제일 오래 서 있는 것을. 물이 정수리를 덮고, 몸이 뿌리 사이로 끌려 들어간다.`,
        dieText:`넷이 장대와 끈으로 물목을 한나절 뒤졌다. 방패만 걸려 나왔다.<br><br>방패는 하류 뭍에 세워 놓았다. 물 건너는 다음 팀이 보라고. 가운데 물목은 서는 자리가 아니라고.<br>그 방패는 지금도 거기 서 있다. 물안개가 끼면 꼭 사람 같다.` },
      ok:`가운데 물목에 버티고 서서 넷을 손에서 손으로 건넸다. 발가락으로 진창 아래 단단한 돌을 찾아 디디고.<br><br>넷째가 건너자마자 발밑에서 물이 당기는 힘이 왔다. 기다리던 것이 더는 못 참은 것이다.<br>디딘 돌을 차고 몸을 날렸다. 넷이 뻗은 손에 걸려 뭍으로 쏠려 올라왔다. 등 뒤 물목이 소용돌이쳤다. 마지막까지 안 서 있는 것. 그게 가운데 물목의 유일한 법이다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S2', t:'연습 사냥',
  x:`어린것들이 대열을 쫓아온다. 어미들 절반 크기. 덤비는 시늉, 빠지는 시늉.<br><br>
    장난이 아니다. 수업이다. 사람 사냥 수업. 풀숲 안쪽에서 큰 그림자들이 참관 중이다.<br>
    오늘 수업이 잘되면 다음 팀은 진짜 사냥을 당한다.<br><br>
    그렇다면 할 일은 하나다. 수업을 망치는 것.`,
  o:[
    { l:'① 첫 돌진을 방패로 세게 받아 수업을 끝낸다.', k:'bond', dc:25, wake:1,
      ok:`어린것 하나가 시늉 반 진심 반으로 들어왔다. 시늉으로 받지 않았다. 온 힘으로 받았다.<br><br>쇠에 받힌 어린것이 두 바퀴 굴러 깨갱거리며 돌아갔다. 나머지가 얼어붙었다.<br>풀숲의 참관자들이 어린것들을 거둬 물러났다. 오늘 배운 것 — 사람은 벽이다. 그 한 줄이면 다음 팀 몫까지 가르친 셈이다.<br><br>지키는 일은 오늘 너머까지 간다는 것. 한 번의 벽이 뒷사람들의 울타리가 된다는 것. 방패가 조금 더 멀리 보게 됐다.`,
      ng:`세게 받긴 받았는데 각이 얕았다. 어린것이 구르지 않고 비껴 돌았다.<br><br>수업 내용이 바뀌었다. 벽은 비껴 돌면 된다, 로.<br>영리한 것들이라 바로 써먹었다. 양옆으로 번갈아 오는 시늉에 대열이 한참 시달렸다. 바위 지대에 들어서서야 수업이 파했다. 가르칠 거면 확실히 가르쳐야 했다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 수업에 장단 맞춰 주지 않고 바위 틈으로 피한다.', k:'evade', dc:24,
      ok:`대열을 바위 지대로 꺾었다. 틈이 좁고 모서리가 많은 곳.<br><br>어린것들의 시늉은 트인 데서 배운 동작이다. 바위 틈에서는 하나도 안 먹혔다.<br>수업은 교재 없음으로 휴강됐다. 참관자들이 어린것들을 몰고 떠났다. 싸우지 않고 망친 수업이 제일 잘 망친 수업이다.`,
      ng:`바위 지대로 꺾는 길목이 하필 수업 자리와 겹쳤다. 어린것들이 신나서 따라붙었다.<br><br>좁은 틈 입구에서 대열이 밀렸다. 맨 뒤가 시늉에 두 번 긁혔다.<br>틈에 다 들어가고서야 떨쳐 냈다. 긁힌 자국은 얕았다. 다만 어린것들 수업에 실습 교재가 된 기분은 오래 씁쓸했다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-27, mind:-15 } }
  ] },

{ at:'S2', t:'승강장 — 문이 열릴 때까지',
  x:`낡은 승강기를 불렀다. 쇠줄 감기는 소리가 까마득한 위에서 내려온다. 오래 걸린다.<br><br>
    승강장은 트였다. 등 뒤는 수풀, 옆은 물가. 소리는 벌써 정원 반을 돌았을 것이다.<br>
    기다림은 사냥터에서 제일 비싼 시간이다.<br><br>
    문이 열릴 때까지, 다섯이 어떻게 서 있을 것인가.`,
  o:[
    { l:'① 등을 맞대고 둥글게 선다 — 방패가 바깥.', k:'bond', dc:24,
      ok:`다섯이 등을 맞대 둥글게 서고 방패를 바깥에 뒀다. 사방이 다 누군가의 정면.<br><br>수풀이 두 번 일렁였다. 두 번 다 일렁인 쪽 정면이 마주 노려봤다. 들어올 틈이 없는 원.<br>쇠줄 소리가 바닥에 닿고 문이 열렸다. 원이 그대로 뒷걸음쳐 통째로 올라탔다. 마지막까지 원은 안 깨졌다.`,
      ng:`원은 섰는데 물가 쪽 담당이 물안개에 자꾸 눈을 뺏겼다.<br><br>그 틈에 수풀 쪽에서 하나가 원 바로 앞까지 왔다. 코앞에서 마주쳤다.<br>방패로 밀고 원을 조여 버텼다. 문이 열리는 소리가 그날따라 늦었다. 늦은 게 아니라 길게 느껴진 거라고, 나중에 알았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-27, mind:-16 } },
    { l:'② 철골 위로 올라가 높은 데서 내려다본다.', k:'sense', dc:24,
      ok:`승강장 철골에 다섯이 올라앉았다. 높이 한 길 반.<br><br>내려다보니 수풀의 움직임이 다 보였다. 세 마리가 번갈아 승강장 아래를 돌았다.<br>높은 데 것은 안 건드린다. 이 정원의 법이다. 큰 것에게 높이란 곧 크기니까. 문이 열릴 때까지 세 마리의 순찰을 구경했다.`,
      ng:`철골이 삭아 있었다. 둘째가 오르다 가로대가 부러졌다.<br><br>떨어진 소리에 수풀이 일제히 일렁였다.<br>부러진 가로대를 창처럼 쥐고 바닥 조를 지켰다. 문이 열리자 위 조가 뛰어내려 같이 탔다. 오르는 것도 내리는 것도 다 계획이 필요하다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-28, mind:-14 } },
    { l:'③ 수풀 쪽으로 몇 걸음 나가 마중선을 긋는다.', k:'steady', dc:26,
      doom:{ title:'마중선', what:'수풀 속으로 끌려갑니다', dc:19, sec:38,
        text:`승강장 앞 다섯 걸음에 홀로 나가 섰다. 여기부터는 못 온다는 선으로.<br><br>선은 저쪽도 그었던 모양이다. 이쪽 선과 저쪽 선 사이가 사냥 자리였다.<br><br>수풀이 소리 없이 갈라지며 양옆에서 왔다. 방패가 한쪽을 받는 사이 다른 쪽이 허리를 물었다. 마중 나간 사람부터 마중당했다.`,
        dieText:`문이 열렸을 때 승강장 앞 다섯 걸음에는 방패만 떨어져 있었다.<br><br>넷은 타지 않고 횃불을 들고 수풀 어귀를 밤새 지켰다. 아무것도 돌려받지 못했다.<br>새벽 첫 승강기로 넷이 올랐다. 방패는 제일 어린 팀원이 품에 안고 탔다.` },
      ok:`승강장 앞 다섯 걸음에 나가 서서 방패 테로 바닥에 길게 금을 그었다. 쇠가 돌을 긁는 소리가 수풀까지 갔다.<br><br>수풀의 것들이 그 금 앞에서 멈췄다. 금의 뜻을 알아서가 아니라, 금을 긋고 버티는 몸의 뜻을 알아서다.<br>문이 열리고 넷이 타는 동안 금 앞을 지켰다. 마지막에 뒷걸음으로 탔다. 금은 남겨 두고 왔다. 다음 팀 몫이다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S2', t:'울타리 기둥 — 급조한 창',
  x:`큰 것 하나가 울타리 바깥 길을 막았다. 돌아갈 길이 없다. 올 것이다. 곧게, 크게.<br><br>
    방패로 받기엔 크다. 받는 게 아니라 깔린다.<br>
    쓰러진 울타리 기둥이 눈에 들어왔다. 끝이 부러져 뾰족한 쇠기둥.<br><br>
    옛 책에 있다. 돌진하는 큰 것은 제 무게로 잡는다.`,
  o:[
    { l:'① 기둥을 바닥에 비껴 박고 돌진을 받는다.', k:'break', dc:26, cost:{ might:30 },
      ok:`기둥 밑동을 바닥 틈에 박고 끝을 가슴 높이로 괴었다. 각은 낮게, 몸은 기둥 뒤에.<br><br>돌진이 왔다. 마지막 반 숨까지 기둥을 숨기고 버티다 몸만 비켰다.<br>제 무게로 어깨를 꿰인 큰 것이 길길이 울며 물러났다. 죽이지는 못했다. 다만 다시 오지도 않았다. 큰 것들은 아픈 걸 오래 기억한다.`,
      ng:`기둥 밑동이 박힌 틈이 얕았다. 돌진의 무게에 기둥째 튕겨 나갔다.<br><br>튕긴 기둥에 이쪽 어깨가 쓸리고, 큰 것의 옆구리에 스친 대열이 흩어졌다.<br>다행히 큰 것도 기둥 끝에 살갗이 그어져 돌진을 접었다. 양쪽 다 피를 본 무승부. 무승부면 산 것이다.`,
      win:{ exp:17, dream:3 }, lose:{ hp:-31, mind:-15 } },
    { l:'② 기둥 대신 바위 뒤로 대열을 꺾는다.', k:'evade', dc:24,
      ok:`돌진의 직선을 거슬러 바위 무더기 뒤로 대열을 꺾었다.<br><br>큰 것은 꺾지 못한다. 덩치는 직선의 세금이다.<br>바위를 두 번 끼고 도는 사이 큰 것의 돌진은 두 번 다 허공을 갈랐다. 세 번째 돌진은 없었다. 세금이 너무 비싸진 것이다.`,
      ng:`꺾는 길목의 바위가 생각보다 낮았다. 큰 것이 바위째 밀고 들어왔다.<br><br>부서진 돌조각이 우박처럼 쏟아졌다. 등으로 막내를 덮었다.<br>등판이 돌에 두들겨 맞는 동안 대열은 다음 바위로 빠졌다. 큰 것은 바위 값을 치르고 물러났다. 이쪽은 등 값을 치렀다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-30, spirit:-15 } }
  ] },

{ at:'S2', t:'마지막 자리',
  x:`승강기 문이 열렸다. 하나씩 오른다. 셋, 넷.<br><br>
    마지막 자리는 정해져 있다. 맨 나중에, 얼굴은 정원 쪽으로.<br>
    들어가는 등을 어둠에 보이지 않는 것. 그게 방패 든 사람이 문에서 서는 법이다.<br><br>
    수풀 가장자리에 그것들이 나와 서 있다. 배웅인지 아쉬움인지 모를 눈들.`,
  o:[
    { l:'① 맨 마지막에 오른다 — 얼굴은 정원 쪽으로.', k:'bond', dc:25, wake:1,
      ok:`넷이 다 오르고, 방패를 든 채 뒷걸음으로 탔다. 눈은 수풀의 눈들과 마주 둔 채.<br><br>문이 닫히는 마지막 금까지 아무것도 오지 않았다. 등을 안 보이는 것에게는 덤빌 자리가 없다.<br>문이 닫히고 나서야 방패를 내렸다. 팔이 그제야 떨렸다.<br><br>마지막 자리의 뜻을 배웠다. 맨 나중은 남는 자리가 아니라 맡는 자리다. 문이 있는 곳마다 그 자리가 있을 것이다. 이제 거기가 이쪽 자리다.`,
      ng:`뒷걸음 마지막 발이 문턱에 걸렸다. 몸이 휘청하며 방패가 내려갔다.<br><br>그 반 숨에 수풀에서 하나가 쏘아져 나왔다. 닫히는 문틈에 발톱이 박혔다 빠졌다.<br>문짝에 발톱 자국 세 줄을 싣고 올라갔다. 마지막 자리는 마지막 반 숨까지가 일이라는 걸, 문짝이 대신 배워 줬다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 방패를 문틈에 괴어 모두 오를 때까지 문을 잡아 둔다.', k:'steady', dc:25,
      ok:`낡은 문은 변덕을 부린다. 방패를 문턱에 괴어 닫힘 틀을 막고, 그 위로 넷을 올렸다.<br><br>문이 두 번 닫히려다 방패에 막혀 두 번 되열렸다.<br>마지막에 방패를 빼며 올라탔다. 문이 기다렸다는 듯 닫혔다. 쇠의 변덕은 쇠로 막는다. 사람 몸으로 막는 건 그다음 수다.`,
      ng:`문이 방패를 문 채로 승강기가 반 뼘 떠올랐다. 노후한 것들은 순서를 안 지킨다.<br><br>방패가 문틈에 씹혀 비틀렸다. 억지로 빼다 균형을 잃고 바닥을 굴렀다.<br>팀원들이 끌어올려 줬다. 비틀린 방패는 무릎으로 펴서 들었다. 펴지긴 펴졌다. 소리가 날 때마다 그 반 뼘이 생각난다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-15 } }
  ] }

]);

// ------------------------------------------
// 신호수 · 자원 없음
// ------------------------------------------
kJob('signal', 'S', [

{ at:'S', t:'신호를 바꾸는 날',
  x:`간밤에 이쪽 호루라기 소리가 어둠 저쪽에서 났다. 길게 두 번, 짧게 한 번. 집합 신호.<br><br>
    토씨 하나 안 틀렸다. 숨 쉬는 자리까지 같았다.<br>
    신호가 넘어갔다. 넘어간 신호는 이제 저쪽 미끼다. 다음에 저 소리가 나면 누군가는 모일 것이다. 모이는 자리에서 무슨 일이 날지는 뻔하다.<br><br>
    신호수의 수첩은 살아 있어야 한다. 죽은 신호는 바로 묻어야 한다.`,
  o:[
    { l:'① 밤새 새 신호를 짜고, 아침에 옛 신호를 장사 지낸다.', k:'bond', dc:24, wake:1,
      ok:`밤새 새 체계를 짰다. 호루라기는 버리고, 혀 차는 소리와 돌 두드림으로. 음도 박자도 전부 새로.<br><br>아침에 다섯을 모아 가르쳤다. 그리고 옛 집합 신호는 이제 흩어지라는 뜻이라고 못 박았다.<br>이틀 뒤 어둠이 옛 신호를 불었다. 다섯이 일제히 흩어졌다. 모이기를 기다리던 것이 빈 가운데에 오래 서 있었다.<br><br>신호는 한 번 새면 뒤집어 쓰는 것. 뺏긴 말을 독으로 바꾸는 법을 배웠다. 수첩이 한 장 두꺼워졌다.`,
      ng:`새 신호를 가르치는데 막내가 자꾸 옛 버릇으로 대답했다.<br><br>버릇은 하루아침에 안 죽는다. 섞인 신호는 없느니만 못하다.<br>이틀을 반 벙어리로 걸었다. 신호 없이 걷는 대열은 눈 가리고 걷는 대열이다. 사흘째에야 새 말이 혀에 붙었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-19 } },
    { l:'② 소리를 다 버리고 손짓으로만 간다.', k:'fix', dc:23,
      ok:`소리 신호를 전부 폐기했다. 손짓 여덟 개만 남겼다. 서라, 와라, 엎드려라, 뛰어라.<br><br>손짓은 빛이 있어야 보인다. 그래서 대열을 등불 반경 안으로 좁혔다.<br>좁아진 대열은 느렸지만 소리가 없었다. 소리를 흉내 내던 것이 흉내 낼 것을 잃었다. 침묵은 베낄 수 없다.`,
      ng:`손짓만으로 사흘째, 갈림길에서 손짓 둘이 겹쳐 보였다. 서라와 뛰어라.<br><br>둘은 서고 셋은 뛰었다. 대열이 갈라진 틈을 어둠이 지나갔다.<br>다시 합치는 데 한 시진이 들었다. 합치고 보니 막내 소매가 찢겨 있었다. 언제 찢겼는지 본인도 몰랐다. 그게 제일 섬뜩했다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'S', t:'가린 불빛',
  x:`앞서간 둘과 길이 어긋났다. 어둠 건너편에서 둘의 기척이 난다. 살아 있다.<br><br>
    불빛을 흔들면 한 번에 찾는다. 그리고 한 번에 들킨다. 이 어둠 전체에.<br>
    빛은 제일 빠른 신호고 제일 비싼 신호다. 값을 깎는 법을 알아야 한다.<br><br>
    등불, 외투, 그리고 벽. 쓸 것은 이 셋이다.`,
  o:[
    { l:'① 외투 속에 등을 숨겨 그쪽 방향으로만 연다.', k:'bond', dc:24,
      ok:`외투로 등불을 감싸고 둘이 있는 방향으로만 틈을 냈다. 짧게 셋, 길게 하나.<br><br>빛의 부채꼴이 손바닥만 했다. 그 손바닥 안에 둘이 들어왔다.<br>건너편에서 돌 두드림이 답했다. 짧게 셋. 반각 뒤 다섯이 다시 모였다. 어둠의 나머지는 아무것도 못 봤다. 빛을 바늘처럼 쓰는 법이다.`,
      ng:`틈을 낸 순간 바람이 외투 자락을 걷었다. 빛이 부챗살로 퍼졌다.<br><br>둘은 찾았다. 다만 먼 어둠에서도 무엇이 그 부챗살을 봤다.<br>모인 다섯이 바로 자리를 떴다. 밤새 세 번 길을 꺾었다. 빛의 값은 늘 생각보다 비싸다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-17, spirit:-18 } },
    { l:'② 빛 대신 돌 두드림으로 부른다.', k:'fix', dc:23,
      ok:`벽돌 두 개를 골라 쳤다. 돌 소리는 벽을 타고 가고, 벽을 타는 소리는 방향을 숨긴다.<br><br>둘에게는 박자가 방향이다. 약속한 박자는 셋-쉬고-둘.<br>둘이 벽을 짚으며 박자를 거슬러 왔다. 어둠은 소리의 임자를 밤새 찾아 헤맸다. 벽이 사방에서 울렸으니까.`,
      ng:`두드림이 벽의 빈 데를 때렸다. 울림이 엉뚱한 쪽으로 몰렸다.<br><br>둘이 그 울림을 따라 반대로 갔다. 간격이 더 벌어졌다.<br>결국 위험을 무릅쓰고 불빛을 썼다. 돌아온 둘의 얼굴이 하얬다. 벌어진 쪽 어둠에서 숨소리를 들었다고 했다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-16, spirit:-19 } },
    { l:'③ 불을 끄고 어둠에 눈을 적신 뒤 맨눈으로 찾는다.', k:'sense', dc:25,
      ok:`등을 끄고 백을 셌다. 눈이 어둠에 젖자 안 보이던 것들이 보였다.<br><br>건너편 둘의 윤곽, 그 사이 통로의 결, 그리고 둘 뒤쪽에 엎드린 낮은 그림자 하나.<br>그림자가 비켜난 틈을 재서 손짓 대신 돌 하나를 굴렸다. 둘이 알아채고 이쪽으로 붙었다. 빛 한 점 안 쓴 재회였다.`,
      ng:`눈이 젖기 전에 막내가 겁에 질려 등을 다시 켰다.<br><br>어둠에 반쯤 열렸던 눈이 빛에 데어 도로 감겼다. 한참을 다 같이 장님이었다.<br>그 틈에 건너편 둘이 제 판단으로 움직였다. 다행히 이쪽으로였다. 운이었다. 운은 신호가 아니다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-17 } }
  ] },

{ at:'S', t:'정확한, 그러나 틀린 신호',
  x:`어둠 저쪽에서 이쪽 점호 신호가 왔다. 짧게 둘, 길게 하나. 패턴은 완벽하다.<br><br>
    다만 손이 틀렸다. 사람 손은 세 번을 쳐도 세기가 조금씩 다르다. 지치고, 설레고, 망설이니까.<br>
    이 두드림은 세 번이 다 똑같다. 저울로 단 것처럼.<br><br>
    완벽한 신호는 사람 것이 아니다. 신호수만 아는 구별법이다.`,
  o:[
    { l:'① 손버릇의 결을 끝까지 읽어 장부에 적는다.', k:'gaze', dc:24,
      ok:`두드림을 끝까지 들으며 결을 적었다. 간격, 세기, 숨 없는 박자.<br><br>베낀 것은 패턴이지 버릇이 아니다. 버릇 없는 신호를 가려내는 귀가 수첩에 박혔다.<br>그 통로를 지도에 빗금 치고 돌아 나왔다. 등 뒤에서 점호 신호가 조금 더 커졌다. 조급해진 것이다. 조급한 가짜는 더 쉽게 들린다.`,
      ng:`결을 읽는 데 팔렸다가 뒤를 놓쳤다. 두드림이 어느새 두 군데서 났다.<br><br>앞과 뒤. 패턴을 베낀 것이 하나가 아니었다.<br>옆 통로로 꺾어 빠졌다. 적던 수첩 장이 땀에 젖어 글씨가 번졌다. 번진 글씨는 나중에 다시 적었다. 그 밤의 손은 확실히 사람 손이었다. 떨렸으니까.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-19, spirit:-21 } },
    { l:'② 마주 신호를 보내 임자를 확인한다.', k:'bond', dc:25,
      doom:{ title:'마주친 신호', what:'신호의 임자에게 끌려갑니다', dc:19, sec:44,
        text:`확인 신호를 쳤다. 넷-쉬고-하나. 이쪽만 아는 대답을 기다렸다.<br><br>대답은 정확했다. 넷-쉬고-하나. 등 바로 뒤에서.<br><br>임자는 처음부터 뒤에 있었다. 앞의 두드림은 고개를 돌리게 하는 수였다. 입이 틀어막히고, 몸이 어둠으로 미끄러진다. 신호수를 잡으려면 신호로 잡는다는 걸, 저쪽도 알았던 것이다.`,
        dieText:`팀원들은 신호수가 사라진 자리에서 돌 두 개를 주웠다. 점호 신호를 치던 돌이다.<br><br>그날 밤부터 어둠의 두드림이 한결 능숙해졌다. 간격도, 세기도, 숨 쉬는 자리까지.<br>새 신호수가 올 때까지 그 팀은 아무 신호도 믿지 않기로 했다. 그게 제일 안전한 수첩이었다.` },
      ok:`확인 신호를 쳤다. 넷-쉬고-하나. 대답은 다섯이어야 한다. 이쪽 팀만 아는 셈이다.<br><br>저쪽이 넷-쉬고-하나를 그대로 돌려줬다. 베끼는 것은 셈을 못 한다.<br>확인 끝. 전원 침묵 신호를 돌리고 반대 통로로 빠졌다. 저쪽은 한참 동안 같은 패턴만 되풀이했다. 묻는 법만 알고 답하는 법은 모르는 것이다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S', t:'두드림 점호',
  x:`이 어둠에서는 목소리가 위험하다. 이름은 더 위험하다. 그래도 점호는 돌려야 한다.<br><br>
    점호 없는 밤에 하나가 사라지면, 아침에야 안다. 아침이면 늦는다.<br>
    소리 없이 수를 세는 법. 그게 오늘 밤 숙제다.<br><br>
    돌 하나와 벽이면 된다.`,
  o:[
    { l:'① 저마다 다른 두드림을 매겨 점호를 돌린다.', k:'bond', dc:23,
      ok:`다섯에게 하나씩 매겼다. 하나는 한 번, 둘은 둘, 막내는 길게 하나.<br><br>한 시진마다 점호를 돌렸다. 벽을 타고 다섯 두드림이 차례로 돌아오면 그 시진은 무사한 것이다.<br>셋째 밤, 점호 끝에 여섯째 두드림이 붙었다. 매긴 적 없는 박자. 즉시 전원을 깨워 자리를 떴다. 점호는 수를 세는 일이다. 수가 늘어도 알아야 한다.`,
      ng:`새벽 점호에서 넷째 두드림이 안 돌아왔다. 다들 심장이 내려앉았다.<br><br>달려가 보니 넷째는 자고 있었다. 돌을 쥔 채. 지쳐서 점호를 놓친 것이다.<br>안도 반, 식은땀 반. 다만 그 소동에 야영지 위치가 새 나갔을지 모른다. 새벽길을 당겨 떠났다. 점호는 깨어 있는 사람 수만 센다는 걸 배웠다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 점호 대신 한 줄에 다섯 손을 올리게 한다.', k:'fix', dc:23,
      ok:`끈 하나를 다섯 사이에 걸었다. 자는 동안도 손목에 감고.<br><br>수를 묻는 대신 무게를 느끼게 했다. 다섯 손목의 당김이 다 있으면 다섯이 다 있는 것이다.<br>두드림조차 없는 밤이 됐다. 제일 조용한 점호는 끈 한 줄이었다.`,
      ng:`밤중에 끈이 돌 모서리에 쓸려 끊겼다. 아무도 몰랐다.<br><br>새벽에 끈 끝이 빈 채 바닥에 늘어져 있는 걸 보고 모두 벌떡 일어났다. 다행히 다섯이 다 있었다. 끈만 죽었다.<br>모르는 채 지나간 밤이 제일 무섭다. 끈 점호에 두드림 점호를 겹치기로 했다. 신호는 겹으로 짜야 그물이 된다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-17, spirit:-19 } }
  ] },

{ at:'S', t:'뒤쫓는 것을 위한 신호',
  x:`따라붙은 것이 이쪽 흔적을 읽으며 온다. 긁힌 벽, 디딘 자국, 떨어뜨린 부스러기.<br><br>
    흔적을 지우는 데는 한계가 있다. 다섯 사람이 지나가며 아무것도 안 남길 수는 없다.<br>
    그렇다면 반대로 간다. 저쪽도 읽는 쪽이라면, 저쪽을 위해 써 주면 된다.<br><br>
    신호는 아군에게만 보내라고 배웠다. 그 가르침을 오늘 어긴다.`,
  o:[
    { l:'① 가짜 흔적의 길을 깔아 준다 — 읽는 놈을 위해 정성껏.', k:'bond', dc:24, wake:1,
      ok:`갈림길에서 왼쪽에 정성을 들였다. 디딘 자국 다섯 벌, 벽의 긁힘, 부스러기 한 줌. 지친 대열이 지나간 꼴로.<br><br>그리고 오른쪽으로는 돌 위만 밟아 지났다.<br>따라붙은 것이 왼쪽을 읽으며 멀어지는 기척을 들었다. 공들여 쓴 글은 공들여 읽힌다.<br><br>신호가 꼭 아군에게만 가는 게 아니라는 것. 읽는 모든 눈이 수신자라는 것. 신호수의 과녁이 두 배로 넓어졌다.`,
      ng:`가짜 자국을 밟아 만드는데 다섯 벌째에서 발 크기가 들쭉났쭉해졌다.<br><br>읽는 놈이 갈림길에서 오래 멈췄다. 글이 어색한 것이다.<br>결국 양쪽 다 의심한 놈이 수를 바꿨다. 갈림길에 눌러앉은 것이다. 돌아갈 길이 막혔다. 크게 우회하느라 밤길을 더 걸었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-20 } },
    { l:'② 아무것도 쓰지 않는다 — 흔적만 지우며 돌 위로 간다.', k:'hide', dc:24,
      ok:`맨 뒤에서 걸레와 손으로 다섯의 흔적을 지웠다. 디딘 자국은 쓸고, 부스러기는 줍고.<br><br>읽을 것이 끊긴 자리에서 따라붙은 것이 오래 코를 박고 있었다.<br>백지는 가짜 글보다 안전하다. 다만 품이 세 배 든다. 그 품을 오늘은 치를 수 있었다. 늘 치를 수 있는 건 아니다.`,
      ng:`지우며 가는 속도가 대열을 못 따라갔다. 간격이 벌어졌다.<br><br>간격 사이로 따라붙은 것이 코를 들이밀었다. 지우개와 책 사이에 끼인 꼴이다.<br>지우기를 포기하고 달려 합류했다. 그날 흔적은 고스란히 남았다. 반쯤 지운 글이 제일 수상한 글이라는 것만 남기고.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'S', t:'사흘 된 조난 신호',
  x:`벽 너머에서 구조 요청 두드림이 돈다. 셋-셋-셋. 만국 공통의 박자.<br><br>
    다만 돌고 있다. 같은 간격, 같은 세기로, 듣는 내내 한 번도 안 흐트러지고.<br>
    사람의 셋-셋-셋은 사흘이면 팔이 꺾인다. 꺾인 팔은 박자가 는다.<br><br>
    이건 꺾이지 않은 팔이다. 사람 팔이 아니거나, 이제는 아니거나.`,
  o:[
    { l:'① 신호 자리로 응답하러 간다.', k:'bond', dc:25,
      doom:{ title:'셋-셋-셋', what:'조난 신호 쪽 어둠으로 끌려갑니다', dc:19, sec:42,
        text:`벽을 돌아 신호 자리로 갔다. 무너진 방 안, 돌을 쥔 손이 벽을 치고 있었다.<br><br>손만. 팔꿈치부터는 어둠에 잠겨 보이지 않았다. 그리고 그 어둠이 숨을 쉬고 있었다.<br><br>조난자는 오래전에 끝났다. 신호만 계속 치게 한 것이다. 미끼 손이 이쪽 소매를 쥐고, 어둠이 당긴다. 셋-셋-셋 박자에 맞춰서.`,
        dieText:`두드림은 그 뒤로도 돈다. 셋-셋-셋.<br><br>요즘은 가끔 넷-쉬고-하나도 섞여 돈다. 이쪽 팀 확인 신호다.<br>수첩을 통째로 읽힌 셈이다. 남은 팀은 신호를 전부 새로 짰다. 짜면서 아무도 말을 안 했다.` },
      ok:`혼자 안 갔다. 둘을 벽 모퉁이에 세우고, 불을 등지고, 물러날 길을 눈으로 재 두고 들어갔다.<br><br>무너진 방 안에 조난자가 있었다. 진짜였다. 다리가 깔린 채 사흘, 돌 쥔 손만 기계처럼 치고 있었다. 박자가 안 흐트러진 건 정신이 먼저 꺾여서였다.<br>들보를 괴어 빼냈다. 업혀 나오면서도 그 손은 허공에 셋-셋-셋을 쳤다. 손에서 돌을 빼 주는데 한참 걸렸다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 응답만 보내고 자리는 지켜본다.', k:'sense', dc:24,
      ok:`멀찍이서 응답 두드림을 보냈다. 들었다, 기다려라.<br><br>셋-셋-셋이 뚝 멎었다. 그리고 다시 시작됐다. 오십 걸음 더 가까운 벽에서.<br>조난자는 벽을 타고 움직이지 못한다. 움직이는 조난 신호는 조난이 아니라 낚시다. 답을 아꼈으면 몸도 아낀 것이다. 조용히 물러났다.`,
      ng:`응답을 보내고 너무 오래 지켜봤다. 신호가 멎은 침묵이 길어졌다.<br><br>침묵 속에서 저쪽도 이쪽을 지켜보고 있었다. 들키지 않았다고 믿은 건 이쪽뿐이었다.<br>물러나는 길목의 부스러기가 밟혀 있었다. 올 때는 없던 자국이다. 서로 구경한 밤이었다. 소름은 나중에 한꺼번에 돋았다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-19, spirit:-22 } }
  ] },

{ at:'S', t:'소리 지도',
  x:`갈림길이 넷. 지도는 여기부터 백지다.<br><br>
    눈은 어둠에 막히지만 귀는 안 막힌다. 소리는 부딪히고 돌아와 길의 꼴을 말해 준다.<br>
    막힌 길은 울림이 짧고, 뚫린 길은 길고, 물이 있으면 젖은 소리가 난다.<br><br>
    다만 이쪽이 듣는 소리는 남들도 듣는다. 그 값까지 셈에 넣고 쳐야 한다.`,
  o:[
    { l:'① 박수 한 번 — 울림으로 네 길을 한꺼번에 그린다.', k:'sense', dc:25,
      ok:`손바닥을 한 번 마주쳤다. 울림이 네 갈래로 달려 나갔다 돌아왔다.<br><br>첫째 길은 세 걸음 만에 끊겼다. 둘째는 길게 울렸고, 셋째는 젖은 소리, 넷째는 울림이 안 돌아왔다.<br>안 돌아오는 길은 무엇이 소리를 먹은 길이다. 둘째로 갔다. 박수 한 번 값으로 지도 한 장. 남는 장사였다.`,
      ng:`박수 울림이 돌아오기 전에 넷째 길에서 다른 소리가 먼저 왔다. 마주 치는 박수.<br><br>한 번. 정확히 한 번.<br>지도고 뭐고 둘째 길로 뛰었다. 등 뒤에서 박수가 한 번 더 났다. 배웅인지 약속인지 모를 한 번이었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-19, spirit:-20 } },
    { l:'② 돌을 굴려 바닥의 속을 듣는다.', k:'fix', dc:24,
      ok:`주먹돌을 첫째 길로 굴렸다. 구르는 소리가 중간에 통 빈 소리로 바뀌었다. 바닥이 들떠 있다는 뜻이다.<br><br>둘째 길의 돌은 끝까지 찼다. 단단한 바닥.<br>길은 울림이 고르고 바닥이 찬 쪽이다. 돌 두 개로 함정 하나와 길 하나를 샀다.`,
      ng:`셋째 길에 굴린 돌이 중간에 멎었다. 구르다 만 게 아니라, 잡힌 소리였다.<br><br>그리고 돌이 도로 굴러 나왔다. 이쪽으로.<br>발 앞에 멎은 돌을 아무도 줍지 않았다. 둘째 길로 조용히 꺾었다. 굴린 것을 돌려주는 길은 들어가는 길이 아니다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-18, spirit:-21 } },
    { l:'③ 넷을 네 어귀에 세워 마주 두드려 재게 한다.', k:'bond', dc:24,
      ok:`넷을 갈림길 네 어귀에 세우고 차례로 두드리게 했다. 이쪽은 가운데서 네 울림을 겹쳐 들었다.<br><br>한 사람 귀로는 못 가르는 차이가 네 자리 울림을 겹치니 드러났다. 둘째 길만 울림 끝이 위로 열렸다. 오르막, 뚫린 길.<br>네 귀와 네 손이 그린 지도. 신호수의 지도는 혼자 그리는 게 아니었다.`,
      ng:`넷째 어귀에 선 팀원이 두드림 순서를 놓쳤다. 세 울림만 겹쳤다.<br><br>모자란 한 조각이 하필 핵심이었다. 반쪽 지도로 둘째 길을 골랐다.<br>반은 맞았다. 길은 뚫렸는데 중간의 물웅덩이는 지도에 없었다. 허리까지 젖어 건넜다. 모자란 신호는 모자란 만큼 몸으로 메운다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S', t:'신호수의 등불',
  x:`기름이 바닥을 보인다. 등불 하나, 반 밤 치.<br><br>
    등불은 신호수의 혀다. 혀가 반 밤 치 남은 것이다.<br>
    남은 빛을 길에 쓰면 오늘 밤이 밝고, 신호에 아끼면 내일까지 말을 할 수 있다.<br><br>
    어느 쪽이든 하나는 포기해야 한다.`,
  o:[
    { l:'① 빛은 신호에만 — 걷는 건 어둠으로 걷는다.', k:'bond', dc:24, wake:1,
      ok:`등을 껐다. 걷는 건 손과 벽과 발끝에 맡겼다. 빛은 하루 세 번, 신호에만 켰다.<br><br>어둠 속 행군은 느렸다. 그래도 신호가 살아 있으니 대열이 안 풀렸다. 켜질 때마다 다섯이 서로의 자리를 확인했다.<br>이틀째 밤, 마지막 기름 한 모금이 갈림길에서 뒤처진 둘을 불러들였다. 빛의 마지막 말로 할 말을 했다.<br><br>빛은 길이 아니라 말이라는 것. 말은 아껴야 끝까지 간다는 것. 등불 하나가 그걸 다 가르치고 꺼졌다.`,
      ng:`신호에만 쓰자니 걷는 쪽이 자꾸 상했다. 어둠 속에서 둘이 발을 접질렸다.<br><br>접질린 걸음은 느리고, 느린 걸음은 밤을 늘린다. 늘어난 밤에 기름은 더 귀해졌다.<br>혀를 아끼다 다리를 잃은 꼴이다. 다음부터는 반반으로 섞기로 했다. 신호도 걸음도 결국 같은 기름을 먹는다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 기름을 갈라 작은 등 두 개로 만든다.', k:'fix', dc:23,
      ok:`깡통을 잘라 심지 둘을 박았다. 큰 등 하나가 작은 등 둘이 됐다.<br><br>하나는 맨 앞의 발밑에, 하나는 이쪽 품에 신호용으로.<br>작은 불은 어둡지만 두 몫을 했다. 밝기를 반 내고 쓰임을 배로 받은 셈이다. 신호수의 흥정은 이런 것이다.`,
      ng:`가르다가 기름을 반 홉 쏟았다. 바닥에 밴 기름 냄새가 지워지지 않았다.<br><br>그 자리에서 서둘러 떠났다. 기름 냄새는 이 어둠에서 사람 냄새만큼 귀한 미끼다.<br>등 둘은 만들었다. 다만 둘 다 반의반 밤 치였다. 쏟은 기름이 밤마다 아까웠다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'S', t:'멈춤 신호',
  x:`신호가 많으면 급할 때 하나도 안 나온다. 급할 때 필요한 건 결국 하나다.<br><br>
    멈춰라. 지금, 그 자리에서, 숨까지.<br>
    이 하나가 반 숨 늦으면 사람이 사라진다. 이 어둠에서는.<br><br>
    오늘 밤은 이 하나만 판다. 다른 건 다 뒤로 미룬다.`,
  o:[
    { l:'① 단 하나의 멈춤 신호를 정하고 몸에 밸 때까지 돌린다.', k:'bond', dc:24, wake:1,
      ok:`혀 차는 소리 한 번. 그걸로 정했다. 밤새 돌렸다. 걷다가, 먹다가, 졸다가도 그 소리면 전원 정지.<br><br>이튿날 오후, 앞서가던 막내 발 앞에서 바닥 결이 이상했다. 혀를 찼다. 다섯이 반 숨에 섰다.<br>막내 발끝 한 뼘 앞 바닥이 꺼지며 아래로 쏟아졌다. 아래 어둠에서 받아먹으려던 것의 숨소리가 길게 아쉬워했다.<br><br>신호는 백 가지를 아는 것보다 하나가 몸에 박히는 게 깊다는 것. 신호수 십 년 치 교본이 그 반 숨에 들어 있었다.`,
      ng:`밤새 연습을 돌렸더니 다들 신경이 곤두섰다. 자다가도 혀 차는 소리에 벌떡벌떡 깼다.<br><br>새벽에는 바람이 문틈을 차는 소리에 다섯이 다 얼어붙었다. 헛신호에 몸이 먼저 반응한 것이다.<br>지친 채로 아침을 맞았다. 신호는 몸에 배야 하지만, 배는 동안 몸이 축난다. 연습에도 박자가 필요하다.`,
      win:{ exp:23, dream:3, spirit:6 }, lose:{ mind:-17, spirit:-18 } },
    { l:'② 멈춤은 신호 대신 맨 앞의 몸으로 한다.', k:'steady', dc:24,
      ok:`맨 앞에 서서 정했다. 이쪽이 서면 모두 선다. 신호도 생략. 몸이 곧 신호.<br><br>이틀을 그렇게 걸었다. 이쪽 등이 대열의 눈이 됐다.<br>단순한 건 안 틀린다. 다만 이쪽이 못 보는 것 앞에서는 아무도 못 선다는 뜻이기도 하다. 그 한계까지 포함해서 쓰는 수다.`,
      ng:`몸 신호는 보이는 동안만 신호다. 안개 낀 구간에서 등이 안 보였다.<br><br>이쪽은 섰는데 뒤의 둘이 계속 와서 등에 부딪혔다. 도미노처럼.<br>부딪힌 소리가 어둠에 울렸다. 서둘러 그 구간을 빠져나왔다. 몸 신호에도 결국 소리 신호 하나는 받쳐야 한다. 반성했다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S', t:'한 박자 늦는 메아리',
  x:`이쪽이 두드리면 저쪽이 두드린다. 한 박자 늦게, 똑같이.<br><br>
    메아리가 아니다. 메아리는 지치지 않고, 이건 점점 가까워진다.<br>
    따라 하며 오는 것이다. 박자를 배우며, 거리를 좁히며.<br><br>
    수업을 끊든가, 수업료를 받아 내든가다.`,
  o:[
    { l:'① 두드림을 뚝 끊고 전원 침묵한다.', k:'steady', dc:24,
      ok:`두드림을 끊고 다섯이 숨을 죽였다. 벽에 붙어서, 한 식경을.<br><br>저쪽은 혼자 두드리다 멎었다. 따라 할 것이 없는 흉내쟁이는 빈손이다.<br>먼 데서 제풀에 두드리는 소리가 몇 번 나다 사라졌다. 수업은 폐강됐다. 선생이 자리를 비우면 그만이다.`,
      ng:`침묵 반 식경에 막내 배에서 꼬르륵 소리가 났다.<br><br>작은 소리였다. 그런데 저쪽이 그걸 따라 했다. 꼬르륵. 소름이 돋았다.<br>위치가 잡힌 것이다. 침묵을 버리고 이동했다. 배 속 소리까지 흉내 내는 귀라는 걸 알게 된 게 그나마 수확이었다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-19, spirit:-21 } },
    { l:'② 박자를 몰아쳐 저쪽 위치를 좁힌다.', k:'bond', dc:25,
      doom:{ title:'이중주', what:'메아리의 임자에게 끌려갑니다', dc:19, sec:40,
        text:`박자를 점점 빠르게 몰았다. 저쪽이 따라오는 간격으로 거리를 잴 셈이었다.<br><br>간격이 반 박, 반의반 박으로 줄었다. 그리고 겹쳤다.<br><br>겹친 순간 등 뒤 벽이 열렸다. 박자는 저쪽도 재고 있었다. 이쪽 위치를, 더 정확하게. 두드리던 손목째 어둠이 문다. 이중주는 원래 나란히 앉아서 치는 것이다.`,
        dieText:`두드림은 그 뒤로 혼자서도 빨라졌다 느려졌다 한다.<br><br>박자를 몰아치는 버릇까지 배운 것이다. 수업료를 선생째 치렀다.<br>남은 팀은 그 구역에서 두드림 신호를 금지했다. 침묵이 교훈의 전부였다.` },
      ok:`박자를 점점 몰았다. 저쪽이 따라붙는 간격이 좁아질수록 울림의 방향이 또렷해졌다.<br><br>왼쪽 벽, 배관 뒤, 열 걸음. 위치가 잡히는 순간 두드림을 끊고 손짓했다. 팀은 반대쪽으로.<br>저쪽은 마지막 박자를 기다리며 배관 뒤에 그대로 있었다. 끝나지 않은 곡은 연주자를 붙잡아 둔다. 그 사이 다섯이 통로를 다 빠져나갔다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S', t:'마지막 한 발',
  x:`조명탄이 한 발 남았다. 쏘면 이 어둠 한 층이 대낮이 된다. 열 숨 동안.<br><br>
    열 숨이면 지형을 다 새길 수 있다. 그리고 이 층의 모든 것에게 이쪽 위치도 새겨진다.<br>
    빛은 공평하다. 그래서 비싸다.<br><br>
    쏘는 것도 수고, 안 쏘는 것도 수다. 신호수가 정할 일이다.`,
  o:[
    { l:'① 쏘지 않는다 — 가장 어두운 순간을 위해 아낀다.', k:'bond', dc:24, wake:1,
      ok:`조명탄을 도로 꽂았다. 지금은 어둡지만 길은 있다. 길이 없어지는 순간을 위해 아꼈다.<br><br>그 순간은 이틀 뒤에 왔다. 무너진 계단, 흩어진 대열, 사방에서 좁혀 오는 기척.<br>그때 쐈다. 열 숨의 대낮. 다섯이 서로를 찾고, 좁혀 오던 것들이 빛에 얼어붙은 열 숨.<br><br>마지막 신호는 보내는 때가 전부라는 것. 품 안의 조명탄이 이틀 동안 다섯의 배짱이기도 했다는 것. 안 쏜 신호도 신호였다.`,
      ng:`아낀 건 좋았는데 아낀다는 걸 이쪽만 알았다.<br><br>어두운 이틀 동안 다들 말수가 줄었다. 마지막 패가 있다는 걸 알려 주지 않은 탓이다.<br>사흘째에 품을 열어 보여 줬다. 그제야 걸음들이 펴졌다. 아끼는 패도 패를 쥔 걸 보여야 힘이 된다. 신호수가 신호를 아끼다 신뢰를 아낄 뻔했다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-19 } },
    { l:'② 갈림길 천장에 쏜다 — 열 숨에 지형을 다 새긴다.', k:'sense', dc:25,
      ok:`천장에 쐈다. 빛이 꽃처럼 열리고, 층 전체가 드러났다.<br><br>열 숨 동안 눈에 새겼다. 갈림길 넷, 무너진 다리, 물길, 그리고 멀리서 빛을 피해 접히는 큰 그림자 둘.<br>어둠이 돌아왔을 때 머릿속에 지도가 있었다. 그림자 둘의 자리까지 포함해서. 빛값은 비쌌지만 산 것이 더 많았다.`,
      ng:`쏘는 각이 낮았다. 조명탄이 천장을 맞고 꺾여 옆 통로로 굴러 들어갔다.<br><br>빛이 엉뚱한 데서 타올랐다. 지형은 반만 새겼고, 위치는 전부 새 나갔다.<br>빛이 꺼지기 전에 자리를 떴다. 등 뒤 여기저기서 기척들이 움직이기 시작했다. 마지막 한 발은 그렇게 반값에 날아갔다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'S1', t:'관제반의 불빛',
  x:`관제실 벽면에 등이 수백 개 박혀 있다. 죽은 시설인데 등은 산다. 초록, 노랑, 빨강.<br><br>
    차례가 있다. 초록 셋이 돌고, 노랑이 끼어들고, 빨강이 번쩍이고.<br>
    아무 뜻 없는 깜빡임은 없다. 시설이 저 혼자 중얼거리는 중이다. 문이 열렸다고, 전력이 샌다고, 어디서 무엇이 움직인다고.<br><br>
    읽을 줄만 알면 이 벽이 이 시설의 귀와 눈이다.`,
  o:[
    { l:'① 등이 바뀌는 차례를 끝까지 적어 문법을 깬다.', k:'gaze', dc:25, wake:1,
      ok:`반 시진을 벽 앞에 앉아 적었다. 초록이 꺼지면 노랑, 노랑 둘이면 빨강.<br><br>문법이 잡혔다. 노랑은 문, 빨강은 움직임. 구역 번호는 등의 자리.<br>그때부터 벽이 말로 들렸다. 7구역 문 열림. 4구역 움직임. 4구역을 피해 7구역으로 길을 잡았다.<br><br>깜빡이는 모든 것은 말이라는 것. 기계든 짐승이든 보내는 쪽이 있으면 읽는 쪽이 될 수 있다는 것. 신호수의 사전이 한 권 늘었다.`,
      ng:`문법을 반쯤 잡았을 때 벽의 빨강 하나가 이쪽 구역 자리에서 켜졌다.<br><br>움직임 감지. 이 방. 이쪽을 가리키는 것이다.<br>시설이 읽는 쪽이기도 하다는 걸 그제야 알았다. 그리고 이 벽을 읽는 눈이 이쪽만이 아닐 수도 있다는 것도. 적던 수첩을 덮고 관제실을 떴다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-19, spirit:-21 } },
    { l:'② 경보 계통 선만 골라 끊어 둔다.', k:'fix', dc:24,
      ok:`배선함을 열어 경보 사이렌 선만 골라 끊었다. 등은 살려 두고.<br><br>이제 시설은 중얼거리되 소리는 못 지른다. 이쪽이 어디서 무엇을 건드려도 사이렌이 이 층을 깨울 일은 없다.<br>말 못 하게 된 벽이 빨강 등만 억울하게 깜빡였다. 읽는 건 이쪽만 하면 된다.`,
      ng:`경보선인 줄 알고 끊은 게 조명 계통이었다. 복도 등이 반쯤 나갔다.<br><br>어두워진 복도는 이쪽에게도 저쪽 것들에게도 공평하게 어두웠다.<br>저쪽이 더 유리한 공평이었다. 그 층을 지나는 내내 어깨가 굳어 있었다. 가위는 확신 있을 때만 대는 것이다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'S1', t:'환풍구 속 교신',
  x:`환풍구를 한 줄로 긴다. 목소리는 금물이라 두드림으로 잇는다. 앞에서 둘, 가운데서 둘, 뒤에서 하나.<br><br>
    셋째와 넷째 사이에서 두드림이 하나 늘었다.<br>
    여섯째 두드림. 박자는 이쪽 것인데 자리가 이쪽 사람 사이다.<br><br>
    관 어딘가, 셋째와 넷째 사이 어느 가지관에 그것이 끼어 있다. 교신에 끼어든 채.`,
  o:[
    { l:'① 끼어든 자에게 정지 신호를 친다 — 저쪽 빌린 박자로.', k:'bond', dc:25,
      doom:{ title:'끼어든 자', what:'가지관 깊은 쪽으로 끌려갑니다', dc:20, sec:38,
        text:`끼어든 두드림에게 이쪽 정지 신호를 쳤다. 배운 말로 멈추라고.<br><br>저쪽이 멈췄다. 제대로 알아들은 것이다. 그게 문제였다.<br><br>알아듣는 것은 대답도 한다. 대답은 두드림이 아니라 손이었다. 가지관에서 뻗어 나온 것이 발목을 감고, 몸이 가지관 어둠으로 미끄러진다. 멈추라는 말은 저쪽 사전에서 이리 오라는 말이었는지도 모른다.`,
        dieText:`관 속의 네 사람은 두드림이 멀어지는 걸 들었다. 여섯째 두드림과 함께.<br><br>둘이 나란히, 깊은 쪽으로.<br>출구에서 넷이 모였을 때 아무도 점호를 돌리지 않았다. 돌리면 넷이라는 게 확정되니까. 밤이 깊어서야 막내가 벽에 네 번 두드렸다. 그게 장례였다.` },
      ok:`끼어든 두드림에게 정지 신호를 쳤다. 셋째와 넷째에게는 그 사이 간격을 당겨 붙이라는 신호를.<br><br>끼어든 자는 멈췄다. 배운 말이 명령인 줄 알고 따른 것이다.<br>그것이 멈춰 선 사이 다섯이 가지관 입구를 지나쳐 빠졌다. 출구에서 점호를 돌리니 다섯. 여섯째는 관 속에 두고 왔다. 아직 멈춰 있을지도 모른다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 교신을 끊고 기는 속도만 배로 올린다.', k:'evade', dc:24,
      ok:`두드림을 전부 끊었다. 신호 없이, 앞사람 발목만 보며, 배로 빠르게.<br><br>교신이 끊기자 끼어들 자리도 없어졌다. 여섯째 두드림이 혼자 몇 번 울리다 멎었다.<br>출구까지 단숨에 뺐다. 신호는 이을 때만큼 끊을 때를 아는 게 일이다. 끊는 박자는 오늘이 맞았다.`,
      ng:`신호 없이 서두르다 가운데 둘이 가지관 갈림에서 길을 갈렸다.<br><br>한 줄이 두 줄이 된 걸 출구에서야 알았다. 둘이 돌아 나오는 데 한 식경이 걸렸다.<br>그 한 식경 동안 가지관 쪽에서 두드림이 들렸다고, 돌아온 둘이 말했다. 이쪽 박자로, 다정하게. 둘은 대답하지 않았다. 그게 살렸다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-19, spirit:-21 } }
  ] },

{ at:'S1', t:'경보 스위치',
  x:`비상 경보 스위치 앞이다. 당기면 사이렌이 울고 격벽이 내려온다. 층 전체에.<br><br>
    쫓아오는 그것을 격벽 너머에 가둘 수 있다. 각이 맞으면.<br>
    각이 틀리면 이쪽이 갈라진다. 다섯이 격벽 양쪽에 둘과 셋으로.<br><br>
    당기는 건 한 번이고, 무르기는 없다. 신호수 손에 층 하나의 문들이 다 걸려 있다.`,
  o:[
    { l:'① 반 층의 시차를 재서 당긴다 — 갇히는 쪽이 그것이 되게.', k:'bond', dc:26,
      ok:`격벽 위치를 외우고, 그것의 걸음과 이쪽 걸음을 쟀다. 다섯이 7번 격벽을 넘는 순간 그것은 5번과 6번 사이.<br><br>그 순간에 당겼다. 사이렌이 울고 격벽들이 떨어졌다.<br>5번과 6번 사이에서 쇠를 두드리는 소리가 오래 났다. 이쪽 다섯은 전부 7번 안쪽. 신호수의 일이란 결국 때를 재는 일이다. 쇠문 세 겹이 그 증명이었다.`,
      ng:`그것의 걸음이 셈보다 빨랐다. 당기는 순간 그것은 이미 6번을 넘고 있었다.<br><br>격벽이 그것 꼬리 쪽에서 닫혔다. 같은 칸에 갇힌 것이다. 이쪽 다섯과.<br>7번 격벽의 수동 손잡이를 넷이 매달려 올리는 동안 하나가 등불을 흔들어 시간을 벌었다. 반 뼘 틈으로 다 기어 나왔다. 사이렌은 그 뒤로도 한참 울었다. 비웃음처럼.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-29, mind:-17 } },
    { l:'② 당기지 않는다 — 격벽은 양날이다.', k:'steady', dc:24,
      ok:`손을 뗐다. 한 번뿐인 패는 확신 없이 안 쓴다.<br><br>대신 걸음을 재촉해 거리만 벌렸다. 그것은 따라오다 다른 기척에 꺾여 사라졌다.<br>스위치는 지도에 적어 뒀다. 위치와 격벽 번호까지. 안 쓴 패는 사라진 패가 아니라 쟁여 둔 패다. 다음 팀 몫일 수도 있고.`,
      ng:`손을 뗀 직후 그것이 속도를 올렸다. 벌린 거리가 반으로 줄었다.<br><br>스위치로 돌아가기엔 늦었다. 달리는 수밖에 없었다.<br>두 층을 내리 달려 따돌렸다. 숨이 돌아온 뒤에 생각했다. 패를 아낀 게 아니라 못 쓴 것 아닌가. 그 경계는 결과만 안다. 오늘은 살았으니 아낀 걸로 친다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-27, spirit:-16 } },
    { l:'③ 경보 대신 스피커 한 줄만 살려 다른 구역에 소리를 흘린다.', k:'fix', dc:25,
      ok:`배선함에서 동쪽 구역 스피커 선만 살렸다. 그리고 마이크에 돌 긁는 소리를 흘렸다.<br><br>동쪽 복도에서 사람 아닌 소리가 울리자, 쫓던 그것이 멈칫하더니 그쪽으로 꺾었다.<br>사이렌 없이, 격벽 없이, 선 한 줄로 길을 비웠다. 큰 패를 아끼고 잔패로 먹은 판. 신호수의 판은 이래야 한다.`,
      ng:`살린다는 선이 전 구역 스피커였다. 돌 긁는 소리가 층 전체에 울렸다.<br><br>쫓던 것만이 아니라 층의 모든 것이 깼다. 사방에서 기척이 일었다.<br>마이크를 뽑고 달렸다. 방송 사고치고는 참혹한 청취율이었다. 다음부터 선은 두 번 확인하기로 했다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-19, spirit:-22 } }
  ] },

{ at:'S1', t:'여왕의 박자',
  x:`시설의 웅웅거림이 어느 순간부터 다르게 들린다. 기계음이 아니다. 박자가 있다.<br><br>
    길게, 길게, 짧게. 배관을 타고 층 전체에 도는 맥.<br>
    그 박자에 맞춰 벽 속 것들이 움직인다. 긴 박에 기고, 짧은 박에 멎고.<br><br>
    가장 깊은 방에서 누가 온 시설에 북을 치고 있는 것이다. 제 식구들에게.`,
  o:[
    { l:'① 박자의 사이 — 엇박에만 움직인다.', k:'bond', dc:26, wake:1,
      ok:`박을 셌다. 길게, 길게, 짧게, 그리고 반 박의 빈틈.<br><br>그 빈틈에만 걸음을 옮겼다. 벽 속 것들이 기는 박에는 이쪽도 멎고, 멎는 박의 틈에 이쪽이 걸었다.<br>식구들 발소리에 이쪽 발소리가 묻혔다. 북 치는 쪽은 끝까지 몰랐다. 제 북소리 틈에 다섯이 끼어 지나간 것을.<br><br>어느 둥지든 지휘자가 있고, 지휘자의 박자에는 반드시 쉼표가 있다는 것. 쉼표로 걷는 법을 배웠다.`,
      ng:`엇박을 타다 긴 박 하나를 잘못 셌다. 벽 속 것들이 멎은 박에 이쪽 발소리만 났다.<br><br>박자가 뚝 끊겼다. 온 시설이 숨을 멈춘 것 같은 침묵.<br>그리고 박자가 배로 빨라졌다. 수색의 박자다. 반 층을 뛰어 배관 없는 구역으로 숨었다. 박자가 제 속도로 돌아오는 데 한 시진이 걸렸다. 그동안 아무도 숨을 크게 못 쉬었다.`,
      win:{ exp:25, dream:4 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 배관을 두드려 가짜 박자를 섞는다.', k:'luck', dc:26,
      ok:`배관 이음새에 돌을 대고 북소리를 반 박 어긋나게 섞었다.<br><br>벽 속 것들이 엉켰다. 어느 박을 따를지 몰라 기다 멎다를 반복했다.<br>지휘자의 박자가 멎고 다시 고르는 사이, 혼란해진 복도를 가로질렀다. 남의 악단에 소음 하나 끼얹은 값으로 길 하나를 샀다. 연주자들에게는 미안하게 됐다.`,
      ng:`가짜 박이 세 번 만에 들통났다. 북소리가 멎고, 배관이 이쪽 두드림만 메아리로 돌려줬다.<br><br>어디서 두드리는지 찾는 메아리였다.<br>돌을 버리고 배관에서 떨어졌다. 그날 밤 내내 북소리가 이 구역에서만 유난히 크게 돌았다. 화난 박자였다. 남의 북엔 손대는 게 아니다.`,
      win:{ exp:16, dream:3 }, lose:{ mind:-21, spirit:-25 } }
  ] },

{ at:'S1', t:'단지 속의 구조 신호',
  x:`표본 선반 사이를 지나는데 두드림이 났다. 유리 안쪽에서.<br><br>
    셋-셋-셋. 구조 요청. 연구원들에게 배운 것이다. 이 방에서 오래 들었을 테니까.<br>
    단지 속 웅크린 것이 두드리고 있다. 느리게, 공들여서, 사람의 박자로.<br><br>
    배운 말로 부르고 있다. 따뜻한 손을.`,
  o:[
    { l:'① 응답하지 않고 패턴만 기록한다.', k:'steady', dc:24,
      ok:`걸음을 늦추지 않고 지나며 귀로만 적었다. 셋-셋-셋, 쉼, 셋-셋-셋.<br><br>이것들이 사람의 신호를 배운다는 것. 그 사실 하나를 수첩에 적었다. 다음 팀들을 위해 크게, 두 번 밑줄 치고.<br>선반을 벗어날 때까지 두드림이 점점 빨라졌다. 무시당하는 걸 아는 속도였다. 그 속도까지 적었다.`,
      ng:`기록하며 지나는데 막내가 걸음을 멈췄다. 사람이 갇힌 걸 수도 있지 않느냐고.<br><br>아니라고 말할 근거를 대는 데 한참 걸렸다. 그 한참 동안 두드림이 애절해졌다. 듣는 쪽을 재는 애절함이었다.<br>막내를 끌다시피 데리고 나왔다. 복도에서 막내가 한참 울었다. 그 울음까지 저 유리 안쪽이 들었을 것이다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-20, spirit:-23 } },
    { l:'② 유리에 손을 대고 마주 두드린다.', k:'bond', dc:25,
      doom:{ title:'배운 말', what:'단지 쪽으로 끌려갑니다', dc:19, sec:40,
        text:`유리에 손바닥을 대고 마주 두드렸다. 들었다, 누구냐.<br><br>대답 대신 유리 안쪽에 손바닥이 마주 붙었다. 사람 손 비슷한, 사람 손 아닌 것이.<br><br>유리는 진작 금이 가 있었다. 금 사이로 가는 것들이 뿜어져 나와 손목을 감는다. 구조 신호는 신호가 아니라 그물이었다. 따뜻한 손이 걸렸다.`,
        dieText:`단지는 깨진 채 비어 있었다. 두드리던 것도, 두드림에 답한 사람도 없었다.<br><br>선반 안쪽 어둠으로 끌린 자국만 길게 남았다.<br>그 방의 다른 단지들이 일제히 두드리기 시작한 것은 남은 넷이 문을 나설 때였다. 셋-셋-셋. 배운 말이 방 전체에 퍼져 있었다.` },
      ok:`유리에 손을 대지는 않았다. 한 걸음 떨어져 바닥을 두드렸다. 들었다. 그러나 안 연다.<br><br>안쪽 두드림이 멎었다. 서로의 패를 확인한 침묵.<br>안쪽 것이 다시 두드리기 시작했을 때 박자가 달라져 있었다. 구조 요청이 아니라 그냥 두드림. 연기를 걷은 것이다. 연기인 걸 서로 알면 그건 더는 미끼가 아니다. 등을 보이고 나왔다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S1', t:'증기 속 유도',
  x:`파이프가 터져 복도가 증기로 찼다. 한 치 앞이 안 보인다.<br><br>
    증기 너머 바닥은 검은 피가 지나가 군데군데 녹아 있다. 헛디디면 아래층이다.<br>
    보이지 않는 길을 다섯이 건너야 한다. 눈 대신 쓸 것은 소리와 줄.<br><br>
    신호수가 눈이 되는 시간이다.`,
  o:[
    { l:'① 혀 차는 소리와 줄 당김만으로 하나씩 건넨다.', k:'bond', dc:25,
      ok:`먼저 바닥을 더듬어 건너가 줄을 맸다. 그리고 증기 저쪽에 소리를 보냈다. 혀 한 번 — 한 걸음. 두 번 — 멈춤. 당김 — 방향.<br><br>한 사람씩, 눈 감은 걸음을 소리로 끌었다. 녹은 자리 앞에서는 두 번, 꺾는 데서는 당김.<br>넷이 다 건넜다. 증기 속에서 다섯이 한 줄의 소리로 꿰어진 반각이었다. 신호수 평생에 이보다 귀가 선 반각은 없을 것이다.`,
      ng:`셋째를 건네는데 증기 속에서 다른 소리가 섞였다. 혀 차는 소리. 이쪽 것이 아닌.<br><br>셋째가 그 소리 쪽으로 반 걸음 틀었다. 녹은 자리 쪽으로.<br>줄을 힘껏 당겨 넘어뜨렸다. 녹은 테두리 한 뼘 앞이었다. 소리를 배우는 것이 증기 속에 같이 있었다. 남은 둘은 줄만 당겨서 건넸다. 소리는 접었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-27, mind:-16 } },
    { l:'② 증기가 옅어지는 결을 기다려 틈틈이 보낸다.', k:'sense', dc:24,
      ok:`증기에도 숨이 있다. 파이프가 뿜고, 멎고, 또 뿜고.<br><br>멎는 틈마다 바닥이 열 숨쯤 비쳤다. 그 열 숨에 한 사람씩 보냈다.<br>다섯 틈에 다섯이 건넜다. 서두르지 않는 게 제일 빠른 길인 날이 있다. 증기의 박자를 읽은 날이 그렇다.`,
      ng:`네 번째 틈이 오지 않았다. 파이프가 아예 터진 것이다. 증기가 벽처럼 섰다.<br><br>남은 둘은 틈 없이 건너야 했다. 기다시피, 바닥을 두드려 가며.<br>하나가 녹은 테두리에 장갑 끝을 댔다. 장갑이 연기를 물었다. 손은 뺐다. 장갑만 바쳤다. 증기의 박자도 결국 기계의 박자라 기계처럼 고장 난다. 그것까지 셈에 넣었어야 했다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S1', t:'전원 복구 — 모든 등이 켜질 때',
  x:`배전반의 주 차단기가 손에 잡힌다. 올리면 이 층 전체에 불이 들어온다.<br><br>
    지도가 생긴다. 한눈에. 그리고 이쪽도 한눈에 드러난다. 층의 모든 것에게.<br>
    빛은 양쪽으로 베는 칼이다. 쥐는 법이 전부다.<br><br>
    손잡이에 손을 얹고 셈을 시작했다.`,
  o:[
    { l:'① 삼 초만 켠다 — 다섯 눈이 다섯 구역을 나눠 찍는다.', k:'bond', dc:25,
      ok:`켜기 전에 나눴다. 하나는 왼쪽 복도, 하나는 오른쪽, 하나는 천장, 하나는 바닥, 이쪽은 가장 먼 문.<br><br>올리고, 하나 둘 셋, 내렸다.<br>어둠이 돌아온 뒤 다섯이 본 것을 모았다. 지도 한 장이 나왔다. 천장 담당이 덧붙였다. 배관 위에 긴 것이 엎드려 있더라고. 그 길만 피하면 된다. 삼 초짜리 지도치고는 자세했다.`,
      ng:`삼 초가 길었다. 끄는 손이 반 박자 늦었다.<br><br>그 반 박자에 배관 위의 긴 것이 이쪽 다섯을 다 셌다. 눈이 마주친 담당자 말로는, 세는 눈이었다고 했다.<br>지도는 얻었다. 다만 저쪽도 지도를 얻었다. 서로의 패를 깐 판은 걸음이 빠른 쪽이 이긴다. 바로 떴다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 불을 켠 채 빛에 몰리는 것들을 본다.', k:'gaze', dc:26,
      ok:`올리고 껐다 켜기를 반복하며 벽 뒤에서 지켜봤다. 빛이 돌아올 때마다 복도의 것들이 어디로 숨는지.<br><br>버릇이 보였다. 전부 바닥 배수구와 천장 배관으로. 벽의 허리 높이는 비어 있었다.<br>허리 높이로만 다니면 된다는 뜻이다. 빛으로 어둠의 버릇을 읽었다. 위험한 독서였지만 책이 좋았다.`,
      ng:`두 번째로 켰을 때 복도의 것 하나가 숨지 않았다. 빛 한가운데 서서 이쪽 배전반을 보고 있었다.<br><br>빛을 안 무서워하는 개체도 있는 것이다. 표본에서 나온 것들이 다 같지는 않으니까.<br>차단기를 내리고 어둠 속을 소리 없이 빠졌다. 그것이 배전반 앞까지 와서 차단기를 더듬는 소리를 등 뒤로 들었다. 배우는 중이었다.`,
      win:{ exp:16, dream:3 }, lose:{ mind:-21, spirit:-24 } },
    { l:'③ 복구하지 않는다 — 어둠에 익은 눈을 지킨다.', k:'steady', dc:23,
      ok:`손잡이에서 손을 뗐다. 사흘 동안 어둠에 적신 눈은 그 자체가 장비다. 한 번의 빛이 그걸 다 씻어 간다.<br><br>익은 눈으로 걸었다. 벽의 결, 바닥의 턱, 공기의 흐름.<br>층을 다 지날 때까지 불 없이 갔다. 지도는 발바닥에 새겨졌다. 눈부신 지도보다 느리지만, 뺏기지 않는 지도다.`,
      ng:`어둠에 익은 눈에도 못 보는 건 있다. 투명한 것. 유리문에 정통으로 부딪혔다.<br><br>소리가 복도를 울렸고, 코피가 터졌다.<br>뒤따르던 팀원들이 번갈아 유리를 더듬어 문고리를 찾았다. 익은 눈의 맹점까지가 익은 눈이다. 코가 그걸 가르쳐 줬다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'S2', t:'무리의 말',
  x:`풀숲 너머에서 그것들이 운다. 밤새 세 가지 울음이 오간다.<br><br>
    짧고 높은 것. 길게 끄는 것. 그리고 뚝뚝 끊어지는 낮은 것.<br>
    울음이 오가고 나면 꼭 무슨 일이 난다. 울음은 저들의 신호다. 신호라면 이쪽 일이다.<br><br>
    사흘 치 밤을 들으면 사전이 만들어진다.`,
  o:[
    { l:'① 울음 셋을 가른다 — 찾는 소리, 모는 소리, 끝내는 소리.', k:'bond', dc:25, wake:1,
      ok:`사흘 밤을 적었다. 짧고 높은 건 찾았다는 소리. 길게 끄는 건 몰이 시작. 낮게 끊어지는 건 끝.<br><br>나흘째 낮, 길게 끄는 울음이 이쪽 뒤에서 났다. 몰이 시작. 모는 방향은 울음의 반대쪽이다.<br>그래서 움직이지 않았다. 몰리는 대신 바위에 등을 붙이고 섰다. 몰이는 뛰는 먹이를 모는 기술이다. 안 뛰는 먹이 앞에서 몰이꾼들이 어색하게 서성이다 흩어졌다.<br><br>적의 신호도 신호라는 것. 신호수의 귀는 진영을 가리지 않는다는 것. 사전이 한 권 또 늘었다.`,
      ng:`사흘 치 사전이 나흘째에 틀렸다. 찾는 소리인 줄 안 울음이 몰이 소리였다.<br><br>울음 반대쪽으로 피한다는 게 몰이 길 한가운데로 들어간 꼴이 됐다.<br>덤불을 뚫고 바위 지대로 구르다시피 빠졌다. 사전은 틀린 장을 찢고 다시 적었다. 남의 말은 목숨 걸고 배우는 말이다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 울음이 들리는 동안만 걷는다 — 바람 아래쪽으로.', k:'sense', dc:24,
      ok:`울음이 나는 동안은 저들이 말하는 중이다. 말하는 입은 사냥하지 않는다.<br><br>울음이 오갈 때만 걷고, 멎으면 같이 멎었다. 바람은 늘 등 뒤에서 맞았다. 냄새가 앞서가지 않게.<br>반나절을 그렇게 저들의 대화 틈새로 걸었다. 말 많은 무리라 틈도 많았다.`,
      ng:`울음이 뚝 멎었다. 말이 끝난 게 아니라 이쪽 냄새를 문 침묵이었다.<br><br>바람이 바뀐 걸 늦게 알았다. 냄새가 먼저 가서 소개를 끝낸 뒤였다.<br>남은 거리를 전력으로 뛰었다. 등 뒤 풀숲이 세 갈래로 갈라지며 따라왔다. 물가로 꺾어서야 떨어졌다. 바람은 신호수의 또 다른 상관이다. 모시는 걸 잊으면 이렇게 된다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-29, mind:-15 } }
  ] },

{ at:'S2', t:'물낯 신호',
  x:`물에 잠긴 고사리 밭 건너편에 먼저 건넌 둘이 있다. 소리는 금물이다. 물의 주인이 소리를 센다.<br><br>
    남은 신호는 물낯뿐이다. 물결은 소리 없이 멀리 간다.<br>
    다만 물결은 주인의 글자이기도 하다. 너무 큰 물결은 주인을 부른다.<br><br>
    돌의 크기가 전부다.`,
  o:[
    { l:'① 조약돌 하나 — 물결 고리 수로 말을 보낸다.', k:'bond', dc:24,
      ok:`새끼손톱만 한 조약돌을 골랐다. 하나 — 기다려라. 둘 — 상류로. 셋 — 지금 건넌다.<br><br>고리가 소리 없이 퍼져 건너편에 닿았다. 둘이 알아듣고 상류 쪽 얕은 목으로 움직였다.<br>주인의 수면은 끝까지 고요했다. 조약돌의 고리는 주인에게는 벌레 한 마리, 이쪽에게는 문장 하나였다. 크기를 아는 것이 신호수다.`,
      ng:`세 번째 돌이 손에서 미끄러져 큰 놈이 들어갔다. 퐁당 소리와 함께 굵은 고리가 퍼졌다.<br><br>먼 수면이 둥글게 울기 시작했다. 주인이 글자를 읽으러 오는 것이다.<br>건너편 둘에게 급히 돌 둘을 던지고 — 상류로 — 이쪽도 물가에서 물러났다. 주인은 빈 물낯을 한참 맴돌았다. 오자 하나가 하마터면 문장 전체를 잡아먹을 뻔했다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 등불을 물낯에 비껴 비춰 건너편 벽에 띄운다.', k:'fix', dc:24,
      ok:`등불을 수면에 낮게 비꼈다. 빛이 물낯을 타고 꺾여 건너편 바위벽에 흐린 점으로 맺혔다.<br><br>점을 길게, 짧게. 둘이 벽의 점을 읽었다.<br>빛은 물 위를 지나갔을 뿐 물을 건드리지 않았다. 주인의 글자는 물결이지 빛이 아니다. 남의 종이는 안 쓰고 보낸 편지였다.`,
      ng:`수면에 비낀 빛이 물고기 떼를 깨웠다. 잔 물결이 사방에서 일었다.<br><br>잔 물결들이 모여 주인의 주의를 끌었다. 수면이 한 번 크게 숨 쉬었다.<br>등을 끄고 엎드렸다. 건너편 둘도 벽의 점이 꺼진 걸 신호로 알아서 엎드렸다. 그건 약속 안 한 신호였는데 통했다. 급하면 어둠도 글자가 된다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-17, spirit:-19 } }
  ] },

{ at:'S2', t:'정원의 종 — 작은 것들의 침묵',
  x:`이 정원에는 작은 소리가 깔려 있다. 풀벌레, 잔 새, 물가의 개구리 비슷한 것들.<br><br>
    그 소리가 걷히는 쪽이 있다. 걷힌 자리는 반드시 큰 것이 지나간다.<br>
    정원 전체가 경보망이다. 작은 것들이 종지기다.<br><br>
    종소리를 들을 귀만 있으면 된다.`,
  o:[
    { l:'① 작은 소리의 지도를 팀 전체에게 가르친다.', k:'bond', dc:24, wake:1,
      ok:`걸으며 가르쳤다. 풀벌레가 멎으면 서라. 잔 새가 뜨면 낮춰라. 물가 것들이 조용하면 물에서 떨어져라.<br><br>이튿날 고사리 밭의 벌레 소리가 파도 걷히듯 멎었다. 다섯이 배운 대로 일제히 엎드렸다.<br>큰 것이 열 걸음 밖을 지나갔다. 땅이 두 번 울렸다. 소리가 돌아오고서야 일어났다.<br><br>정원 전체가 신호망이라는 것. 신호수의 일은 망을 치는 것만이 아니라 쳐진 망을 읽는 것이라는 것. 귀가 다섯 배로 늘었다.`,
      ng:`가르치는 데 반나절을 썼는데 막내가 잔 새와 풀벌레를 자꾸 헷갈렸다.<br><br>새가 떴는데 선 채로 두리번댄 것이다. 마침 지나던 몰이꾼 하나와 눈이 마주쳤다.<br>다행히 저쪽도 혼자라 물러났다. 복습을 다시 돌렸다. 신호는 가르친 걸로 끝이 아니라 몸에 밸 때까지가 수업이다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-19 } },
    { l:'② 약속 하나만 박는다 — 침묵이 오면 무조건 엎드린다.', k:'steady', dc:23,
      ok:`지도까지는 사치다. 규칙 하나만 박았다. 주위가 조용해지면 묻지도 말고 엎드려라.<br><br>단순한 규칙은 급할 때 안 깨진다. 사흘 동안 네 번 엎드렸다. 두 번은 헛것이었고 두 번은 진짜였다.<br>헛 엎드림 두 번은 보험료다. 진짜 두 번에 비하면 공짜나 다름없다.`,
      ng:`네 번째 침묵에서 막내가 묻고 엎드렸다. 왜요, 한마디.<br><br>그 한마디가 침묵 속에 또렷했다. 걷힌 소리 한가운데서.<br>지나가던 큰 것이 멈칫했다. 다들 숨을 끊고 백을 셌다. 큰 것은 다시 걸었다. 그날 밤 막내는 자진해서 침묵 연습을 했다. 가르침은 때로 간담이 대신 한다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-18, spirit:-21 } }
  ] },

{ at:'S2', t:'빌린 울음',
  x:`무리가 길목을 깔고 앉았다. 돌아갈 길은 물이고, 기다릴 시간은 없다.<br><br>
    사흘 들은 저들의 말이 혀끝에 있다. 몰이 울음. 길게 끌다 두 번 꺾는 소리.<br>
    저들의 말로 저들을 움직인다. 신호수가 할 수 있는 제일 위험한 장난이다.<br><br>
    억양 하나가 어긋나면, 저들은 틀린 말을 고치러 온다.`,
  o:[
    { l:'① 몰이 울음을 흉내 내 무리를 비탈 쪽으로 민다.', k:'bond', dc:26,
      ok:`숨을 고르고 길게 끌다 두 번 꺾었다. 사흘 치 귀가 혀로 옮겨 가는 순간이었다.<br><br>길목의 무리가 일제히 일어났다. 비탈 쪽에서 몰이가 시작된 줄 알고 제 자리를 잡으러 움직였다.<br>빈 길목을 다섯이 지났다. 등 뒤에서 무리가 오지 않는 몰이를 한참 기다리는 기척이 났다. 남의 말을 빌리면 이자가 무섭지만, 오늘 원금은 두둑했다.`,
      ng:`두 번 꺾는 끝이 반 음 높았다. 사람 목은 결국 사람 목이다.<br><br>무리가 일어나다 말고 일제히 이쪽 방향을 봤다. 틀린 말을 한 입을 찾는 눈으로.<br>길목이고 뭐고 물가로 뛰었다. 허리까지 적시고 바위를 타고서야 떨어졌다. 남의 말은 완벽하지 않으면 안 꺼내는 것이다. 혀가 며칠 조용했다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-29, mind:-17 } },
    { l:'② 끝내는 소리를 흉내 내 사냥 자체를 접게 한다.', k:'luck', dc:26,
      doom:{ title:'틀린 억양', what:'무리에게 끌려갑니다', dc:20, sec:36,
        text:`끝내는 소리를 냈다. 낮게, 뚝뚝 끊어서. 사냥 끝, 다들 돌아가라.<br><br>무리가 멎었다. 그리고 아무도 안 돌아갔다. 끝내는 소리는 장이 낸다. 장의 목소리가 아니었던 것이다.<br><br>가짜 장을 찾는 데는 오래 걸리지 않았다. 풀이 사방에서 좁혀 오고, 소리 낸 입부터 문다. 끌려가는 동안에도 무리는 조용했다. 사냥 끝 소리는 이미 났으니까.`,
        dieText:`남은 넷은 물가 바위에서 그 밤을 샜다.<br><br>새벽에 무리의 울음이 바뀌어 있었다. 끝내는 소리에 꺾임이 하나 늘었다. 가짜를 거르는 꺾임일 것이다.<br>저들도 신호를 고친다. 신호수가 마지막으로 가르친 것이 하필 그것이었다.` },
      ok:`끝내는 소리를 냈다. 장이 내는 낮은 소리, 사흘 중 두 번밖에 못 들은 그 소리를.<br><br>무리가 하나둘 길목에서 일어나 풀숲으로 걷어 들어갔다. 오늘 사냥은 끝났다는 걸음으로.<br>다 사라진 길목을 숨도 못 쉬고 지났다. 다시는 안 할 짓이다. 두 번 들은 말로 왕 노릇을 했다. 세 번째 들을 일이 없기를 빌면서 걸었다.`,
      win:{ exp:25, dream:4 } }
  ] },

{ at:'S2', t:'승강기 종',
  x:`승강장 기둥에 종이 달려 있다. 낡은 안내판 — 승강기 호출은 타종.<br><br>
    치면 위에서 승강기가 내려온다. 그리고 종소리는 정원 끝까지 간다. 모두에게.<br>
    호출 신호와 만찬 종이 같은 종인 셈이다.<br><br>
    치는 법을 바꿀 수 있다면 얘기가 달라진다.`,
  o:[
    { l:'① 종 틀을 천으로 감아 반만 울린다.', k:'fix', dc:24,
      ok:`종 몸통을 외투로 감고 추만 살렸다. 치니 둔탁한 반 소리가 났다.<br><br>위쪽 권양실에는 닿고, 정원 멀리까지는 못 가는 소리. 종의 사정거리를 자른 것이다.<br>승강기가 내려오는 동안 수풀은 조용했다. 반 소리는 반 거리만 간다. 신호의 크기는 조절하는 것이다. 언제나.`,
      ng:`감은 외투가 추에 씹혔다. 반 소리 대신 찢어지는 쇳소리가 났다.<br><br>둔탁한 종소리보다 훨씬 멀리 가는 소리였다.<br>수풀 세 군데가 일렁였다. 승강기가 내려오는 동안 다섯이 등을 맞대고 섰다. 문이 열리는 소리와 풀 갈라지는 소리가 거의 동시였다. 외투는 종에 두고 탔다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 종 대신 쇠줄을 두드려 위에 몸짓을 보낸다.', k:'bond', dc:25,
      ok:`승강기 쇠줄에 돌을 대고 두드렸다. 쇠줄은 위로만 울린다. 세로로 선 전선 같은 것이다.<br><br>권양실 쪽에서 쇠줄이 마주 울렸다. 위에 사람이든 기계든, 알아들은 것이다.<br>승강기가 내려왔다. 정원은 끝까지 아무것도 몰랐다. 종은 만인의 신호고 쇠줄은 둘만의 신호다. 신호수는 좁은 쪽을 고른다.`,
      ng:`쇠줄 두드림이 약했는지 위쪽이 한참 조용했다.<br><br>기다리다 결국 종을 쳤다. 제일 피하고 싶던 수를 제일 늦게 쓴 꼴이다.<br>종소리를 듣고 수풀이 깨어나는 시간과 승강기가 내려오는 시간의 경주가 됐다. 승강기가 반 걸음 이겼다. 문이 닫힐 때 바깥 발톱 소리가 승강장을 긁었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-19, spirit:-21 } },
    { l:'③ 제 울림대로 치고, 종 곁에서 버틴다.', k:'steady', dc:26,
      doom:{ title:'만찬 종', what:'수풀 속으로 끌려갑니다', dc:19, sec:38,
        text:`종을 제 소리로 쳤다. 정직한 호출. 그리고 종 곁에 서서 승강기를 기다렸다.<br><br>정원의 대답이 승강기보다 빨랐다.<br><br>수풀이 세 방향에서 갈라졌다. 종 친 사람이 종 곁에 있었다. 만찬 종을 치고 식탁 위에 서 있었던 것이다. 첫 이빨이 외투 자락을 물고 수풀로 당긴다.`,
        dieText:`승강기는 제시간에 내려왔다. 네 사람이 탔다.<br><br>문이 닫히기 전까지 수풀 쪽에 등불을 비췄지만 돌아온 것은 없었다.<br>그 종에는 지금 안내판이 하나 더 붙어 있다. 급히 긁어 쓴 글씨로 — 치고 나서 반드시 떨어져 있을 것.` },
      ok:`종을 제 소리로 치고, 바로 종에서 서른 걸음 떨어진 바위 뒤로 다 같이 물렸다.<br><br>정원의 것들이 종 주위로 모여들었다. 소리의 임자를 찾아서. 빈 종만 맴돌았다.<br>승강기가 내려오자 그것들이 쇠 소리에 주춤한 틈에 반대쪽에서 달려 탔다. 종을 미끼로 쓴 셈이다. 신호가 미끼가 되는 건 한 끗 차이다. 그 한 끗은 서른 걸음이었다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S2', t:'횃불 시계',
  x:`둘이 관리인 오두막으로 열쇠를 받으러 가고, 셋이 승강장을 지키기로 했다.<br><br>
    헤어지면 신호가 필요하고, 이 정원에서 소리 신호는 사치다.<br>
    남는 것은 시간 약속. 그런데 시계가 없다.<br><br>
    탈 것의 길이는 시간이다. 신호수는 불로도 시계를 만든다.`,
  o:[
    { l:'① 길이가 다른 홰 세 개로 시계를 만든다.', k:'fix', dc:25,
      ok:`같은 굵기 나무를 세 뼘, 두 뼘, 한 뼘으로 잘라 셋에게 나눴다. 같은 불로 붙이면 타는 시간이 한 식경씩 어긋난다.<br><br>세 뼘이 다 타면 돌아올 시간. 두 뼘이 다 타면 늦는 것. 한 뼘까지 타면 버리고 떠나라는 약속.<br>둘은 두 뼘 반에 돌아왔다. 열쇠를 들고. 홰 시계는 반 뼘을 남기고 꺼졌다. 쓸모를 다한 시계가 제일 좋은 시계다.`,
      ng:`승강장 쪽 홰가 바람에 빨리 탔다. 시계가 서로 어긋났다.<br><br>셋은 늦었다고 믿고 둘은 이르다고 믿었다. 승강장의 셋이 먼저 종 앞까지 갔다가 돌아오는 소동이 났다.<br>소동의 발소리가 수풀을 한 번 깨웠다. 바람 부는 날의 불 시계는 바람까지 셈해야 한다. 수업료는 간 떨어진 값으로 치렀다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-19 } },
    { l:'② 헤어지지 않게 길을 다시 짠다 — 시계가 필요 없게.', k:'bond', dc:25,
      ok:`쪼개는 안을 접고 다섯이 다 같이 오두막을 들러 승강장으로 도는 길을 짰다.<br><br>반 시진 더 걷는 길. 그 값으로 신호도 시계도 약속도 다 필요 없어졌다.<br>제일 좋은 신호 체계는 신호가 필요 없는 동선이다. 신호수가 신호를 지우는 날이 제일 일 잘한 날이라는 걸, 스승이 왜 입버릇처럼 말했는지 알았다.`,
      ng:`같이 도는 길이 하필 몰이 길과 겹쳤다. 다섯이 한꺼번에 풀숲에 엎드리는 일이 두 번.<br><br>반 시진이 한 시진이 됐다.<br>오두막에 닿았을 때 관리인이 혀를 찼다. 다섯이 우르르 다니면 눈에 띄는 게 당연하다고. 뭉치는 값과 쪼개는 값, 오늘은 뭉치는 값이 더 들었다. 그래도 치를 만한 값이었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S2', t:'마지막 신호',
  x:`승강기 문이 열렸다. 다만 다섯이 흩어져 있다. 물가에 둘, 바위에 하나, 수풀 가장자리에 하나.<br><br>
    크게 부르면 정원이 다 듣는다. 하나씩 데리러 가면 문이 닫힌다.<br>
    신호 하나로 넷을 불러야 한다. 지금, 조용히, 이리로 — 그 전부가 담긴 하나.<br><br>
    신호수 생활의 전부가 이 한 번에 걸렸다.`,
  o:[
    { l:'① 약속해 둔 단 하나의 신호를 보낸다.', k:'bond', dc:25, wake:1,
      ok:`혀를 한 번 차고, 등불을 가슴 앞에서 두 번 가렸다. 처음 정원에 내려온 날 약속한 그 신호. 지금, 조용히, 이리로.<br><br>물가의 둘이 물풀처럼 낮게 움직였다. 바위의 하나가 미끄러져 내려왔다. 수풀 가장자리의 하나가 뒷걸음으로 빠졌다.<br>넷이 소리 하나 없이 모여들어 탔다. 문이 닫혔다.<br><br>천 가지 신호를 배워 결국 하나에 닿았다. 지금, 조용히, 이리로. 신호수가 평생 보내는 말은 사실 이 한마디라는 것. 그걸 알았으니 이제 어디서든 신호수다.`,
      ng:`신호는 보냈는데 수풀 가장자리의 하나가 등을 돌리고 있었다. 못 본 것이다.<br><br>셋이 타고도 문을 잡고 기다렸다. 다시 보낼 신호가 마땅치 않았다.<br>결국 바위의 팀원이 조약돌을 던져 어깨를 맞혔다. 투박했지만 통했다. 마지막 신호의 예비 신호까지 정해 두는 것. 다음 약속에는 그것까지 넣기로 했다.`,
      win:{ exp:25, dream:4 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 신호를 접고 한 사람씩 몸으로 데리러 간다.', k:'steady', dc:26,
      ok:`문에 제일 가까운 팀원에게 문을 맡기고, 낮은 걸음으로 하나씩 데리러 갔다.<br><br>물가 둘, 바위 하나, 수풀 가장자리 하나. 네 번의 왕복.<br>마지막 왕복에서 수풀이 한 번 일렁였지만 걸음을 안 바꿨다. 뛰는 등은 쫓기는 등이다. 걷는 등으로 돌아와 탔다. 신호 없는 날의 신호수는 발로 신호를 쓴다.`,
      ng:`세 번째 왕복에서 수풀의 것과 길이 겹쳤다. 데리러 간 팀원을 끌고 구르다시피 돌아왔다.<br><br>네 번째는 그 팀원이 제 발로 뛰어왔다. 기다릴 처지가 아니게 된 것이다.<br>문이 닫힐 때 바깥에서 풀 눕는 소리가 길게 났다. 몸 신호는 확실한 대신 비싸다. 오늘 값은 외투 한 벌과 간 반쪽이었다.`,
      win:{ exp:16, dream:3 }, lose:{ hp:-30, mind:-16 } }
  ] }

]);
